struct GameplayTerrainFrameCache {
    std::vector<u16> pixels;
    i32 camera_x = 0;
    i32 camera_y = 0;
    u32 animation_slot = 0;
    u32 width = 0;
    u32 height = 0;
    bool pixel_mode_555 = false;
    bool valid = false;
};

struct GameplayMinimapBaseFrameCache {
    u32 simulation_frame = 0;
    u32 animation_slot = 0;
    u32 map_width_tiles = 0;
    u32 map_height_tiles = 0;
    u32 minimap_width_pixels = 0;
    u32 minimap_height_pixels = 0;
    bool pixel_mode_555 = false;
    bool valid = false;
};

GameplayTerrainFrameCache g_gameplay_terrain_frame_cache;
GameplayMinimapBaseFrameCache g_gameplay_minimap_base_frame_cache;

void reset_default_gameplay_terrain_frame_cache() {
    // The process-global cache survives the DirectDraw surface lifetime.  Drop
    // the backing pixels as well as the validity bit so a second P2P session
    // cannot restore bytes captured from the previous match if its first
    // terrain pass observes the same camera/animation tuple.
    g_gameplay_terrain_frame_cache = GameplayTerrainFrameCache{};
    g_gameplay_minimap_base_frame_cache = GameplayMinimapBaseFrameCache{};
}

bool restore_default_gameplay_terrain_frame_cache(
    const SpriteRenderTarget& target, i32 camera_x, i32 camera_y,
    u32 animation_slot) {
    const GameplayTerrainFrameCache& cache =
        g_gameplay_terrain_frame_cache;
    if (!cache.valid || target.pixels == nullptr ||
        target.stride_words < target.width ||
        cache.camera_x != camera_x || cache.camera_y != camera_y ||
        cache.animation_slot != animation_slot ||
        cache.width != target.width || cache.height != target.height ||
        cache.pixel_mode_555 != SurfacePixelMode555() ||
        cache.pixels.size() !=
            static_cast<std::size_t>(target.width) * target.height) {
        return false;
    }

    for (u32 y = 0; y < target.height; ++y) {
        std::memcpy(target.pixels +
                static_cast<std::size_t>(y) * target.stride_words,
            cache.pixels.data() +
                static_cast<std::size_t>(y) * target.width,
            static_cast<std::size_t>(target.width) * sizeof(u16));
    }
    return true;
}

void capture_default_gameplay_terrain_frame_cache(
    const SpriteRenderTarget& target, i32 camera_x, i32 camera_y,
    u32 animation_slot) {
    if (target.pixels == nullptr || target.stride_words < target.width ||
        target.width == 0 || target.height == 0) {
        reset_default_gameplay_terrain_frame_cache();
        return;
    }

    GameplayTerrainFrameCache& cache = g_gameplay_terrain_frame_cache;
    cache.pixels.resize(
        static_cast<std::size_t>(target.width) * target.height);
    for (u32 y = 0; y < target.height; ++y) {
        std::memcpy(cache.pixels.data() +
                static_cast<std::size_t>(y) * target.width,
            target.pixels +
                static_cast<std::size_t>(y) * target.stride_words,
            static_cast<std::size_t>(target.width) * sizeof(u16));
    }
    cache.camera_x = camera_x;
    cache.camera_y = camera_y;
    cache.animation_slot = animation_slot;
    cache.width = target.width;
    cache.height = target.height;
    cache.pixel_mode_555 = SurfacePixelMode555();
    cache.valid = true;
}

void queue_default_gameplay_chat_payload(Mode1ChatPayload payload) {
    const std::lock_guard<std::mutex> lock(g_gameplay_chat_mutex);
    g_pending_gameplay_chat_messages.push_back(std::move(payload));
}

void clear_default_gameplay_chat_payloads() {
    const std::lock_guard<std::mutex> lock(g_gameplay_chat_mutex);
    g_pending_gameplay_chat_messages.clear();
}

void sync_default_gameplay_chat_input_hud() {
    const UiOverlayState& overlay = ui_overlay_state();
    GameplayHudSelectedStatus& selected =
        g_runtime.gameplay_hud_text.selected_status;
    selected.active = overlay.chat_active;
    selected.category = static_cast<u8>(std::min<u32>(
        overlay.chat_channel, selected.category_labels.size() - 1u));
    selected.typed_text = overlay.chat_input_text;
#ifdef _WIN32
    if (overlay.chat_active) {
        selected.typed_text += CurrentImeCompositionText();
    }
#endif
    selected.extra_text.clear();
    selected.extra_text_active = false;
}

void drain_default_gameplay_chat_payloads(u32 current_tick_ms) {
    std::vector<Mode1ChatPayload> pending;
    {
        const std::lock_guard<std::mutex> lock(g_gameplay_chat_mutex);
        pending.swap(g_pending_gameplay_chat_messages);
    }
    if (pending.empty()) {
        return;
    }

    constexpr u8 kDynamicChatColorIndex = 0xfeu;
    SetTextColorRef(kDynamicChatColorIndex, kMode1ChatColorWhite);
    SetTextColorPixel(kDynamicChatColorIndex,
        SurfacePixelMode555() ? 0x7fffu : 0xffffu);
    GameplayHudTextState& hud = g_runtime.gameplay_hud_text;
    hud.current_tick_ms = current_tick_ms;
    for (Mode1ChatPayload& payload : pending) {
        QueueGameplayTimedChatNotification(hud,
            std::move(payload.primary_text), std::move(payload.secondary_text),
            kDynamicChatColorIndex, kDynamicChatColorIndex);
    }
}

GameplayLogicalSurfaceSize resolve_active_gameplay_logical_surface_size() {
    const DirectDrawRuntimeState& draw = direct_draw_state();
    const GameplayDisplayState& requested = g_runtime.gameplay_display_state;
    return ResolveGameplayLogicalSurfaceSize(draw.active, draw.width, draw.height,
        requested.width, requested.height);
}

