void clear_default_replay_playback_runtime(const char* reason) {
    ReplayRecordingState& replay = replay_recording_state();
    const bool playback_was_active = replay.playback_mode;
    // A replay can own both its sibling MP3 and scenario-triggered playlist
    // streams.  Ordinary leave requests return through the session wrapper
    // without visiting handle_replay_session_leave, and another teardown can
    // clear playback_mode before this final boundary.  Close both backends
    // unconditionally while this call still identifies a replay boundary.
    CloseAllMilesEffectPlaylistStreams();
    CloseDirectMilesMusic();
    ClearReplayPlaybackState(replay);
    P2PGameSessionStartState& p2p = g_runtime.p2p_session_start_state;
    p2p.direct_music_started = false;
    p2p.direct_music_paused = false;
    SetReplayControlsEnabled(false);
    SetRankerMainWindowScenarioAiProfileOverride(false);
    if (playback_was_active) {
        append_startup_log("replay playback state cleared reason=%s",
            reason != nullptr ? reason : "unspecified");
    }
}

void default_link_start_game(LinkLobbyState& state) {
    // A Link-lobby start is always a live session.  Original replay teardown
    // ends at 0x004d93e8 by clearing DAT_01242a20; enforce the same invariant
    // here as a boundary guard so a prior replay can never override the room's
    // prepared map or route the frame gate through replay packet playback.
    if (replay_recording_state().playback_mode) {
        clear_default_replay_playback_runtime("live-link-session-start");
    }
    const u32 mode = state.mode >= 0 ?
        static_cast<u32>(state.mode) : g_runtime.frontend_mode;
    g_runtime.frontend_mode = mode;
    g_runtime.gameplay_launch_source =
        g_runtime.p2p_command_line_flow_active ?
        GameplayLaunchSource::command_line_p2p :
        GameplayLaunchSource::link_lobby;
    g_runtime.link_lobby_start_parameters_pending =
        !state.start_parameter_payload.empty();
    append_startup_log("link start_game mode=%lu start_payload=%zu map=%s",
        static_cast<unsigned long>(mode), state.start_parameter_payload.size(),
        state.map_file_name.c_str());
    if (mode == 0) {
        // WizardNet keeps its authenticated lobby alive underneath the Link
        // room so Cancel can return without logging in again.  Once the match
        // starts that retained native child must be hidden; otherwise
        // destroying the Link room merely exposes the lobby over the running
        // DirectDraw gameplay session.
        OnlineLobbyState& online = online_lobby_state();
        if (online.window != nullptr && IsWindow(online.window) &&
            state.main_window == online.window) {
            ShowWindow(online.window, SW_HIDE);
            append_startup_log("wizardnet lobby hidden for gameplay");
        }
    }
    SetActiveNetworkTransportMode(static_cast<i32>(mode));
    queue_default_gameplay_session_transition(state.main_window, mode);
}

void default_link_queue_packet(LinkLobbyState&, const void* packet,
    i32 byte_count) {
    if (packet == nullptr || byte_count <= 0) {
        return;
    }
    PrepareAndQueueLegacyAsyncTcpSend(FrontendAsyncTcpSocket0(),
        const_cast<void*>(packet), byte_count);
}

bool default_link_finalize_start_sync(LinkLobbyState& state) {
    return SendLinkLobbyStartParametersPacket(state);
}

void default_link_shutdown_network(LinkLobbyState& state) {
    if (state.mode == 0 &&
        (state.relay_game_id != 0 || WizardNetRelayEnabled())) {
        const u32 relay_game_id = state.relay_game_id != 0 ?
            state.relay_game_id : wizardnet_relay_state().game_id;
        QueueWizardNetRelayLeaveForGame(relay_game_id);
        state.relay_game_id = 0;
    }
    if (state.mode >= 0 && state.mode < 3) {
        // A Link room owns both the direct-P2P listen socket and its UDP
        // route.  Merely closing the TCP records leaves the transport marked
        // initialized and retains the UDP socket across the return to
        // WizardNet.  Fully retire both transports so an immediate second
        // host attempt starts with fresh sockets and window notification
        // routes.
        ShutdownLegacyTcpNetworking();
        ShutdownLegacyUdpNetworking();
        state.shared_peer_socket = INVALID_SOCKET;
        state.pending_join_socket = INVALID_SOCKET;
        state.player_sockets.fill(INVALID_SOCKET);
    } else {
        CloseAllLegacySocketRecords();
    }
    if (state.map_download_state == 2 && !state.prepared_map_path.empty()) {
        DeleteFileA(state.prepared_map_path.c_str());
        state.map_download_state = 0;
    }
}

void reset_default_p2p_room_transport_after_game() {
    // The original direct-P2P outer loop either keeps the current room alive
    // or tears its transport down before returning to the room browser.  The
    // reconstructed flow returns to the browser, so retaining the previous
    // listen socket makes the next hosted room fail its bind on the same port.
    ShutdownLegacyTcpNetworking();
    ShutdownLegacyUdpNetworking();

    LinkLobbyState& link = link_lobby_state();
    link.shared_peer_socket = INVALID_SOCKET;
    link.pending_join_socket = INVALID_SOCKET;
    link.player_sockets.fill(INVALID_SOCKET);

    P2PLobbyState& p2p = p2p_lobby_state();
    p2p.join_pending = false;
    p2p.join_socket = INVALID_SOCKET;
    append_startup_log("post-game direct-p2p room transport reset");
}

void configure_link_lobby_callbacks(LinkLobbyState& state) {
    load_default_p2p_ports(state.default_tcp_port, state.default_udp_port);
    ConnectFrontendState& connect = connect_frontend_state();
    LoadConnectFrontendConfiguration(connect);
    state.default_peer_probe_port =
        static_cast<u16>(connect.configuration.server_port);
    std::snprintf(state.default_peer_probe_host.data(),
        state.default_peer_probe_host.size(), "%s",
        connect.configuration.default_server_address.c_str());
    state.async_tcp_socket = &FrontendAsyncTcpSocket0();
    state.callbacks.open_connect_frontend = default_link_open_connect;
    state.callbacks.open_online_lobby = default_link_open_online;
    state.callbacks.open_p2p_lobby = default_link_open_p2p;
    state.callbacks.open_ipx_lobby = default_link_open_ipx;
    state.callbacks.open_replay_or_observer_lobby =
        default_link_resume_single_player;
    state.callbacks.start_game = default_link_start_game;
    state.callbacks.shutdown_network = default_link_shutdown_network;
    state.callbacks.show_message = nullptr;
    state.callbacks.queue_packet = default_link_queue_packet;
    state.callbacks.finalize_start_sync = default_link_finalize_start_sync;
}

