template <std::size_t N>
void copy_result_text(std::array<char, N>& dest, const char* text) {
    std::snprintf(dest.data(), dest.size(), "%s", text != nullptr ? text : "");
}

P2PGameEndReason p2p_result_end_reason_from_modal_result(int result) {
    if (result == 0) {
        return P2PGameEndReason::NoError;
    }
    if (result >= 0 && result <= static_cast<int>(P2PGameEndReason::NetworkError)) {
        return static_cast<P2PGameEndReason>(result);
    }
    return P2PGameEndReason::NoGameplayAbort;
}

std::string default_p2p_result_player_name(
    u32 owner, const P2PGameSessionStartState& p2p) {
    if (owner < g_runtime.gameplay_startup_state.owner_display_names.size() &&
        !g_runtime.gameplay_startup_state.owner_display_names[owner].empty()) {
        return g_runtime.gameplay_startup_state.owner_display_names[owner];
    }
    if (owner < p2p.network_index_by_owner.size()) {
        const u32 network_index = p2p.network_index_by_owner[owner];
        if (network_index < p2p.network_player_count &&
            network_index < p2p.player_names.size() &&
            p2p.player_names[network_index][0] != '\0') {
            return p2p.player_names[network_index].data();
        }
    }

    char fallback[32]{};
    std::snprintf(fallback, sizeof(fallback), "Player %u", owner + 1);
    return fallback;
}

bool default_p2p_result_slot_playing(const PlayerSlotRuntimeState& players, u32 owner) {
    return owner < players.slot_states.size() &&
        players.slot_states[owner] != static_cast<u8>(PlayerSlotState::disabled);
}

void default_gameplay_flow_write_p2p_result_file(
    GameplaySessionFlowState& state, int result) {
    P2PGameResultFileInput input{};
    const PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;
    const GameplaySessionStartupState& startup = g_runtime.gameplay_startup_state;
    const P2PGameSessionStartState& p2p = g_runtime.p2p_session_start_state;
    const bool normal_end = result == 0;
    const u32 network_player_count = std::min<u32>(
        p2p.network_player_count, static_cast<u32>(input.players.size()));

    input.version_packed = LoadTrcRecord9Value();
    input.local_player_slot = std::min<u32>(
        players.local_player_slot, static_cast<u32>(input.players.size() - 1));
    input.active_player_count = std::min<u32>(
        std::max<u32>(players.active_slot_count, 1),
        static_cast<u32>(input.players.size()));
    input.connected_player_count = network_player_count != 0 ?
        network_player_count : input.active_player_count;

    for (u32 owner = 0; owner < input.players.size(); ++owner) {
        P2PGameResultPlayer& player = input.players[owner];
        const std::string name = default_p2p_result_player_name(owner, p2p);
        copy_result_text(player.result_name, name.c_str());
        copy_result_text(player.network_name, name.c_str());
        player.faction = owner < startup.owner_faction_ids.size() ?
            startup.owner_faction_ids[owner] : 0;
        player.selected_tribe = owner < startup.owner_tribe_ids.size() ?
            startup.owner_tribe_ids[owner] : player.faction;
        player.ally_mask = owner < players.owner_relation_masks.size() ?
            players.owner_relation_masks[owner] : 0;
        player.playing = default_p2p_result_slot_playing(players, owner);
    }

    if (!normal_end && network_player_count != 0) {
        for (u32 index = 0; index < network_player_count; ++index) {
            P2PGameResultPlayer& player = input.players[index];
            copy_result_text(player.network_name, p2p.player_names[index].data());
            if (player.result_name[0] == '\0') {
                copy_result_text(player.result_name, p2p.player_names[index].data());
            }
            player.playing = p2p.player_names[index][0] != '\0';
        }
    }

    input.client_player_name = input.players[input.local_player_slot].result_name.data();
    const P2PGameWinResult win_result = normal_end ?
        static_cast<P2PGameWinResult>(state.p2p_win_result) :
        P2PGameWinResult::Draw;
    WriteP2PGameResultFile(input, win_result,
        p2p_result_end_reason_from_modal_result(result));
}

void default_gameplay_flow_set_cursor(GameplaySessionFlowState&) {
    g_runtime.hide_cursor = false;
    if (g_runtime.peer_startup_cursor_transition_active &&
        !g_runtime.peer_startup_software_cursor_enabled) {
        // The Link room has gone away, but the worker has not produced a game
        // frame yet. Keep the native game cursor visible while archive,
        // definition and unit startup work owns the DirectDraw/D3D resources.
        SetGameCursorIndex(gameplay_loop_state().current_cursor_index);
        SetGameCursorPresentationSuppressed(true);
        SetCursor(GetFrontendGameCursor());
        return;
    }
    SetGameCursorPresentationSuppressed(false);
    SetGameCursorIndex(gameplay_loop_state().current_cursor_index);
    ShowGameCursor();
}

void default_gameplay_flow_hide_cursor(GameplaySessionFlowState&) {
    g_runtime.hide_cursor = true;
    HideGameCursor();
}

void default_gameplay_flow_show_cursor(GameplaySessionFlowState&) {
    g_runtime.hide_cursor = false;
    if (g_runtime.peer_startup_cursor_transition_active &&
        !g_runtime.peer_startup_software_cursor_enabled) {
        SetGameCursorPresentationSuppressed(true);
        SetCursor(GetFrontendGameCursor());
        return;
    }
    SetGameCursorPresentationSuppressed(false);
    ShowGameCursor();
}

constexpr u32 kPeerStartupCursorWarmupPresentationCount = 2;

void begin_default_peer_startup_cursor_transition() {
    g_runtime.peer_startup_cursor_transition_active =
        GameplayLaunchUsesLivePeerConnection(g_runtime.gameplay_launch_source);
    g_runtime.peer_startup_software_cursor_enabled = false;
    g_runtime.peer_startup_cursor_presentations_remaining = 0;
    if (!g_runtime.peer_startup_cursor_transition_active) {
        return;
    }

    // The 25 ms legacy multimedia timer already supplies the original 1 ms
    // scheduler resolution. The remaining peer-only hitch was a presentation
    // ownership problem: WM_MOUSEMOVE could synchronously present while the
    // gameplay worker was materializing the first frame. Keep the native
    // cursor independent until those resources are ready, and coalesce input
    // only across the first two D3D warm-up presentations.
    SetContinuousGameplayCursorPresentationActive(true);
    SetGameCursorPresentationSuppressed(true);
    SetCursor(GetFrontendGameCursor());
    append_startup_log("peer-startup cursor: native transition begin source=%lu",
        static_cast<unsigned long>(g_runtime.gameplay_launch_source));
}

void enable_default_peer_startup_software_cursor() {
    if (!g_runtime.peer_startup_cursor_transition_active ||
        g_runtime.peer_startup_software_cursor_enabled) {
        return;
    }

    g_runtime.peer_startup_software_cursor_enabled = true;
    g_runtime.peer_startup_cursor_presentations_remaining =
        kPeerStartupCursorWarmupPresentationCount;
    SetGameCursorIndex(gameplay_loop_state().current_cursor_index);
    SetGameCursorPresentationSuppressed(false);
    const InputState& input = input_state();
    SetGameCursorPointerPosition(
        static_cast<i32>(input.mouse_x), static_cast<i32>(input.mouse_y));
    ShowGameCursor();
    set_main_window_system_cursor_for_lock_state();
    append_startup_log("peer-startup cursor: software cursor ready warmup=%lu",
        static_cast<unsigned long>(
            g_runtime.peer_startup_cursor_presentations_remaining));
}

void finish_default_peer_startup_cursor_transition() {
    if (!g_runtime.peer_startup_cursor_transition_active) {
        return;
    }
    g_runtime.peer_startup_cursor_transition_active = false;
    g_runtime.peer_startup_software_cursor_enabled = false;
    g_runtime.peer_startup_cursor_presentations_remaining = 0;
    SetContinuousGameplayCursorPresentationActive(false);
    append_startup_log("peer-startup cursor: transition complete");
}

void advance_default_peer_startup_cursor_presentation() {
    if (!g_runtime.peer_startup_cursor_transition_active ||
        !g_runtime.peer_startup_software_cursor_enabled) {
        return;
    }
    if (g_runtime.peer_startup_cursor_presentations_remaining > 1) {
        --g_runtime.peer_startup_cursor_presentations_remaining;
        return;
    }
    finish_default_peer_startup_cursor_transition();
}

void default_gameplay_flow_frame_boundary(GameplaySessionFlowState&) {
    YieldBackgroundWorkerThreadSlice();
}

void default_gameplay_flow_send_p2p_game_flow_modal(GameplaySessionFlowState& state) {
    if (g_runtime.main_window != nullptr && IsWindow(g_runtime.main_window)) {
        SendMessageA(g_runtime.main_window, WM_USER + 8, 0, 2);
        return;
    }

    state.modal_result = GameplayModalResult::ContinueNetwork;
    state.worker_modal_pending = 0;
}

void default_gameplay_flow_immediate_dialog_sound(GameplaySessionFlowState& state) {
    HandleImmediateDialogGameplaySound(g_runtime.gameplay_sound,
        state.immediate_dialog_sound_selector,
        state.immediate_dialog_sound_world_delta);
}

void default_gameplay_flow_reset_input(GameplaySessionFlowState&) {
    ResetInputState();
}

void default_gameplay_flow_cleanup_after_close(GameplaySessionFlowState&) {
    ResetInputState();
}

void default_gameplay_flow_final_worker_cleanup(GameplaySessionFlowState&) {
    if (g_runtime.worker_thread != nullptr &&
        g_runtime.worker_thread_id == GetCurrentThreadId()) {
        ExitBackgroundWorkerThread();
        return;
    }
    ResetInputState();
}

void default_gameplay_flow_release_loaded_resources(GameplaySessionFlowState& state) {
    if (state.loaded_resource_base_owned &&
        state.loaded_resource_base != kInvalidResourceEntry) {
        ReleaseResourceEntriesFrom(state.loaded_resource_base);
    }
    if (state.loaded_palette_slot != kInvalidPaletteCacheSlot) {
        // FUN_0042dc60/FUN_0042e1e0 close the save/load child frame by
        // rewinding both parallel stack allocators.  Keeping only the image
        // rewind made each later visit consume another palette slot and could
        // eventually bind unrelated reused colors to modal sprites.
        ReleasePaletteCacheSlotsFrom(state.loaded_palette_slot);
    }
    state.loaded_resource_base = kInvalidResourceEntry;
    state.loaded_palette_slot = kInvalidPaletteCacheSlot;
    state.loaded_resource_base_owned = false;
}

void default_gameplay_flow_shutdown_primary_music_policy(GameplaySessionFlowState&) {
    ShutdownPrimaryMilesMusicPolicy();
}

void default_gameplay_flow_set_primary_music_policy_mode(
    GameplaySessionFlowState&, u32 mode) {
    set_default_primary_miles_music_policy_mode(mode);
}

void default_gameplay_display_reset_overlay() {
    g_runtime.suppress_paint = false;
}

void default_gameplay_display_frame_boundary() {
    YieldBackgroundWorkerThreadSlice();
}

void default_gameplay_display_configure_surfaces(u32 width, u32 height, u32 color_depth) {
    const HRESULT result = ConfigureDirectDrawSurfaces(g_runtime.main_window,
        static_cast<int>(width), static_cast<int>(height),
        static_cast<int>(color_depth));
    if (FAILED(result)) {
        UpdateDirectDrawErrorString(result);
        g_runtime.directx_initialized = false;
        const DirectDrawRuntimeState& draw = direct_draw_state();
        append_startup_log(
            "gameplay display surface configure failed hr=0x%08lx name=%s requested=%ux%ux%u",
            static_cast<unsigned long>(result),
            draw.last_error_name.empty() ? "unknown" : draw.last_error_name.c_str(),
            width, height, color_depth);
        char failure[224]{};
        std::snprintf(failure, sizeof(failure),
            "Gameplay display surface configure failed: 0x%08lx (%s), requested %ux%ux%u.\n",
            static_cast<unsigned long>(result),
            draw.last_error_name.empty() ? "unknown" : draw.last_error_name.c_str(),
            width, height, color_depth);
        OutputDebugStringA(failure);
        return;
    }

    // cnc-ddraw recomputes scale/unscale and restores the same logical cursor
    // whenever the DirectDraw mode changes (notably 800x600 <-> 640x480).
    refresh_main_window_cursor_confinement(g_runtime.main_window);
    const DirectDrawRuntimeState& draw = direct_draw_state();
    append_startup_log("gameplay display surface configured %ux%ux%u requested=%ux%ux%u",
        draw.width, draw.height, draw.color_depth, width, height, color_depth);
    char text[160]{};
    std::snprintf(text, sizeof(text),
        "Gameplay display surface configured: %ux%ux%u (requested %ux%ux%u).\n",
        draw.width, draw.height, draw.color_depth, width, height, color_depth);
    OutputDebugStringA(text);
}

bool gameplay_modal_ui_is_active(const GameplayModalUiState& state) {
    return state.main_menu_active || state.scenario_message_active ||
        state.exit_surrender_active || state.options_active ||
        state.relation_mask_active || state.observer_mask_active ||
        state.wait_dialog_active || state.replay_modal_pending;
}

bool default_gameplay_input_can_skip_input_drain(GameplayInputActionState& state) {
    const bool modal_active = gameplay_modal_ui_is_active(gameplay_modal_ui_state());
    state.modal_route_blocked = modal_active;
    return modal_active;
}

void configure_default_gameplay_input_action_context(
    GameplayInputActionState& state);
void install_default_gameplay_session_flow_callbacks(GameplaySessionFlowState& state);

GameplaySessionFlowState& prepare_default_modal_session_flow() {
    GameplaySessionFlowState& flow = g_runtime.gameplay_session_flow;
    install_default_gameplay_session_flow_callbacks(flow);
    for (std::size_t index = 0; index < flow.save_slots.size(); ++index) {
        if (!flow.save_slots[index].path.empty()) {
            continue;
        }
        char path[MAX_PATH]{};
        std::snprintf(path, sizeof(path), "Save\\_Jw2_%02zu.sav", index);
        flow.save_slots[index].path = path;
    }
    return flow;
}

GameplayModalSaveSlotState modal_save_slot_state_from_flow(
    GameplaySaveSlotStatus status) {
    switch (status) {
    case GameplaySaveSlotStatus::Valid:
        return GameplayModalSaveSlotState::Occupied;
    case GameplaySaveSlotStatus::Invalid:
        return GameplayModalSaveSlotState::Invalid;
    case GameplaySaveSlotStatus::Empty:
    default:
        return GameplayModalSaveSlotState::Empty;
    }
}

void sync_default_modal_save_slots_from_session_flow(
    GameplayModalUiState& modal, const GameplaySessionFlowState& flow) {
    for (std::size_t index = 0;
         index < modal.save_slots.size() && index < flow.save_slots.size(); ++index) {
        modal.save_slots[index].state =
            modal_save_slot_state_from_flow(flow.save_slots[index].status);
        modal.save_slots[index].label = flow.save_slots[index].title;
    }
}

std::string default_gameplay_modal_player_display_name(u32 owner) {
    if (owner < g_runtime.gameplay_startup_state.owner_display_names.size() &&
        !g_runtime.gameplay_startup_state.owner_display_names[owner].empty()) {
        return g_runtime.gameplay_startup_state.owner_display_names[owner];
    }
    char name[32]{};
    std::snprintf(name, sizeof(name), "Player %u", owner + 1);
    return name;
}

void sync_default_gameplay_modal_players(GameplayModalUiState& modal) {
    const PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;
    const Mode1ReliableRuntimeState& reliable = mode1_reliable_state();
    if (reliable.initialized) {
        modal.wait_required_packet_count = reliable.sync_threshold;
    }
    for (u32 owner = 0; owner < modal.players.size(); ++owner) {
        GameplayModalPlayerSlot& row = modal.players[owner];
        row.slot_state = owner < players.slot_states.size() ?
            players.slot_states[owner] : static_cast<u8>(PlayerSlotState::disabled);
        row.modal_pause_uses_remaining =
            owner < mode1_gameplay_packet_dispatch_state()
                        .player_modal_pause_uses_remaining.size()
            ? mode1_gameplay_packet_dispatch_state()
                  .player_modal_pause_uses_remaining[owner]
            : 0;
        row.relation_mask = owner < players.owner_relation_masks.size() ?
            players.owner_relation_masks[owner] : 0;
        row.visibility_mask = owner < players.owner_visibility_masks.size() ?
            players.owner_visibility_masks[owner] : 0;
        row.display_name = default_gameplay_modal_player_display_name(owner);
        if (reliable.initialized && owner < kMode1ReliableChannelCount) {
            modal.wait_packet_counts[owner] = reliable.subtype10_counts[owner];
            modal.wait_elapsed_ms[owner] = reliable.wait_budget[owner];
            row.wait_ready = reliable.wait_budget[owner] == 0;
        }
    }
    if (!modal.relation_mask_active && modal.local_player_index < 32) {
        modal.relation_observer_flag =
            ((players.global_active_slot_mask >> modal.local_player_index) & 1u) != 0;
    }
}

void sync_default_gameplay_player_session_record() {
    std::vector<u8>* record =
        MutableGameplaySessionLoadedRecord(kGameplaySessionPlayerRecordIndex);
    if (record == nullptr ||
        record->size() < kGameplaySessionPlayerRecordBytes) {
        return;
    }

    const GameplaySessionStartupState& startup =
        g_runtime.gameplay_startup_state;
    const PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;
    const UnitLifecycleContext* lifecycle = startup.lifecycle;

    write_default_session_buffer_u32(*record,
        kSessionPlayerRecordLocalOwnerOffset,
        NormalizePlayerOrNoLocalSlot(players.local_player_slot));

    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        const std::size_t name_offset =
            kSessionPlayerRecordNameBaseOffset +
            static_cast<std::size_t>(owner) *
                kSessionPlayerRecordNameStride;
        std::fill_n(record->begin() + name_offset,
            kSessionPlayerRecordNameStride, u8{0});
        const std::string name = default_gameplay_modal_player_display_name(owner);
        const std::size_t name_bytes = std::min<std::size_t>(
            name.size(), kSessionPlayerRecordNameStride - 1);
        std::copy_n(name.begin(), name_bytes,
            record->begin() + name_offset);

        const GameplayScenarioOwnerSlot& slot = startup.owner_slots[owner];
        write_default_session_buffer_u32(*record,
            kSessionPlayerRecordFactionBaseOffset + owner * sizeof(u32),
            slot.faction_id);
        write_default_session_buffer_u32(*record,
            kSessionPlayerRecordSlotStateBaseOffset + owner * sizeof(u32),
            players.slot_states[owner]);
        const std::size_t start_offset =
            kSessionPlayerRecordStartCoordinateBaseOffset +
            static_cast<std::size_t>(owner) *
                kSessionPlayerRecordStartCoordinateStride;
        write_default_session_buffer_u32(
            *record, start_offset, static_cast<u32>(slot.start_x));
        write_default_session_buffer_u32(
            *record, start_offset + sizeof(u32),
            static_cast<u32>(slot.start_y));
    }

    for (u32 owner = 0; owner < kPlayerOwnerResourceSlots; ++owner) {
        const std::size_t resource_offset =
            static_cast<std::size_t>(owner) * sizeof(u32);
        const u32 primary = lifecycle != nullptr &&
                owner < lifecycle->owner_primary_resources.size()
            ? lifecycle->owner_primary_resources[owner]
            : players.owner_primary_resources[owner];
        const u32 secondary = lifecycle != nullptr &&
                owner < lifecycle->owner_secondary_resources.size()
            ? lifecycle->owner_secondary_resources[owner]
            : players.owner_secondary_resources[owner];
        write_default_session_buffer_u32(*record,
            kSessionPlayerRecordOwnerResourcePrimaryBaseOffset +
                resource_offset,
            primary);
        write_default_session_buffer_u32(*record,
            kSessionPlayerRecordOwnerResourceSecondaryBaseOffset +
                resource_offset,
            secondary);
        write_default_session_buffer_u32(*record,
            kSessionPlayerRecordOwnerResourceAuxBaseOffset +
                resource_offset,
            players.owner_aux_resources[owner]);
    }
}

void sync_default_gameplay_movement_layer_record(
    u32 relative_record, u32 UnitMovementCell::* field) {
    std::vector<u8>* record = MutableGameplaySessionLoadedRecord(relative_record);
    const UnitMovementMap& map = g_runtime.gameplay_movement_context.map;
    if (record == nullptr || record->size() < sizeof(u32) || map.cells.empty()) {
        return;
    }

    const u32 record_cells = static_cast<u32>(
        std::min<std::size_t>(record->size() / sizeof(u32),
            std::numeric_limits<u32>::max()));
    for (u32 y = 0; y < map.height; ++y) {
        for (u32 x = 0; x < map.width; ++x) {
            const u32 cell = UnitMovementMapTileIndex(map, x, y);
            if (cell >= record_cells || cell >= map.cells.size()) {
                continue;
            }
            write_default_session_buffer_u32(
                *record, static_cast<std::size_t>(cell) * sizeof(u32),
                map.cells[cell].*field);
        }
    }
}

void sync_default_gameplay_movement_map_session_records() {
    sync_default_gameplay_movement_layer_record(
        kGameplayScenarioMapLayerRecordIndex, &UnitMovementCell::flags);
    sync_default_gameplay_movement_layer_record(
        kGameplayMapSourceLayerRecordIndex, &UnitMovementCell::alternate_flags);
    sync_default_gameplay_movement_layer_record(
        kGameplayMapEffectLayerRecordIndex, &UnitMovementCell::visibility_flags);
}

void sync_default_gameplay_unit_pool_list_session_records() {
    std::vector<u8>* header = MutableGameplaySessionLoadedRecord(0);
    std::vector<u8>* record =
        MutableGameplaySessionLoadedRecord(kGameplayScenarioObjectRecordIndex);
    UnitMovementContext* movement = default_gameplay_movement_context();
    if (header == nullptr || record == nullptr || movement == nullptr ||
        header->size() <
            kGameplayHeaderUnitLifecycleListHeadOffset + sizeof(u32) ||
        record->size() < kGameplayScenarioObjectStride * 2) {
        return;
    }

    const u32 object_count = std::min<u32>(
        static_cast<u32>(record->size() / kGameplayScenarioObjectStride),
        kGameplayScenarioObjectMaxSlots);
    std::vector<u8> claimed(object_count, 0);
    std::vector<u32> active_indices;
    std::vector<u32> lifecycle_indices;
    std::vector<u32> free_indices;
    active_indices.reserve(movement->active_units.size());
    lifecycle_indices.reserve(movement->lifecycle_units.size());
    free_indices.reserve(movement->free_units.size());

    const auto append_unit_slot = [&](const UnitMovementUnit* unit,
                                      bool require_active,
                                      std::vector<u32>& indices) {
        if (unit == nullptr || unit->active != require_active ||
            unit->runtime_slot_index == 0 ||
            unit->runtime_slot_index == kInvalidUnitRuntimeSlotIndex ||
            unit->runtime_slot_index >= object_count ||
            claimed[unit->runtime_slot_index] != 0) {
            return;
        }
        claimed[unit->runtime_slot_index] = 1;
        indices.push_back(unit->runtime_slot_index);
    };
    for (const UnitMovementUnit* unit : movement->active_units) {
        append_unit_slot(unit, true, active_indices);
    }
    for (const UnitMovementUnit* unit : movement->lifecycle_units) {
        append_unit_slot(unit, false, lifecycle_indices);
    }
    for (const UnitMovementUnit* unit : movement->free_units) {
        append_unit_slot(unit, false, free_indices);
    }

    // A fixed-pool slot omitted by a malformed runtime list belongs at the
    // free-list tail.  This preserves the next allocation while keeping the
    // serialized pool complete, matching the map-effect pool exporter.
    for (u32 slot = 1; slot < object_count; ++slot) {
        if (claimed[slot] == 0) {
            claimed[slot] = 1;
            free_indices.push_back(slot);
        }
    }

    const auto write_chain = [&](const std::vector<u32>& indices) {
        for (std::size_t position = 0; position < indices.size(); ++position) {
            const u32 slot = indices[position];
            const std::size_t object_base =
                static_cast<std::size_t>(slot) *
                kGameplayScenarioObjectStride;
            const u32 previous = position == 0 ? 0 :
                indices[position - 1] * kGameplayScenarioObjectStride;
            const u32 next = position + 1 >= indices.size() ? 0 :
                indices[position + 1] * kGameplayScenarioObjectStride;
            write_default_session_buffer_u32(*record,
                object_base + kGameplayScenarioObjectPreviousLinkOffset,
                previous);
            write_default_session_buffer_u32(*record,
                object_base + kGameplayScenarioObjectNextLinkOffset,
                next);
        }
    };
    write_chain(active_indices);
    write_chain(lifecycle_indices);
    write_chain(free_indices);

    write_default_session_buffer_u32(*header,
        kGameplayHeaderUnitActiveListHeadOffset,
        active_indices.empty() ? 0 :
            active_indices.front() * kGameplayScenarioObjectStride);
    write_default_session_buffer_u32(*header,
        kGameplayHeaderUnitFreeListHeadOffset,
        free_indices.empty() ? 0 :
            free_indices.front() * kGameplayScenarioObjectStride);
    write_default_session_buffer_u32(*header,
        kGameplayHeaderUnitLifecycleListHeadOffset,
        lifecycle_indices.empty() ? 0 :
            lifecycle_indices.front() * kGameplayScenarioObjectStride);
}

bool default_unit_effect_serialized_offset_to_index(
    const std::vector<u8>& record, u32 offset, std::size_t& index) {
    index = 0;
    if (offset == 0 ||
        (offset % kGameplayUnitEffectObjectStride) != 0) {
        return false;
    }
    const u32 physical_index = offset / kGameplayUnitEffectObjectStride;
    if (physical_index == 0 ||
        physical_index > kGameplayUnitEffectUsableSlotCount) {
        return false;
    }
    const std::size_t object_base =
        static_cast<std::size_t>(physical_index) *
        kGameplayUnitEffectObjectStride;
    if (object_base > record.size() ||
        record.size() - object_base < kGameplayUnitEffectObjectStride) {
        return false;
    }
    index = physical_index - 1u;
    return true;
}

bool read_default_unit_effect_serialized_chain(
    const std::vector<u8>& record, u32 head,
    std::vector<std::size_t>& head_to_tail) {
    head_to_tail.clear();
    std::vector<u8> visited(kGameplayUnitEffectUsableSlotCount, 0);
    u32 previous = 0;
    u32 cursor = head;
    while (cursor != 0) {
        std::size_t index = 0;
        if (!default_unit_effect_serialized_offset_to_index(
                record, cursor, index) ||
            index >= visited.size() || visited[index] != 0) {
            head_to_tail.clear();
            return false;
        }
        const std::size_t object_base =
            (index + 1u) * kGameplayUnitEffectObjectStride;
        if (read_default_session_record_u32(record,
                object_base + kGameplayUnitEffectObjectPreviousOffset,
                0xffffffffu) != previous) {
            head_to_tail.clear();
            return false;
        }
        visited[index] = 1;
        head_to_tail.push_back(index);
        previous = cursor;
        cursor = read_default_session_record_u32(record,
            object_base + kGameplayUnitEffectObjectNextOffset, 0);
    }
    return true;
}

bool recover_default_unit_effect_serialized_lists(
    const std::vector<u8>& header, const std::vector<u8>& record,
    std::vector<std::size_t>& active_head_to_tail,
    std::vector<std::size_t>& free_head_to_tail) {
    active_head_to_tail.clear();
    free_head_to_tail.clear();
    if (header.size() <
            kGameplayHeaderUnitEffectFreeListHeadOffset + sizeof(u32) ||
        record.size() < static_cast<std::size_t>(
            kGameplayUnitEffectRawBlockCount) *
            kGameplayUnitEffectObjectStride) {
        return false;
    }

    const u32 active_head = read_default_session_record_u32(header,
        kGameplayHeaderUnitEffectActiveListHeadOffset, 0);
    const u32 free_head = read_default_session_record_u32(header,
        kGameplayHeaderUnitEffectFreeListHeadOffset, 0);
    if (!read_default_unit_effect_serialized_chain(
            record, active_head, active_head_to_tail) ||
        !read_default_unit_effect_serialized_chain(
            record, free_head, free_head_to_tail)) {
        active_head_to_tail.clear();
        free_head_to_tail.clear();
        return false;
    }

    std::vector<u8> claimed(kGameplayUnitEffectUsableSlotCount, 0);
    for (const std::size_t index : active_head_to_tail) {
        if (index >= claimed.size() || claimed[index] != 0) {
            active_head_to_tail.clear();
            free_head_to_tail.clear();
            return false;
        }
        claimed[index] = 1;
    }
    for (const std::size_t index : free_head_to_tail) {
        if (index >= claimed.size() || claimed[index] != 0) {
            active_head_to_tail.clear();
            free_head_to_tail.clear();
            return false;
        }
        claimed[index] = 1;
    }
    // Both intrusive roots must cover the physical pool exactly.  Treating a
    // node orphaned by a truncated active chain as free would silently change
    // live effects; reject the whole recovery and use the all-free fallback.
    if (std::find(claimed.begin(), claimed.end(), u8{0}) != claimed.end()) {
        active_head_to_tail.clear();
        free_head_to_tail.clear();
        return false;
    }
    return true;
}

bool default_unit_effect_uses_serialized_path_axes(
    const UnitEffectRuntimeState& effects, const UnitEffectRuntime& effect) {
    if ((effect.flags & kUnitEffectFlagStartup) != 0) {
        return false;
    }
    // Effect 0x20's afterimage clone stays in the active dispatcher, but its
    // tick handler advances only the frame/timer union.  Raw +0x30..+0x3c
    // therefore remain opaque saved-state words rather than path axes.
    if (effect.effect_id == 0x20u &&
        (effect.flags & kUnitEffectFlagAfterimageClone) != 0) {
        return false;
    }
    if ((effect.flags & kUnitEffectFlagImpact) != 0) {
        // Generic low projectiles retain their live Bresenham scratch after
        // entering impact.  Three fixed-impact handlers instead own opaque
        // +0x30/+0x34 unions and must preserve their backing words.
        return effect.effect_id < 0x3du && effect.effect_id != 0x1eu &&
            effect.effect_id != 0x22u && effect.effect_id != 0x26u;
    }
    // Sky Fallout, Blasting, and Bline have dedicated in-place active
    // handlers.  Their definition loop fields do not turn raw +0x30..+0x3c
    // into path scratch (and mode-5 overrides must not do so either).
    if (effect.effect_id == 0x4du || effect.effect_id == 0x62u ||
        effect.effect_id == 0x69u) {
        return false;
    }
    // Berry-fly (selected action 0x26) owns a dedicated path initializer and
    // active handler.  Its movement does not depend on mutable definition
    // path-control fields, including mode-5 tail overrides.
    if (effect.effect_id == 0x63u) {
        return true;
    }
    if (effect.effect_id < 0x3du) {
        return true;
    }
    const UnitEffectDefinition* definition =
        find_default_unit_effect_definition(effects, effect.effect_id);
    return definition != nullptr &&
        (definition->action_path_control == 1 ||
            definition->action_projectile_loop_ticks != 0);
}

void rebind_default_reserved_tile_effect_from_raw_cargo(
    UnitMovementUnit& unit) {
    unit.reserved_tile_effect = nullptr;
    unit.reserved_tile_effect_slot_offset = 0;
    if ((unit.command_state & kUnitCommandStateMask) !=
            kUnitStateReservedTileLinkedObject) {
        return;
    }

    const u32 effect_offset = unit.cargo_amount;
    if (effect_offset == 0 ||
        (effect_offset % kGameplayUnitEffectObjectStride) != 0) {
        return;
    }
    const u32 physical_index =
        effect_offset / kGameplayUnitEffectObjectStride;
    if (physical_index == 0 ||
        physical_index > kGameplayUnitEffectUsableSlotCount) {
        return;
    }

    UnitEffectRuntimeState& effects =
        g_runtime.gameplay_unit_effect_runtime;
    const std::size_t index = physical_index - 1u;
    if (index >= effects.effect_slots.size()) {
        return;
    }
    unit.reserved_tile_effect_slot_offset = effect_offset;
    UnitEffectRuntime& effect = effects.effect_slots[index];
    // Original state 0x58 accepts an inactive/recycled OBB node and validates
    // only the source reference at effect raw +0x18.
    if (effect.source_unit_id == unit.id) {
        unit.reserved_tile_effect = &effect;
    }
}

void sync_default_unit_effect_runtime_session_record() {
    std::vector<u8>* header = MutableGameplaySessionLoadedRecord(0);
    std::vector<u8>* record = MutableGameplaySessionLoadedRecord(
        kGameplayUnitEffectObjectRecordIndex);
    if (header == nullptr || record == nullptr ||
        header->size() <
            kGameplayHeaderUnitEffectFreeListHeadOffset + sizeof(u32) ||
        record->size() < static_cast<std::size_t>(
            kGameplayUnitEffectRawBlockCount) *
            kGameplayUnitEffectObjectStride) {
        return;
    }

    UnitEffectRuntimeState& effects =
        g_runtime.gameplay_unit_effect_runtime;
    std::vector<u8> claimed(kGameplayUnitEffectUsableSlotCount, 0);
    std::vector<std::size_t> active_indices;
    std::vector<std::size_t> free_indices;
    active_indices.reserve(effects.active_effect_indices.size());
    free_indices.reserve(effects.free_effect_indices.size());

    const auto append_active = [&](std::size_t index) {
        if (index >= claimed.size() || index >= effects.effect_slots.size() ||
            claimed[index] != 0 || !effects.effect_slots[index].active) {
            return;
        }
        claimed[index] = 1;
        active_indices.push_back(index);
    };
    for (const std::size_t index : effects.active_effect_indices) {
        append_active(index);
    }
    // Preserve a live effect even if a malformed typed list omitted it.
    for (std::size_t index = 0;
         index < effects.effect_slots.size() && index < claimed.size(); ++index) {
        append_active(index);
    }

    const auto append_free = [&](std::size_t index) {
        if (index >= claimed.size() || claimed[index] != 0 ||
            (index < effects.effect_slots.size() &&
                effects.effect_slots[index].active)) {
            return;
        }
        claimed[index] = 1;
        free_indices.push_back(index);
    };
    for (const std::size_t index : effects.free_effect_indices) {
        append_free(index);
    }
    for (std::size_t index = 0; index < claimed.size(); ++index) {
        append_free(index);
    }

    const auto write_chain = [&](const std::vector<std::size_t>& indices) {
        for (std::size_t position = 0; position < indices.size(); ++position) {
            const std::size_t index = indices[position];
            const std::size_t object_base =
                (index + 1u) * kGameplayUnitEffectObjectStride;
            const u32 previous = position == 0 ? 0 : static_cast<u32>(
                (indices[position - 1] + 1u) *
                kGameplayUnitEffectObjectStride);
            const u32 next = position + 1 >= indices.size() ? 0 :
                static_cast<u32>((indices[position + 1] + 1u) *
                    kGameplayUnitEffectObjectStride);
            write_default_session_buffer_u32(*record,
                object_base + kGameplayUnitEffectObjectPreviousOffset,
                previous);
            write_default_session_buffer_u32(*record,
                object_base + kGameplayUnitEffectObjectNextOffset, next);
        }
    };
    write_chain(active_indices);
    write_chain(free_indices);

    write_default_session_buffer_u32(*header,
        kGameplayHeaderUnitEffectActiveListHeadOffset,
        active_indices.empty() ? 0 : static_cast<u32>(
            (active_indices.front() + 1u) *
            kGameplayUnitEffectObjectStride));
    write_default_session_buffer_u32(*header,
        kGameplayHeaderUnitEffectFreeListHeadOffset,
        free_indices.empty() ? 0 : static_cast<u32>(
            (free_indices.front() + 1u) *
            kGameplayUnitEffectObjectStride));

    for (std::size_t index = 0;
         index < effects.effect_slots.size() && index < claimed.size(); ++index) {
        const UnitEffectRuntime& effect = effects.effect_slots[index];
        const std::size_t object_base =
            (index + 1u) * kGameplayUnitEffectObjectStride;
        const auto write_field = [&](std::size_t field, u32 value) {
            write_default_session_buffer_u32(
                *record, object_base + field, value);
        };

        write_field(kGameplayUnitEffectObjectIdOffset, effect.effect_id);
        write_field(kGameplayUnitEffectObjectDirectionOffset, effect.direction);
        write_field(kGameplayUnitEffectObjectFlagsOffset, effect.flags);
        write_field(kGameplayUnitEffectObjectAmountOffset, effect.amount);
        write_field(kGameplayUnitEffectObjectSourceUnitOffset,
            effect.source_unit_id);
        const u32 target_reference = effect.effect_id < 0x3du
            ? (effect.target_unit_id != 0 ?
                effect.target_unit_id : effect.linked_unit_id)
            : (effect.linked_unit_id != 0 ?
                effect.linked_unit_id : effect.target_unit_id);
        write_field(kGameplayUnitEffectObjectTargetUnitOffset,
            target_reference);
        write_field(kGameplayUnitEffectObjectXOffset,
            static_cast<u32>(effect.x));
        write_field(kGameplayUnitEffectObjectYOffset,
            static_cast<u32>(effect.y));
        write_field(kGameplayUnitEffectObjectTargetXOffset,
            static_cast<u32>(effect.target_x));
        write_field(kGameplayUnitEffectObjectTargetYOffset,
            static_cast<u32>(effect.target_y));
        write_field(kGameplayUnitEffectObjectStepXOffset,
            static_cast<u32>(effect.step_x));
        write_field(kGameplayUnitEffectObjectStepYOffset,
            static_cast<u32>(effect.step_y));
        write_field(kGameplayUnitEffectObjectClosestDistanceOffset,
            effect.closest_distance);

        const bool uses_serialized_path_axes =
            default_unit_effect_uses_serialized_path_axes(effects, effect);
        if (effect.effect_id >= 0x3du && uses_serialized_path_axes) {
            // Selected-action projectiles use +0x0c as their loop tick and
            // +0x10 as the remaining path budget until impact begins.
            write_field(kGameplayUnitEffectObjectCounter0cOffset, effect.tick);
            write_field(kGameplayUnitEffectObjectState10Offset, effect.range);
        } else if (effect.effect_id >= 0x3du) {
            write_field(kGameplayUnitEffectObjectCounter0cOffset, effect.tick);
            write_field(kGameplayUnitEffectObjectState10Offset, effect.frame);
        } else if (effect.effect_id == 0x1eu ||
            (effect.effect_id == 0x20u &&
                (effect.flags & kUnitEffectFlagAfterimageClone) != 0)) {
            write_field(kGameplayUnitEffectObjectCounter0cOffset, effect.frame);
            write_field(kGameplayUnitEffectObjectState10Offset, effect.tick);
        } else if ((effect.flags & kUnitEffectFlagStartup) != 0) {
            write_field(kGameplayUnitEffectObjectCounter0cOffset, effect.tick);
        } else {
            write_field(kGameplayUnitEffectObjectCounter0cOffset, effect.frame);
            if ((effect.flags & kUnitEffectFlagImpact) == 0) {
                write_field(kGameplayUnitEffectObjectState10Offset, effect.range);
            } else if (effect.effect_id == 0x22u ||
                effect.effect_id == 0x26u) {
                write_field(kGameplayUnitEffectObjectState10Offset,
                    effect.initial_impact_applied ? 1u : 0u);
            }
        }

        if (uses_serialized_path_axes) {
            const bool y_major =
                (effect.flags & kUnitEffectFlagProjectileYMajor) != 0;
            write_field(kGameplayUnitEffectObjectAxis30Offset,
                y_major ? effect.accumulator_x : effect.abs_delta_x);
            write_field(kGameplayUnitEffectObjectAxis34Offset,
                y_major ? effect.abs_delta_y : effect.accumulator_y);
            write_field(kGameplayUnitEffectObjectAbsXOffset,
                effect.abs_delta_x);
            write_field(kGameplayUnitEffectObjectAbsYOffset,
                effect.abs_delta_y);
        } else if (effect.effect_id >= 0x3du) {
            // High-id action handlers reuse +0x30/+0x34 for lifetime and
            // counters.  +0x38/+0x3c remain untouched backing bytes here.
            write_field(kGameplayUnitEffectObjectAxis30Offset,
                effect.abs_delta_x);
            write_field(kGameplayUnitEffectObjectAxis34Offset,
                effect.abs_delta_y);
        } else if (effect.effect_id == 0x1eu) {
            write_field(kGameplayUnitEffectObjectAxis30Offset,
                static_cast<u32>(effect.previous_x));
            write_field(kGameplayUnitEffectObjectAxis34Offset,
                static_cast<u32>(effect.previous_y));
        }

        if (effect.effect_id == 0x17u) {
            // FUN_004ed189 clears raw +0x4c when a live chain projectile is
            // initialized.  Free nodes retain their stale payload verbatim.
            if (effect.active) {
                write_field(kGameplayUnitEffectObjectHitCountOffset, 0);
            }
            write_field(kGameplayUnitEffectObjectHitHistoryOffset,
                effect.chain_remaining);
            for (std::size_t chain = 0;
                 chain < effect.chained_target_ids.size(); ++chain) {
                write_field(kGameplayUnitEffectObjectHitHistoryOffset +
                    (chain + 1u) * sizeof(u32),
                    effect.chained_target_ids[chain]);
            }
        } else if (effect.effect_id < 0x3du) {
            const u32 hit_count = static_cast<u32>(std::min<std::size_t>(
                effect.hit_unit_ids.size(),
                kGameplayUnitEffectHitHistoryCapacity));
            write_field(kGameplayUnitEffectObjectHitCountOffset, hit_count);
            for (u32 hit = 0; hit < hit_count; ++hit) {
                write_field(kGameplayUnitEffectObjectHitHistoryOffset +
                    static_cast<std::size_t>(hit) * sizeof(u32),
                    effect.hit_unit_ids[hit]);
            }
        }
    }
}

void sync_default_map_effect_context_session_record() {
    std::vector<u8>* record =
        MutableGameplaySessionLoadedRecord(kGameplayMapEffectObjectRecordIndex);
    if (record == nullptr ||
        record->size() < kGameplayMapEffectObjectStride * 2) {
        return;
    }

    const u32 object_count = std::min<u32>(
        static_cast<u32>(record->size() / kGameplayMapEffectObjectStride),
        kGameplayMapEffectObjectMaxSlots);

    // HandleGameplaySessionBundleExport writes DAT_012ce970 as one raw
    // 0x7800-byte record (0x004d236d..0x004d238b).  Rebuild that physical
    // pool image for every slot before replacing only its intrusive links.
    // This retains untyped +0x04/+0x08 and +0x14..+0x20 bytes as well as the
    // stale payload of free nodes, just as AllocateMapEffect/ReleaseMapEffect
    // (0x004d1bc0/0x004d1c0b) do in the original.
    const u32 materialized_count = std::min<u32>(object_count,
        static_cast<u32>(g_runtime.map_effect_context.effects.size()));
    for (u32 index = 0; index < materialized_count; ++index) {
        const MapEffectInstance& effect =
            g_runtime.map_effect_context.effects[index];
        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        StoreMapEffectRawRecord(effect, record->data() + object_base,
            record->size() - object_base);
    }

    std::vector<bool> active(object_count, false);
    std::vector<bool> free(object_count, false);
    std::vector<u32> active_indices;
    active_indices.reserve(g_runtime.map_effect_context.active_effect_indices.size());
    for (u32 index : g_runtime.map_effect_context.active_effect_indices) {
        if (index == 0 || index >= object_count ||
            index >= g_runtime.map_effect_context.effects.size() ||
            active[index]) {
            continue;
        }
        const MapEffectInstance& effect =
            g_runtime.map_effect_context.effects[index];
        // AllocateMapEffect/ReleaseMapEffect (0x004d1bc0/0x004d1c0b) use
        // intrusive-list ownership as the active/free discriminator.  Type 0
        // is a valid terrain effect selected by raw unit +0x68.
        if (!effect.active) {
            continue;
        }
        active[index] = true;
        active_indices.push_back(index);
    }

    // The runtime vector keeps the intrusive free-list head at the back,
    // because AllocateMapEffect pops from there.  Serialize it in the
    // original head-to-tail order.
    std::vector<u32> free_indices;
    free_indices.reserve(object_count);
    for (auto it = g_runtime.map_effect_context.free_effect_indices.rbegin();
         it != g_runtime.map_effect_context.free_effect_indices.rend(); ++it) {
        const u32 index = *it;
        if (index == 0 || index >= object_count || active[index] || free[index]) {
            continue;
        }
        free[index] = true;
        free_indices.push_back(index);
    }
    // Keep the serialized pool complete even if a malformed runtime vector
    // omitted an inactive slot.  Such recovered slots belong at the free-list
    // tail and therefore do not change the next allocation.
    for (u32 index = 1; index < object_count; ++index) {
        if (!active[index] && !free[index]) {
            free[index] = true;
            free_indices.push_back(index);
        }
    }

    for (std::size_t position = 0; position < active_indices.size(); ++position) {
        const u32 index = active_indices[position];
        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        const u32 previous_offset = position == 0 ? 0 :
            active_indices[position - 1] * kGameplayMapEffectObjectStride;
        const u32 next_offset = position + 1 >= active_indices.size() ? 0 :
            active_indices[position + 1] * kGameplayMapEffectObjectStride;
        write_default_session_buffer_u32(
            *record, object_base + kGameplayMapEffectObjectPreviousOffset,
            previous_offset);
        write_default_session_buffer_u32(
            *record, object_base + kGameplayMapEffectObjectNextOffset,
            next_offset);
    }

    for (std::size_t position = 0; position < free_indices.size(); ++position) {
        const u32 index = free_indices[position];
        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        const u32 previous_offset = position == 0 ? 0 :
            free_indices[position - 1] * kGameplayMapEffectObjectStride;
        const u32 next_offset = position + 1 >= free_indices.size() ? 0 :
            free_indices[position + 1] * kGameplayMapEffectObjectStride;
        write_default_session_buffer_u32(
            *record, object_base + kGameplayMapEffectObjectPreviousOffset,
            previous_offset);
        write_default_session_buffer_u32(
            *record, object_base + kGameplayMapEffectObjectNextOffset,
            next_offset);
    }

    std::vector<u8>* header = MutableGameplaySessionLoadedRecord(0);
    if (header != nullptr &&
        header->size() >=
            kGameplayHeaderMapEffectFreeListHeadOffset + sizeof(u32)) {
        write_default_session_buffer_u32(
            *header, kGameplayHeaderMapEffectActiveListHeadOffset,
            active_indices.empty() ? 0 :
                active_indices.front() * kGameplayMapEffectObjectStride);
        write_default_session_buffer_u32(
            *header, kGameplayHeaderMapEffectFreeListHeadOffset,
            free_indices.empty() ? 0 :
                free_indices.front() * kGameplayMapEffectObjectStride);
    }
}

void stamp_default_gameplay_save_title(std::vector<u8>& record, const char* title) {
    if (record.size() < kGameplaySaveTitleBytes) {
        record.resize(kGameplaySaveTitleBytes, 0);
    }
    std::fill_n(record.data(), kGameplaySaveTitleBytes, u8{0});
    if (title == nullptr) {
        return;
    }

    std::size_t count = 0;
    while (count + 1 < kGameplaySaveTitleBytes && title[count] != '\0') {
        ++count;
    }
    std::memcpy(record.data(), title, count);
}

bool export_default_loaded_gameplay_session_bundle_to(
    const char* archive_name, const char* save_title) {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (archive_name == nullptr || archive_name[0] == '\0' || !load.loaded) {
        return false;
    }

    sync_default_gameplay_movement_map_session_records();
    sync_default_gameplay_player_session_record();
    // Script mirroring runs before the unit-runtime phase, so its record-7
    // image can be one simulation tick behind (or still contain a free node
    // for a unit produced later that tick).  Snapshot every live active node
    // into its physical fixed-pool slot immediately before serializing.
    if (UnitMovementContext* movement = default_gameplay_movement_context()) {
        GameplayScriptTriggerState& script = gameplay_script_trigger_state();
        script.condition_context.active_object_order.clear();
        for (UnitMovementUnit* unit : movement->active_units) {
            if (unit == nullptr || !unit->active) {
                continue;
            }
            const u32 object_index =
                ensure_default_gameplay_script_object_index_for_unit(
                    script, *unit);
            if (object_index >= script.objects.size()) {
                continue;
            }
            sync_default_gameplay_script_object_from_unit(
                script.objects[object_index], *unit);
            script.condition_context.active_object_order.push_back(object_index);
        }
        for (UnitMovementUnit* unit : movement->lifecycle_units) {
            if (unit == nullptr || unit->active) {
                continue;
            }
            const u32 object_index =
                ensure_default_gameplay_script_object_index_for_unit(
                    script, *unit);
            if (object_index >= script.objects.size()) {
                continue;
            }
            sync_default_gameplay_script_object_from_unit(
                script.objects[object_index], *unit);
            // Lifecycle-list raw +0x64 aliases the work/death/growth timer.
            // The typed runtime keeps it separate from the active animation
            // frame, so project the list-specific value immediately before
            // serializing record 7.
            script.objects[object_index].animation_frame = unit->work_timer;
        }
        sync_default_gameplay_script_scenario_record(script);
        g_runtime.gameplay_script_scenario_record_sync_frame =
            gameplay_loop_state().simulation_frame_counter;
    }
    sync_default_gameplay_unit_pool_list_session_records();
    sync_default_unit_effect_runtime_session_record();
    sync_default_map_effect_context_session_record();

    std::vector<TrcWriteRecord> records;
    const std::vector<GameplaySessionExportRecordSpec>& specs =
        gameplay_session_export_specs();
    records.reserve(specs.size() + kSessionRuntimeUserRecordCount + 2);
    for (std::size_t i = 0; i < specs.size(); ++i) {
        const GameplaySessionExportRecordSpec& spec = specs[i];
        TrcWriteRecord record{};
        record.name = spec.name;
        record.method = spec.original_method;
        if (i == kGameplaySessionOwnerAiRecordIndex) {
            if (!export_default_owner_ai_snapshot_to_payload(record.payload)) {
                return false;
            }
        } else if (i == kGameplaySessionOwnerUnitAvailabilityRecordIndex) {
            record.payload.resize(kGameplaySessionOwnerUnitAvailabilityRecordBytes);
            for (u32 owner = 0; owner < kGameSessionOwnerCount; ++owner) {
                const std::size_t offset =
                    static_cast<std::size_t>(owner) * kGameSessionUnitTypeCount;
                std::copy(g_runtime.session_runtime_import_state
                              .owner_unit_availability[owner].begin(),
                    g_runtime.session_runtime_import_state
                        .owner_unit_availability[owner].end(),
                    record.payload.begin() + offset);
            }
        } else if (i < load.records.size() && load.record_loaded[i]) {
            record.payload = load.records[i];
        } else if (spec.byte_count != 0) {
            record.payload.assign(spec.byte_count, 0);
        }
        if (i == 0) {
            sync_default_gameplay_clock_and_random_state_to_session_header(
                record.payload);
            // The original JW2 primary record owns the live production
            // variants, lock cells and accumulated upgrade effects.  US_UPG
            // remains a raw definition override and is exported separately.
            sync_default_production_runtime_to_session_header(record.payload);
        }
        if (i == kGameplaySessionMapRecordIndex) {
            stamp_default_gameplay_save_title(record.payload, save_title);
        }
        records.push_back(record);
    }
    if (!append_default_session_runtime_export_records(records)) {
        return false;
    }

    return HandleGameplaySessionBundleExport(archive_name, records);
}

GameplayInputActionState& prepare_default_modal_publish_input() {
    GameplayInputActionState& input = gameplay_input_action_state();
    configure_default_gameplay_input_action_context(input);
    input.local_player_index = mode1_reliable_state().local_player_index;
    return input;
}

void default_gameplay_modal_clear_reliable_packet_rings(GameplayModalUiState&) {
    ClearMode1ReliablePacketRings();
}

void default_gameplay_modal_scan_save_slot_headers(GameplayModalUiState& state) {
    GameplaySessionFlowState& flow = prepare_default_modal_session_flow();
    ScanGameplaySaveSlotHeaders(flow);
    sync_default_modal_save_slots_from_session_flow(state, flow);
}

void default_gameplay_modal_refresh_scenario_objective(
    GameplayModalUiState& state) {
    std::string objective;
    if (const std::vector<u8>* record = default_session_scenario_record();
        record != nullptr) {
        objective = ReadGameplayScenarioObjectiveText(*record);
    }
    const GameplayScriptTriggerState& script = gameplay_script_trigger_state();
    if (objective.empty()) {
        objective = script.opcode_context.scenario_message_text;
    }
    if (objective.empty()) {
        objective = RecoverGameplayScenarioObjectiveText(script);
    }
    if (objective.empty()) {
        return;
    }

    state.scenario_message_text = objective;
    state.fallback_scenario_message_text = std::move(objective);
}

bool default_gameplay_active_session_import() {
    return gameplay_loop_state().session_active &&
        g_runtime.gameplay_startup_slots_started;
}

void configure_default_gameplay_modal_load_retry_policy(
    GameplayModalUiState& state) {
    // DAT_00725c08 is set while the original game is replacing an active
    // session.  Once an import has damaged/replaced the raw record set, the
    // load dialog must stay open until a subsequent attempt succeeds.
    state.require_cancel_confirmation = default_gameplay_active_session_import();
}

bool patch_default_in_game_load_player_record_bytes(std::vector<u8>& record,
    const GameplayInGameLoadResumeState& resume) {
    if (resume.local_player_index >= kPlayerSlotCount ||
        resume.local_faction_id > 3 ||
        record.size() < kGameplaySessionPlayerRecordBytes) {
        return false;
    }

    write_default_session_buffer_u32(
        record, kSessionPlayerRecordLocalOwnerOffset,
        resume.local_player_index);
    write_default_session_buffer_u32(record,
        kSessionPlayerRecordFactionBaseOffset +
            static_cast<std::size_t>(resume.local_player_index) * sizeof(u32),
        resume.local_faction_id);
    return true;
}

bool patch_default_in_game_load_player_record(
    const GameplayInGameLoadResumeState& resume) {
    std::vector<u8>* record =
        MutableGameplaySessionLoadedRecord(kGameplaySessionPlayerRecordIndex);
    return record != nullptr &&
        patch_default_in_game_load_player_record_bytes(*record, resume);
}

bool default_gameplay_modal_import_materialization_ready(
    bool active_session_import, bool bundle_loaded, bool terrain_loaded) {
    // Preserve the existing inactive/frontend import contract.  An active
    // session, however, cannot enter the deferred restart with an empty tile
    // bank: the original 0x004d1ccc success chain includes FUN_00425340.
    return bundle_loaded && (!active_session_import || terrain_loaded);
}

bool default_gameplay_modal_import_session_bundle(
    GameplayModalUiState& state, u32 slot_index) {
    GameplaySessionFlowState& flow = prepare_default_modal_session_flow();
    if (slot_index >= flow.save_slots.size()) {
        return false;
    }

    const std::string& path = flow.save_slots[slot_index].path;
    if (path.empty()) {
        return false;
    }

    const bool active_session_import = default_gameplay_active_session_import();
    state.require_cancel_confirmation = active_session_import;
    GameplayInGameLoadResumeState resume{};
    if (active_session_import) {
        resume.p2p_session_start = g_runtime.p2p_session_start_state;
        resume.frontend_mode = g_runtime.frontend_mode;
        resume.local_player_index = mode1_reliable_state().local_player_index;
        const u32 local_player = std::min<u32>(
            resume.local_player_index, kPlayerSlotCount - 1);
        resume.local_faction_id =
            g_runtime.gameplay_startup_state.owner_faction_ids[local_player];
        if (resume.local_faction_id > 3) {
            resume.local_faction_id =
                g_runtime.gameplay_startup_state.owner_slots[local_player]
                    .faction_id;
        }
        if (resume.local_faction_id > 3) {
            resume.local_faction_id = 0;
        }
        resume.network_transport_mode =
            async_com_state().active_network_transport_mode;
        resume.p2p_session_start_prepared =
            g_runtime.p2p_session_start_prepared;
        resume.generic_ai_profile_mode = g_runtime.generic_ai_profile_mode;
        resume.network_ai_profile_override =
            g_runtime.network_ai_profile_override;
        resume.generic_ai_scenario_active =
            g_runtime.generic_ai_scenario_active;
    }

    g_runtime.gameplay_session_archive_path = path;
    SetReplayControlsEnabled(replay_recording_state().playback_mode);
    const bool bundle_imported = HandleGameplaySessionBundleImport(
        path.c_str(), 0, load_default_gameplay_terrain_tile_sheet_bank);
    if (!bundle_imported) {
        report_gameplay_session_import_resource_failure();
    }
    g_runtime.gameplay_session_bundle_loaded = bundle_imported;
    g_runtime.gameplay_terrain_tile_sheet_loaded =
        bundle_imported && TerrainTileSheetBankAllocationsValid(
            g_runtime.gameplay_terrain_tile_sheet);
    if (g_runtime.gameplay_session_bundle_loaded && active_session_import &&
        !patch_default_in_game_load_player_record(resume)) {
        append_startup_log(
            "modal-load: failed to preserve local record3 owner/faction");
        g_runtime.gameplay_session_bundle_loaded = false;
    }
    if (g_runtime.gameplay_session_bundle_loaded &&
        !import_default_owner_ai_snapshot_from_session_records()) {
        g_runtime.gameplay_session_bundle_loaded = false;
    }
    if (g_runtime.gameplay_session_bundle_loaded) {
        if (!default_gameplay_modal_import_materialization_ready(
                active_session_import,
                g_runtime.gameplay_session_bundle_loaded,
                g_runtime.gameplay_terrain_tile_sheet_loaded)) {
            append_startup_log(
                "modal-load: active import terrain bank failed; retry required");
            g_runtime.gameplay_session_bundle_loaded = false;
        }
    }
    if (g_runtime.gameplay_session_bundle_loaded) {
        g_runtime.session_runtime_import_state = SessionRuntimeImportState{};
        g_runtime.active_session_definitions = SessionRuntimeDefinitionTableSet{};
        g_runtime.base_session_definitions = SessionRuntimeDefinitionTableSet{};
        g_runtime.staged_session_definitions = SessionRuntimeDefinitionTableSet{};
        g_runtime.gameplay_session_runtime_buffers = SessionRuntimeBufferPairs{};
        import_default_session_owner_unit_availability();
        stage_default_session_runtime_override_definitions();
        state.non_empty_runtime_tables_available =
            g_runtime.gameplay_session_runtime_definitions_staged;
    } else {
        ReleaseTerrainTileSheetBankResources(g_runtime.gameplay_terrain_tile_sheet);
        g_runtime.gameplay_terrain_tile_sheet_loaded = false;
        state.non_empty_runtime_tables_available = false;
    }

    if (g_runtime.gameplay_session_bundle_loaded && active_session_import) {
        resume.pending = true;
        g_runtime.gameplay_in_game_load_resume = std::move(resume);
        append_startup_log(
            "modal-load: deferred active materialization local=%lu transport=%ld",
            static_cast<unsigned long>(
                g_runtime.gameplay_in_game_load_resume.local_player_index),
            static_cast<long>(
                g_runtime.gameplay_in_game_load_resume.network_transport_mode));
    }

    return g_runtime.gameplay_session_bundle_loaded;
}

bool default_gameplay_modal_export_session_bundle(
    GameplayModalUiState& state, u32 slot_index) {
    GameplaySessionFlowState& flow = prepare_default_modal_session_flow();
    if (slot_index >= flow.save_slots.size()) {
        return false;
    }

    const std::string& path = flow.save_slots[slot_index].path;
    if (!export_default_loaded_gameplay_session_bundle_to(
            path.c_str(), state.save_slots[slot_index].label.c_str())) {
        return false;
    }

    ScanGameplaySaveSlotHeaders(flow);
    sync_default_modal_save_slots_from_session_flow(state, flow);
    return true;
}

void default_gameplay_modal_import_runtime_tables(GameplayModalUiState&) {
    if (g_runtime.gameplay_in_game_load_resume.pending) {
        return;
    }
    prepare_default_base_session_runtime_definition_import();
    // Gameplay save/load uses the mode-5 preservation path: primary JW2 state
    // is live before pristine definitions and marked user overrides catch up.
    restore_default_production_runtime_from_session_header();
    mirror_default_production_variants_to_session_import_state();
    ImportSessionRuntimeDefinitionTables(g_runtime.session_runtime_import_state,
        g_runtime.active_session_definitions, g_runtime.base_session_definitions);
    finalize_default_session_runtime_definition_import();
}

void default_gameplay_modal_import_non_empty_runtime_tables(GameplayModalUiState&) {
    if (g_runtime.gameplay_in_game_load_resume.pending) {
        return;
    }
    prepare_default_non_empty_session_runtime_definition_import();
    ImportNonEmptySessionRuntimeDefinitionTables(g_runtime.session_runtime_import_state,
        g_runtime.active_session_definitions, g_runtime.staged_session_definitions);
    finalize_default_session_runtime_definition_import();
}

void default_gameplay_modal_rebuild_unit_type_references(GameplayModalUiState&) {
    if (g_runtime.gameplay_in_game_load_resume.pending) {
        return;
    }
    rebuild_default_unit_reference_tables_from_catalog();
}

void default_gameplay_modal_publish_corrective_checksum(GameplayModalUiState& modal) {
    GameplayInputActionState& input = prepare_default_modal_publish_input();
    const u32 local = input.local_player_index % kPlayerSlotCount;
    const u32 wait_consensus_mask =
        local < modal.players.size() ? modal.players[local].visibility_mask : 0;

    // FUN_0042c8b0 publishes subtype 0x15 with EAX=1 and the timed-out-player
    // bit mask in EDX (wire offset +0x1c).  The old zero-filled packet selected
    // the command-0 single-target path and therefore voted against slot zero.
    input.pending_action_arg0 = 1;
    input.pending_action_arg1 = 0;
    input.pending_action_arg2 = wait_consensus_mask;
    input.pending_action_arg3 = 0;
    PublishMode1CorrectiveChecksum(input);

    // DirectPlay does not loop a broadcast back to its sender.  Immediately
    // apply the same outbound buffer locally, matching 0x0042c90c..0x0042c911,
    // so a two-player timeout can retire the missing peer and release the
    // reliable sync gate on the following pump.
    const Mode1ReliablePacket local_vote = BuildMode1GameplayPacket(
        (0x15u << 24) | (local & 0xffu), 1, 0, 0,
        wait_consensus_mask, 0);
    HandleSubtype15PlayerConsensusPacket(local_vote);
}

void default_gameplay_modal_publish_modal_pause(GameplayModalUiState&) {
    GameplayInputActionState& input = prepare_default_modal_publish_input();
    input.pending_action_arg0 =
        gameplay_loop_state().modal_pause_suppressed ? 0u : 1u;
    PublishMode1ModalPauseAction(input);
}

void default_gameplay_modal_reset_and_publish_inactive(GameplayModalUiState&) {
    GameplayInputActionState& input = prepare_default_modal_publish_input();
    input.pending_action_arg0 = 0;
    input.pending_action_arg2 = 2;
    const u32 local_slot = std::min<u32>(
        g_runtime.gameplay_player_slots.local_player_slot,
        kPlayerSlotCount - 1);
    if (gameplay_loop_state().simulation_frame_counter >=
            kGameplayOnlineAutoTransitionFrame &&
        g_runtime.gameplay_startup_state.ready_flags[local_slot] != 2) {
        input.pending_action_arg2 = 1;
    }
    const bool local_forces_early_result =
        g_runtime.gameplay_startup_state.ready_flags[local_slot] == 2u;
    g_runtime.gameplay_end_condition_state.result_code =
        ResolveGameplayManualLeaveResult(
            gameplay_loop_state().simulation_frame_counter,
            local_forces_early_result);
    ResetAndPublishPlayerInactiveState(input);
}

void default_gameplay_modal_publish_relation_mask(
    GameplayModalUiState&, u32 relation_mask, u32 visibility_mask,
    bool observer_flag) {
    GameplayInputActionState& input = prepare_default_modal_publish_input();
    input.pending_action_arg0 = observer_flag ? 1u : 0u;
    input.pending_action_arg1 = relation_mask;
    input.pending_action_arg2 = visibility_mask;
    input.pending_action_arg3 = 0;
    PublishMode1RelationMaskAction(input);
}

void default_gameplay_modal_update_catchup_target(GameplayModalUiState&) {
    UpdateGameplayCatchupTargetIfActive(gameplay_loop_state());
}

void default_gameplay_modal_toggle_catchup(GameplayModalUiState& state) {
    GameplayLoopState& loop = gameplay_loop_state();
    if (loop.catchup_enabled != state.catchup_enabled) {
        ToggleGameplayCatchupMode(loop);
    }
}

void default_gameplay_modal_pause_music(GameplayModalUiState&) {
    PausePrimaryMusicFromPolicy();
}

void default_gameplay_modal_resume_music(GameplayModalUiState&) {
    HandlePrimaryMusicPolicyResume();
}

void sync_default_gameplay_options_from_setup_once() {
    static bool synced = false;
    if (synced) {
        return;
    }
    synced = true;

    GameplayLoopState& loop = gameplay_loop_state();
    loop.frame_interval_index = std::min<u32>(
        ImportSetupU32(kSetupGameplaySpeedOffset, loop.frame_interval_index),
        static_cast<u32>(kGameplayFrameIntervalsMs.size() - 1));
    SetPrimaryMilesMusicPolicyRawVolume(std::min<u32>(
        ImportSetupU32(kSetupPrimaryMusicRawVolumeOffset,
            miles_music_state().primary_policy_raw_volume),
        0xffffu));
    g_runtime.gameplay_sound.listener_position_offset = std::clamp(
        ImportSetupI32(kSetupGameplaySoundListenerOffset,
            g_runtime.gameplay_sound.listener_position_offset),
        -10000, 0);
    HandlePrimaryMusicPolicyVolumeApply();
}

u32 default_gameplay_speed_index(u32 speed) {
    return std::min<u32>(
        speed, static_cast<u32>(kGameplayFrameIntervalsMs.size() - 1));
}

u32 default_camera_scroll_speed_index(u32 speed) {
    return std::min<u32>(
        speed, static_cast<u32>(kCameraScrollSpeedCount - 1));
}

void apply_default_gameplay_speed_index(u32 speed, bool export_setup) {
    const u32 clamped_speed = default_gameplay_speed_index(speed);
    gameplay_loop_state().frame_interval_index = clamped_speed;
    if (export_setup) {
        ExportSetupU32(kSetupGameplaySpeedOffset, clamped_speed);
    }
}

void apply_default_camera_scroll_speed_index(u32 speed, bool export_setup) {
    const u32 clamped_speed = default_camera_scroll_speed_index(speed);
    ui_overlay_state().camera_scroll_speed_index = clamped_speed;
    if (export_setup) {
        ExportSetupU32(kSetupSecondaryTimingOffset, clamped_speed);
    }
}

void default_gameplay_modal_apply_music_volume(GameplayModalUiState& state) {
    const u32 gameplay_speed =
        static_cast<u32>(std::clamp(state.music_volume_left, 0, 0x0f));
    const u32 secondary_timing =
        static_cast<u32>(std::clamp(state.music_volume_right, 0, 0x0f));
    const u32 music_raw =
        static_cast<u32>(std::clamp(state.music_volume_raw, 0, 0xffff));
    const i32 sound_offset = std::clamp(state.sound_volume_raw, -10000, 0);
    const u32 scroll_speed =
        static_cast<u32>(std::max(state.scroll_speed, 0));

    apply_default_gameplay_speed_index(gameplay_speed, true);
    apply_default_camera_scroll_speed_index(secondary_timing, true);
    SetPrimaryMilesMusicPolicyRawVolume(music_raw);
    g_runtime.gameplay_sound.listener_position_offset = sound_offset;
    ExportSetupU32(kSetupPrimaryMusicRawVolumeOffset, music_raw);
    ExportSetupI32(kSetupGameplaySoundListenerOffset, sound_offset);
    ExportSetupU32(kSetupScrollSpeedOffset, scroll_speed);
    HandlePrimaryMusicPolicyVolumeApply();
}

void default_gameplay_modal_apply_setup_data(GameplayModalUiState&) {
    WriteDefaultSetupDataBuffer();
}

void default_gameplay_modal_toggle_unit_resource_pack(GameplayModalUiState& state) {
    bool setup_write_requested = false;
    if (ToggleUnitResourcePackVariantAndReload(&setup_write_requested) &&
        setup_write_requested) {
        WriteDefaultSetupDataBuffer();
    }
    state.unit_resource_pack_variant =
        unit_definition_resource_catalog_state().alternate_pack_active;
}

void default_gameplay_modal_exit_worker_thread(GameplayModalUiState& state) {
    state.worker_exit_requested = true;
    g_runtime.worker_thread_running = false;
    gameplay_loop_state().process_shutdown_requested = true;
    gameplay_loop_state().leave_requested = true;
}

void default_gameplay_modal_show_message(GameplayModalUiState&, const char* message) {
    const char* text = message != nullptr ? message : "";
#ifdef _WIN32
    OutputDebugStringA(text);
    OutputDebugStringA("\n");
#endif
    if (g_runtime.main_window != nullptr && IsWindow(g_runtime.main_window) &&
        g_runtime.callbacks.show_status_message != nullptr) {
        g_runtime.callbacks.show_status_message(g_runtime.main_window, text, 0x000a0afa,
            g_runtime.callbacks.user_data);
    }
}

void default_gameplay_modal_apply_observer_settings(
    GameplayModalUiState&, u32 channel, u32 recipient_mask) {
    UiOverlayState& overlay = ui_overlay_state();
    overlay.default_chat_channel = std::min<u32>(channel, 3u);
    if (!overlay.chat_active) {
        overlay.chat_channel = overlay.default_chat_channel;
    }
    g_gameplay_chat_target_mask = recipient_mask & 0xffu;
}

void default_gameplay_modal_apply_compact_observer_flags(
    GameplayModalUiState&, u32 flags) {
    gameplay_script_trigger_state().opcode_context.resource_hud_flags = flags;
}

void default_gameplay_modal_send_replay_modal_action(
    GameplayModalUiState& state, u32 action) {
    if (g_runtime.main_window == nullptr || !IsWindow(g_runtime.main_window)) {
        state.replay_modal_pending = false;
        return;
    }
    SendMessageA(g_runtime.main_window, WM_USER + 9, 0,
        static_cast<LPARAM>(action));
    state.replay_modal_pending = false;
}

void default_gameplay_modal_trc_fatal_error(GameplayModalUiState& state) {
    DispatchActiveTrcRecordFatalErrorMirror(state);
}

void configure_default_gameplay_modal_ui_callbacks(GameplayModalUiState& state) {
    constexpr std::size_t kStartupDefaultObjectiveTextRow = 182;
    constexpr std::size_t kStartupPostResultTextRow = 204;
    constexpr std::size_t kStartupEmptySaveSlotTextRow = 233;
    constexpr std::size_t kStartupInvalidSaveSlotTextRow = 234;
    constexpr std::size_t kStartupImportErrorTextRow = 235;
    constexpr std::size_t kStartupNetworkAddressFormatRow = 236;
    constexpr std::size_t kStartupCancelConfirmTextRow = 237;
    constexpr std::size_t kStartupExportErrorTextRow = 238;
    constexpr std::size_t kStartupDefaultMessageTextRow = 239;
    constexpr std::size_t kStartupWaitRemainingFormatRow = 240;
    configure_default_gameplay_modal_load_retry_policy(state);
    sync_default_gameplay_options_from_setup_once();
    if (const char* post_result_text =
            startup_platform_row(kStartupPostResultTextRow, nullptr)) {
        state.post_result_text = post_result_text;
    }
    state.empty_save_label =
        startup_platform_row(kStartupEmptySaveSlotTextRow, "Empty");
    state.invalid_save_label =
        startup_platform_row(kStartupInvalidSaveSlotTextRow, "Invalid");
    state.import_error_message =
        startup_platform_row(kStartupImportErrorTextRow, "Game Loading error !");
    state.network_address_format =
        startup_platform_row(kStartupNetworkAddressFormatRow, "Ver %d-%d-%d");
    state.cancel_confirm_message = startup_platform_row(
        kStartupCancelConfirmTextRow, "Game data demaged, You must load a game.");
    state.export_error_message =
        startup_platform_row(kStartupExportErrorTextRow, "Game Saveing error !");
    state.default_message_text =
        startup_platform_row(kStartupDefaultMessageTextRow, "Unknown error !");
    state.default_objective_text = startup_platform_row(
        kStartupDefaultObjectiveTextRow, "Destroy all enemy buildings.");
    state.wait_remaining_format = startup_platform_row(
        kStartupWaitRemainingFormatRow, "%s - %d Sec remain.");
    if (state.callbacks.refresh_scenario_objective == nullptr) {
        state.callbacks.refresh_scenario_objective =
            default_gameplay_modal_refresh_scenario_objective;
    }
    // FUN_0042d440 centers gameplay outcome/modals against DAT_0086358c,
    // the top of the fixed bottom interface, not the full 600-pixel surface.
    // Keep the full surface as the pre-game/fallback extent, while a running
    // match uses the live world viewport (421 at the original 800x600 layout).
    const UiOverlayState& overlay = ui_overlay_state();
    state.center_width = overlay.screen_width != 0 ? overlay.screen_width : 800u;
    state.fallback_center_height =
        overlay.screen_height != 0 ? overlay.screen_height : 600u;
    state.center_height = overlay.world_viewport_height != 0 ?
        overlay.world_viewport_height : state.fallback_center_height;
    state.catchup_enabled = gameplay_loop_state().catchup_enabled;
    state.local_player_index = mode1_reliable_state().local_player_index;
    state.transport_mode = static_cast<u32>(
        std::max<i32>(async_com_state().active_network_transport_mode, 0));
    state.session_mode = g_runtime.gameplay_startup_state.session_mode;
    state.generic_ai_profile_mode = g_runtime.generic_ai_profile_mode;
    state.replay_mode = replay_recording_state().playback_mode;
    state.scenario_ai_profile_override =
        g_runtime.generic_ai_scenario_active;
    state.network_ai_profile_override = g_runtime.network_ai_profile_override;
    state.modal_pause_suppressed =
        gameplay_loop_state().modal_pause_suppressed ||
        gameplay_loop_state().replay_direct_music_paused;
    if (!state.observer_mask_active) {
        state.committed_observer_mode = std::min<u32>(
            ui_overlay_state().default_chat_channel, 3u);
        state.pending_observer_mode = state.committed_observer_mode;
        state.committed_observer_mask = g_gameplay_chat_target_mask & 0xffu;
        state.pending_observer_mask = state.committed_observer_mask;
    }
    state.compact_observer_flags =
        gameplay_script_trigger_state().opcode_context.resource_hud_flags;
    sync_default_gameplay_modal_players(state);
    state.sound_options_available = direct_sound_state().active;
    state.unit_resource_pack_variant =
        (ImportSetupU32(kSetupUiFlagsOffset,
            unit_definition_resource_catalog_state().alternate_pack_active ? 0x20u : 0u) &
            0x20u) != 0;
    state.music_volume_left =
        static_cast<int>(default_gameplay_speed_index(
            gameplay_loop_state().frame_interval_index));
    state.music_volume_raw =
        static_cast<int>(std::min<u32>(
            miles_music_state().primary_policy_raw_volume, 0xffffu));
    state.sound_volume_raw =
        std::clamp(g_runtime.gameplay_sound.listener_position_offset, -10000, 0);
    state.music_volume_right = static_cast<int>(default_camera_scroll_speed_index(
        ImportSetupU32(kSetupSecondaryTimingOffset,
            static_cast<u32>(std::max(state.music_volume_right, 0)))));
    state.scroll_speed = static_cast<int>(ImportSetupU32(
        kSetupScrollSpeedOffset, static_cast<u32>(std::max(state.scroll_speed, 0))));
    if (state.callbacks.scan_save_slot_headers == nullptr) {
        state.callbacks.scan_save_slot_headers =
            default_gameplay_modal_scan_save_slot_headers;
    }
    if (state.callbacks.import_session_bundle == nullptr) {
        state.callbacks.import_session_bundle =
            default_gameplay_modal_import_session_bundle;
    }
    if (state.callbacks.export_session_bundle == nullptr) {
        state.callbacks.export_session_bundle =
            default_gameplay_modal_export_session_bundle;
    }
    if (state.callbacks.clear_reliable_packet_rings == nullptr) {
        state.callbacks.clear_reliable_packet_rings =
            default_gameplay_modal_clear_reliable_packet_rings;
    }
    if (state.callbacks.import_runtime_tables == nullptr) {
        state.callbacks.import_runtime_tables =
            default_gameplay_modal_import_runtime_tables;
    }
    if (state.callbacks.import_non_empty_runtime_tables == nullptr) {
        state.callbacks.import_non_empty_runtime_tables =
            default_gameplay_modal_import_non_empty_runtime_tables;
    }
    if (state.callbacks.rebuild_unit_type_references == nullptr) {
        state.callbacks.rebuild_unit_type_references =
            default_gameplay_modal_rebuild_unit_type_references;
    }
    if (state.callbacks.publish_corrective_checksum == nullptr) {
        state.callbacks.publish_corrective_checksum =
            default_gameplay_modal_publish_corrective_checksum;
    }
    if (state.callbacks.publish_modal_pause == nullptr) {
        state.callbacks.publish_modal_pause =
            default_gameplay_modal_publish_modal_pause;
    }
    if (state.callbacks.reset_and_publish_inactive == nullptr) {
        state.callbacks.reset_and_publish_inactive =
            default_gameplay_modal_reset_and_publish_inactive;
    }
    if (state.callbacks.publish_relation_mask == nullptr) {
        state.callbacks.publish_relation_mask =
            default_gameplay_modal_publish_relation_mask;
    }
    if (state.callbacks.update_catchup_target == nullptr) {
        state.callbacks.update_catchup_target =
            default_gameplay_modal_update_catchup_target;
    }
    if (state.callbacks.toggle_catchup == nullptr) {
        state.callbacks.toggle_catchup =
            default_gameplay_modal_toggle_catchup;
    }
    if (state.callbacks.pause_music == nullptr) {
        state.callbacks.pause_music = default_gameplay_modal_pause_music;
    }
    if (state.callbacks.resume_music == nullptr) {
        state.callbacks.resume_music = default_gameplay_modal_resume_music;
    }
    if (state.callbacks.apply_music_volume == nullptr) {
        state.callbacks.apply_music_volume =
            default_gameplay_modal_apply_music_volume;
    }
    if (state.callbacks.apply_setup_data == nullptr) {
        state.callbacks.apply_setup_data =
            default_gameplay_modal_apply_setup_data;
    }
    if (state.callbacks.toggle_unit_resource_pack == nullptr) {
        state.callbacks.toggle_unit_resource_pack =
            default_gameplay_modal_toggle_unit_resource_pack;
    }
    if (state.callbacks.apply_observer_settings == nullptr) {
        state.callbacks.apply_observer_settings =
            default_gameplay_modal_apply_observer_settings;
    }
    if (state.callbacks.apply_compact_observer_flags == nullptr) {
        state.callbacks.apply_compact_observer_flags =
            default_gameplay_modal_apply_compact_observer_flags;
    }
    if (state.callbacks.exit_worker_thread == nullptr) {
        state.callbacks.exit_worker_thread =
            default_gameplay_modal_exit_worker_thread;
    }
    if (state.callbacks.show_message == nullptr) {
        state.callbacks.show_message = default_gameplay_modal_show_message;
    }
    if (state.callbacks.send_replay_modal_action == nullptr) {
        state.callbacks.send_replay_modal_action =
            default_gameplay_modal_send_replay_modal_action;
    }
    if (state.callbacks.trc_fatal_error == nullptr) {
        state.callbacks.trc_fatal_error =
            default_gameplay_modal_trc_fatal_error;
    }
}

