const char* resolve_gameplay_session_archive_path() {
    const auto existing_file = [](const char* path) -> const char* {
        if (path == nullptr || path[0] == '\0') {
            return nullptr;
        }
        const DWORD attributes = GetFileAttributesA(path);
        return attributes != INVALID_FILE_ATTRIBUTES &&
            (attributes & FILE_ATTRIBUTE_DIRECTORY) == 0 ? path : nullptr;
    };

    const GameplayLaunchSource source = g_runtime.gameplay_launch_source;
    if (GameplayLaunchUsesReplay(source)) {
        const ReplayRecordingState& replay = replay_recording_state();
        return replay.playback_mode ?
            existing_file(replay.playback_archive_path.c_str()) : nullptr;
    }
    if (GameplayLaunchUsesCommandLineP2P(source)) {
        const P2PNetworkLaunchParameters& launch =
            p2p_network_launch_parameters();
        if (launch.uses_map_file) {
            return existing_file(launch.map_path.data());
        }
        // A command-line join receives its map through the Link room.
    }
    if (GameplayLaunchUsesLinkLobby(source)) {
        // Original Link startup passes the current DAT_01244a40 map path
        // directly into the synchronous importer.  Read only this launch's
        // Link handoff instead of searching every retained frontend singleton.
        return existing_file(link_lobby_state().prepared_map_path.c_str());
    }
    if (GameplayLaunchUsesWizardSession(source)) {
        const WizardLoginState& wizard = wizard_login_state();
        return !wizard.selected_session.invalid ?
            existing_file(wizard.selected_session.archive_path.data()) : nullptr;
    }
    return nullptr;
}

u32 resolve_gameplay_launch_resource_theme() {
    const GameplayLaunchSource source = g_runtime.gameplay_launch_source;
    if (GameplayLaunchUsesReplay(source)) {
        // FUN_0049e100 copies the replay header before session import.  Its
        // metadata begins at 0x63 and contains the Link tribe bytes at +0x50.
        const ReplayRecordingState& replay = replay_recording_state();
        return ResolveReplayGameplayTheme(replay.playback_payload.data(),
            replay.playback_payload.size());
    }
    if (GameplayLaunchUsesLinkLobby(source)) {
        const LinkLobbyState& lobby = link_lobby_state();
        const int local_index = std::clamp(
            lobby.local_player_index, 0, kLinkLobbyAvatarCount - 1);
        const u32 theme = lobby.tribe_choices[local_index];
        return theme <= 3 ? theme : 0u;
    }
    return 0;
}

MinimapPixelFormat default_gameplay_minimap_pixel_format() {
    const bool pixel_mode_555 = SurfacePixelMode555();

    MinimapPixelFormat format{};
    format.red_mask = pixel_mode_555 ? 0x7c00u : 0xf800u;
    format.green_mask = pixel_mode_555 ? 0x03e0u : 0x07e0u;
    format.blue_mask = 0x001fu;
    format.red_shift = pixel_mode_555 ? 10u : 11u;
    format.green_shift = 5u;
    format.blue_shift = 0u;
    format.pixel_mode_555 = pixel_mode_555;
    return format;
}

u32 default_gameplay_terrain_component_limit(u32 mask, u32 shift) {
    return mask == 0 ? 0 : mask >> (shift & 0x1f);
}

u32 default_gameplay_terrain_component(u16 pixel, u32 mask, u32 shift) {
    return (static_cast<u32>(pixel) & mask) >> (shift & 0x1f);
}

u16 default_gameplay_pack_terrain_pixel(
    const MinimapPixelFormat& format, u32 red, u32 green, u32 blue) {
    red = std::min(red,
        default_gameplay_terrain_component_limit(format.red_mask, format.red_shift));
    green = std::min(green,
        default_gameplay_terrain_component_limit(format.green_mask, format.green_shift));
    blue = std::min(blue,
        default_gameplay_terrain_component_limit(format.blue_mask, format.blue_shift));
    return static_cast<u16>(
        ((red & 0xffffu) << (format.red_shift & 0x1f)) |
        ((green & 0xffffu) << (format.green_shift & 0x1f)) |
        ((blue & 0xffffu) << (format.blue_shift & 0x1f)));
}

bool default_gameplay_terrain_tile_index_valid(
    const TerrainTileSheetState& tile_sheet, i32 tile_index) {
    if (tile_index < 0 ||
        static_cast<u32>(tile_index) >= tile_sheet.tile_count) {
        return false;
    }
    const std::size_t pixel_offset =
        static_cast<std::size_t>(tile_index) * kTerrainTilePixelsPerTile;
    return pixel_offset + kTerrainTilePixelsPerTile <=
        tile_sheet.tile_pixels.size();
}

i32 default_gameplay_terrain_tile_index(
    u32 terrain_code, i32 tile_x, i32 tile_y, u32 animation_slot) {
    terrain_code &= 7u;
    i32 offset = kGameplayTerrainTileOffsets[terrain_code];
    if (terrain_code == 6) {
        offset += static_cast<i32>(animation_slot * 0xc8u);
    }
    return offset + ResolveMinimapTilePatternIndex(tile_x, tile_y);
}

const u16* default_gameplay_terrain_tile_pixels(
    const TerrainTileSheetState& tile_sheet, i32 tile_index) {
    if (!default_gameplay_terrain_tile_index_valid(tile_sheet, tile_index)) {
        return nullptr;
    }
    return tile_sheet.tile_pixels.data() +
        static_cast<std::size_t>(tile_index) * kTerrainTilePixelsPerTile;
}

void default_gameplay_draw_uniform_terrain_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 animation_slot) {
    const u32 terrain_code = command.terrain_flags & 7u;
    const i32 tile_index = default_gameplay_terrain_tile_index(
        terrain_code, command.tile_x, command.tile_y, animation_slot);
    const u16* source = default_gameplay_terrain_tile_pixels(tile_sheet, tile_index);
    if (source == nullptr) {
        return;
    }

    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    for (i32 row = 0; row < command.clip.height; ++row) {
        const u16* source_row = source +
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u +
            static_cast<std::size_t>(command.clip.src_x);
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        std::copy_n(source_row, static_cast<std::size_t>(command.clip.width),
            target_row);
    }
}

void default_gameplay_draw_average_blended_terrain_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 animation_slot) {
    std::array<const u16*, kGameplayTerrainBlendCodeShifts.size()> sources{};
    std::size_t source_count = 0;
    for (u32 shift : kGameplayTerrainBlendCodeShifts) {
        const u32 terrain_code = (command.terrain_flags >> shift) & 7u;
        const i32 tile_index = default_gameplay_terrain_tile_index(
            terrain_code, command.tile_x, command.tile_y, animation_slot);
        const u16* source = default_gameplay_terrain_tile_pixels(tile_sheet, tile_index);
        if (source != nullptr) {
            sources[source_count++] = source;
        }
    }
    if (source_count == 0) {
        return;
    }

    const MinimapPixelFormat format = default_gameplay_minimap_pixel_format();
    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    for (i32 row = 0; row < command.clip.height; ++row) {
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        const std::size_t source_row =
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u;
        for (i32 col = 0; col < command.clip.width; ++col) {
            const std::size_t source_pixel = source_row +
                static_cast<std::size_t>(command.clip.src_x + col);
            u32 red = 0;
            u32 green = 0;
            u32 blue = 0;
            for (std::size_t source_index = 0; source_index < source_count;
                 ++source_index) {
                const u16 pixel = sources[source_index][source_pixel];
                red += default_gameplay_terrain_component(
                    pixel, format.red_mask, format.red_shift);
                green += default_gameplay_terrain_component(
                    pixel, format.green_mask, format.green_shift);
                blue += default_gameplay_terrain_component(
                    pixel, format.blue_mask, format.blue_shift);
            }
            target_row[col] = default_gameplay_pack_terrain_pixel(format,
                red / static_cast<u32>(source_count),
                green / static_cast<u32>(source_count),
                blue / static_cast<u32>(source_count));
        }
    }
}

i32 default_gameplay_terrain_blend_mask_tile_index(
    const TerrainTileDrawCommand& command) {
    const u32 mask_id = (command.terrain_flags >> 0x12) & 0x3fu;
    const u32 variant = (command.terrain_flags >> 0x18) & 3u;
    const std::size_t offset_index =
        static_cast<std::size_t>(mask_id) * 2u + variant;
    i32 base = kGameplayTerrainBlendMaskBaseOffset;
    if ((command.tile_x & 1) == 0) {
        ++base;
    }
    if (offset_index >= kGameplayTerrainBlendMaskOffsets.size()) {
        return base;
    }
    return base + kGameplayTerrainBlendMaskOffsets[offset_index];
}

void default_gameplay_draw_blended_terrain_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 animation_slot) {
    std::array<const u16*, kGameplayTerrainBlendCodeShifts.size()> sources{};
    for (std::size_t source_index = 0;
         source_index < kGameplayTerrainBlendCodeShifts.size(); ++source_index) {
        const u32 shift = kGameplayTerrainBlendCodeShifts[source_index];
        const u32 terrain_code = (command.terrain_flags >> shift) & 7u;
        const i32 tile_index = default_gameplay_terrain_tile_index(
            terrain_code, command.tile_x, command.tile_y, animation_slot);
        sources[source_index] =
            default_gameplay_terrain_tile_pixels(tile_sheet, tile_index);
    }

    const i32 mask_tile_index =
        default_gameplay_terrain_blend_mask_tile_index(command);
    const u16* mask = default_gameplay_terrain_tile_pixels(
        tile_sheet, mask_tile_index);
    if (mask == nullptr) {
        default_gameplay_draw_average_blended_terrain_tile(
            tile_sheet, command, target, animation_slot);
        return;
    }

    const MinimapPixelFormat format = default_gameplay_minimap_pixel_format();
    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    const u32 green_weight_shift =
        format.green_shift + (format.pixel_mode_555 ? 0u : 1u);
    for (i32 row = 0; row < command.clip.height; ++row) {
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        const std::size_t source_row =
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u;
        for (i32 col = 0; col < command.clip.width; ++col) {
            const std::size_t source_pixel = source_row +
                static_cast<std::size_t>(command.clip.src_x + col);
            const u32 mask_sample_column =
                ResolveGameplayTerrainBlendMaskSampleColumn(
                    static_cast<u32>(command.clip.width),
                    static_cast<u32>(col));
            const std::size_t mask_pixel_index = source_row +
                static_cast<std::size_t>(command.clip.src_x) +
                mask_sample_column;
            const u16 mask_pixel = mask[mask_pixel_index];
            std::size_t primary_index = 5;
            std::size_t secondary_index = 2;
            u32 weight = mask_pixel & 0x1fu;
            if ((mask_pixel & static_cast<u16>(format.green_mask)) != 0) {
                primary_index = 4;
                secondary_index = 1;
                weight = (static_cast<u32>(mask_pixel) >>
                             (green_weight_shift & 0x1f)) &
                    0x1fu;
            }
            else if ((mask_pixel & static_cast<u16>(format.red_mask)) != 0) {
                primary_index = 3;
                secondary_index = 0;
                weight = (static_cast<u32>(mask_pixel) >>
                             (format.red_shift & 0x1f)) &
                    0x1fu;
            }

            const u16* primary = sources[primary_index];
            const u16* secondary = sources[secondary_index];
            if (primary == nullptr || secondary == nullptr) {
                continue;
            }
            target_row[col] = BlendGameplayTerrainPixels(format,
                primary[source_pixel], secondary[source_pixel], weight);
        }
    }
}

u32 default_gameplay_overlay_id(u32 overlay_flags, u32 slot) {
    switch (slot) {
    case 0:
        return overlay_flags & 0x3fu;
    case 1:
        return (overlay_flags >> 8) & 0x3fu;
    case 2:
        return (overlay_flags >> 0x10) & 0x3fu;
    case 3:
        return (overlay_flags >> 0x18) & 0x3fu;
    default:
        return 0;
    }
}

u32 default_gameplay_overlay_variant(u32 overlay_flags, u32 slot) {
    switch (slot) {
    case 0:
        return (overlay_flags >> 6) & 3u;
    case 1:
        return (overlay_flags >> 0x0e) & 3u;
    case 2:
        return (overlay_flags >> 0x16) & 3u;
    case 3:
        return overlay_flags >> 0x1e;
    default:
        return 0;
    }
}

i32 default_gameplay_overlay_palette_tile_index(u32 overlay_id, u32 variant) {
    const std::size_t index =
        static_cast<std::size_t>(overlay_id & 0x3fu) * 4u +
        (variant & 3u);
    if (index >= kGameplayOverlayVariantOffsets.size()) {
        return kGameplayOverlayPaletteBaseOffset;
    }
    return kGameplayOverlayPaletteBaseOffset +
        kGameplayOverlayVariantOffsets[index];
}

i32 default_gameplay_overlay_blend_mask_tile_index(u32 overlay_id) {
    if (overlay_id >= kGameplayOverlayBlendMaskOffsets.size()) {
        return -1;
    }
    const i32 offset = kGameplayOverlayBlendMaskOffsets[overlay_id];
    if (offset < 0) {
        return offset;
    }
    return kGameplayOverlayBlendMaskBaseOffset + offset;
}

void default_gameplay_draw_transparent_overlay_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 overlay_id, u32 variant) {
    const i32 tile_index =
        default_gameplay_overlay_palette_tile_index(overlay_id, variant);
    const u16* source = default_gameplay_terrain_tile_pixels(tile_sheet, tile_index);
    if (source == nullptr) {
        return;
    }

    const MinimapPixelFormat format = default_gameplay_minimap_pixel_format();
    const u16 transparent = static_cast<u16>(format.green_mask);
    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    for (i32 row = 0; row < command.clip.height; ++row) {
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        const std::size_t source_row =
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u;
        for (i32 col = 0; col < command.clip.width; ++col) {
            const u16 pixel = source[source_row +
                static_cast<std::size_t>(command.clip.src_x + col)];
            if (pixel != transparent) {
                target_row[col] = pixel;
            }
        }
    }
}

void default_gameplay_draw_masked_overlay_tile_index(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, i32 overlay_tile_index, u32 animation_slot,
    bool special_overlay_preclipped = false) {
    const i32 fill_tile_index = default_gameplay_terrain_tile_index(
        5, command.tile_x, command.tile_y, animation_slot);
    const u16* overlay =
        default_gameplay_terrain_tile_pixels(tile_sheet, overlay_tile_index);
    const u16* fill =
        default_gameplay_terrain_tile_pixels(tile_sheet, fill_tile_index);
    if (overlay == nullptr || fill == nullptr) {
        return;
    }

    const MinimapPixelFormat format = default_gameplay_minimap_pixel_format();
    const u16 transparent = static_cast<u16>(format.green_mask);
    const u16 fill_token =
        static_cast<u16>(format.red_mask | format.blue_mask);
    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    for (i32 row = 0; row < command.clip.height; ++row) {
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        const std::size_t source_row =
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u;
        // FUN_00422a60 clips the special 0x3f overlay and advances its source
        // pointer before calling FUN_00422d90.  The latter clips the adjusted
        // destination again, so its terrain-5 fill source restarts at the
        // visible rectangle's (0, 0), while the overlay source retains the
        // first clip offset.  This matters at the left/top viewport edge.
        const std::size_t fill_row = special_overlay_preclipped ?
            static_cast<std::size_t>(row) * 0x20u : source_row;
        for (i32 col = 0; col < command.clip.width; ++col) {
            const std::size_t source_pixel = source_row +
                static_cast<std::size_t>(command.clip.src_x + col);
            const std::size_t fill_pixel = fill_row +
                static_cast<std::size_t>(special_overlay_preclipped ?
                    col : command.clip.src_x + col);
            const u16 pixel = overlay[source_pixel];
            if (pixel == transparent) {
                continue;
            }
            target_row[col] = pixel == fill_token ? fill[fill_pixel] : pixel;
        }
    }
}

void default_gameplay_draw_masked_overlay_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 overlay_id, u32 variant,
    u32 animation_slot) {
    default_gameplay_draw_masked_overlay_tile_index(tile_sheet, command, target,
        default_gameplay_overlay_palette_tile_index(overlay_id, variant),
        animation_slot);
}

void default_gameplay_draw_blended_overlay_tile_index(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, i32 overlay_tile_index, i32 blend_mask_tile_index) {
    const u16* overlay =
        default_gameplay_terrain_tile_pixels(tile_sheet, overlay_tile_index);
    const u16* blend_mask =
        default_gameplay_terrain_tile_pixels(tile_sheet, blend_mask_tile_index);
    if (overlay == nullptr || blend_mask == nullptr) {
        return;
    }

    const MinimapPixelFormat format = default_gameplay_minimap_pixel_format();
    const u16 transparent = static_cast<u16>(format.green_mask);
    const u32 target_pitch = target.stride_words != 0 ?
        target.stride_words : target.width;
    for (i32 row = 0; row < command.clip.height; ++row) {
        u16* target_row = target.pixels +
            static_cast<std::size_t>(command.clip.dst_y + row) * target_pitch +
            static_cast<std::size_t>(command.clip.dst_x);
        const std::size_t source_row =
            static_cast<std::size_t>(command.clip.src_y + row) * 0x20u;
        for (i32 col = 0; col < command.clip.width; ++col) {
            const std::size_t source_pixel = source_row +
                static_cast<std::size_t>(command.clip.src_x + col);
            const u16 overlay_pixel = overlay[source_pixel];
            if (overlay_pixel == transparent) {
                continue;
            }
            const u32 weight = blend_mask[source_pixel] & 0x1fu;
            if (weight == 0) {
                continue;
            }
            target_row[col] = BlendGameplayTerrainPixels(format,
                overlay_pixel, target_row[col], weight);
        }
    }
}

void default_gameplay_draw_blended_overlay_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 overlay_id, u32 variant,
    i32 blend_mask_tile_index) {
    default_gameplay_draw_blended_overlay_tile_index(tile_sheet, command, target,
        default_gameplay_overlay_palette_tile_index(overlay_id, variant),
        blend_mask_tile_index);
}

bool default_gameplay_draw_special_overlay_terrain_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 animation_slot) {
    const u32 row = default_gameplay_overlay_id(command.overlay_flags, 2);
    const u32 column = default_gameplay_overlay_id(command.overlay_flags, 3);
    const std::size_t index =
        static_cast<std::size_t>(row) * 41u + column;
    if (index >= kGameplaySpecialOverlayPaletteOffsets.size()) {
        return false;
    }

    const i32 overlay_tile_index = 0x0af0 +
        kGameplaySpecialOverlayPaletteOffsets[index];
    const i32 mask_offset = kGameplaySpecialOverlayBlendMaskOffsets[index];
    if (mask_offset < 0) {
        default_gameplay_draw_masked_overlay_tile_index(
            tile_sheet, command, target, overlay_tile_index, animation_slot,
            true);
    }
    else {
        default_gameplay_draw_blended_overlay_tile_index(tile_sheet, command,
            target, overlay_tile_index,
            kGameplayOverlayBlendMaskBaseOffset + mask_offset);
    }
    return true;
}

void default_gameplay_draw_overlay_terrain_tile(
    const TerrainTileSheetState& tile_sheet, const TerrainTileDrawCommand& command,
    SpriteRenderTarget& target, u32 animation_slot) {
    if (default_gameplay_overlay_id(command.overlay_flags, 0) == 0x3fu) {
        (void)default_gameplay_draw_special_overlay_terrain_tile(
            tile_sheet, command, target, animation_slot);
        return;
    }

    for (i32 slot = 3; slot >= 0; --slot) {
        const u32 overlay_id =
            default_gameplay_overlay_id(command.overlay_flags, static_cast<u32>(slot));
        if (overlay_id == 0) {
            continue;
        }
        const u32 variant = default_gameplay_overlay_variant(
            command.overlay_flags, static_cast<u32>(slot));
        const i32 blend_mask_tile =
            default_gameplay_overlay_blend_mask_tile_index(overlay_id);
        if (blend_mask_tile >= 0) {
            default_gameplay_draw_blended_overlay_tile(
                tile_sheet, command, target, overlay_id, variant, blend_mask_tile);
        }
        else if (overlay_id < kGameplayOverlayMaskedKinds.size() &&
                 kGameplayOverlayMaskedKinds[overlay_id] == 1) {
            default_gameplay_draw_masked_overlay_tile(
                tile_sheet, command, target, overlay_id, variant, animation_slot);
        }
        else {
            default_gameplay_draw_transparent_overlay_tile(
                tile_sheet, command, target, overlay_id, variant);
        }
    }
}

u32 default_gameplay_session_terrain_bank_index() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionMapRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionMapRecordIndex]) {
        return 0;
    }

    const std::vector<u8>& record = load.records[kGameplaySessionMapRecordIndex];
    if (kSessionMapRecordTerrainBankOffset + sizeof(u32) > record.size()) {
        return 0;
    }

    return static_cast<u32>(record[kSessionMapRecordTerrainBankOffset]) |
        (static_cast<u32>(record[kSessionMapRecordTerrainBankOffset + 1]) << 8) |
        (static_cast<u32>(record[kSessionMapRecordTerrainBankOffset + 2]) << 16) |
        (static_cast<u32>(record[kSessionMapRecordTerrainBankOffset + 3]) << 24);
}

bool load_default_gameplay_terrain_tile_sheet_bank() {
    const u32 bank_index = default_gameplay_session_terrain_bank_index();
    return LoadTerrainTileSheetBank(g_runtime.gameplay_terrain_tile_sheet,
        "JW2_03.TRC", static_cast<i32>(bank_index),
        default_gameplay_minimap_pixel_format(), kOriginalColorDepth);
}

void configure_default_gameplay_minimap_render_config(
    MinimapTerrainRenderConfig& config) {
    ConfigureGameplayMinimapTerrainLayout(config);
    config.pixel_format = default_gameplay_minimap_pixel_format();
    config.animated_terrain_bank =
        g_runtime.gameplay_frame_render_context.animation_frame_slot;
    config.minimap_tile_palette =
        g_runtime.gameplay_terrain_tile_sheet.average_pixels;
}

void ensure_default_ui_overlay_minimap_surface(UiOverlayState& overlay) {
    ConfigureGameplayUiOverlayLayout(overlay);
    if (overlay.minimap.map_width_tiles == 0) {
        overlay.minimap.map_width_tiles = overlay.map_width_tiles;
    }
    if (overlay.minimap.map_height_tiles == 0) {
        overlay.minimap.map_height_tiles = overlay.map_height_tiles;
    }
    if (overlay.minimap.viewport_width_pixels == 0) {
        overlay.minimap.viewport_width_pixels = overlay.screen_width;
    }
    if (overlay.minimap.viewport_height_pixels == 0) {
        overlay.minimap.viewport_height_pixels = overlay.screen_height;
    }
    if (overlay.minimap.output_pitch_pixels == 0) {
        overlay.minimap.output_pitch_pixels = overlay.screen_width;
    }
    if (overlay.minimap.output_height_pixels == 0) {
        overlay.minimap.output_height_pixels = overlay.screen_height;
    }
}

void prepare_default_ui_overlay_minimap_base(UiOverlayState& overlay) {
    if (!g_runtime.gameplay_terrain_tile_sheet_loaded ||
        g_runtime.gameplay_terrain_tile_sheet.average_pixels.empty() ||
        g_runtime.gameplay_terrain_layer.terrain_flags.empty()) {
        return;
    }

    ensure_default_ui_overlay_minimap_surface(overlay);
    configure_default_gameplay_minimap_render_config(
        g_runtime.gameplay_minimap_render_config);
    const u32 simulation_frame =
        gameplay_loop_state().simulation_frame_counter;
    const MinimapRenderState& minimap = overlay.minimap;
    const MinimapTerrainLayer& terrain = g_runtime.gameplay_terrain_layer;
    const GameplayMinimapBaseFrameCache& cache =
        g_gameplay_minimap_base_frame_cache;
    if (cache.valid && cache.simulation_frame == simulation_frame &&
        cache.animation_slot ==
            g_runtime.gameplay_minimap_render_config.animated_terrain_bank &&
        cache.map_width_tiles == terrain.width_tiles &&
        cache.map_height_tiles == terrain.height_tiles &&
        cache.minimap_width_pixels == minimap.minimap_width_pixels &&
        cache.minimap_height_pixels == minimap.minimap_height_pixels &&
        cache.pixel_mode_555 == SurfacePixelMode555()) {
        return;
    }
    RenderMinimapTerrainBase(overlay.minimap,
        g_runtime.gameplay_terrain_layer,
        g_runtime.gameplay_minimap_render_config);
    GameplayMinimapBaseFrameCache& updated =
        g_gameplay_minimap_base_frame_cache;
    updated.simulation_frame = simulation_frame;
    updated.animation_slot =
        g_runtime.gameplay_minimap_render_config.animated_terrain_bank;
    updated.map_width_tiles = terrain.width_tiles;
    updated.map_height_tiles = terrain.height_tiles;
    updated.minimap_width_pixels = minimap.minimap_width_pixels;
    updated.minimap_height_pixels = minimap.minimap_height_pixels;
    updated.pixel_mode_555 = SurfacePixelMode555();
    updated.valid = true;
}

bool default_gameplay_flow_import_session_bundle(GameplaySessionFlowState& state) {
    state.loaded_resource_base = 0xffffffffu;
    state.loaded_palette_slot = 0xffffffffu;
    state.loaded_resource_base_owned = false;
    g_runtime.gameplay_session_bundle_loaded = false;
    g_runtime.gameplay_terrain_tile_sheet_loaded = false;
    g_runtime.gameplay_session_archive_path.clear();

    if (!g_runtime.directx_initialized || !direct_draw_state().active) {
        append_startup_log(
            "gameplay import blocked because the display surface is inactive");
        OutputDebugStringA(
            "Gameplay session import blocked because the display surface is inactive.\n");
        return false;
    }

    const char* archive_path = resolve_gameplay_session_archive_path();
    if (archive_path == nullptr || archive_path[0] == '\0') {
        append_startup_log("gameplay import missing selected session archive");
        OutputDebugStringA(
            "Gameplay session import callback reached without a selected session "
            "archive.\n");
        return false;
    }

    g_runtime.gameplay_session_archive_path = archive_path;
    SetRuntimeResourceThemeIndex(resolve_gameplay_launch_resource_theme());
    SetReplayControlsEnabled(replay_recording_state().playback_mode);
    const bool bundle_imported = HandleGameplaySessionBundleImport(
        archive_path, 0, load_default_gameplay_terrain_tile_sheet_bank);
    if (!bundle_imported) {
        report_gameplay_session_import_resource_failure();
    }
    g_runtime.gameplay_session_bundle_loaded = bundle_imported;
    g_runtime.gameplay_terrain_tile_sheet_loaded =
        bundle_imported && TerrainTileSheetBankAllocationsValid(
            g_runtime.gameplay_terrain_tile_sheet);
    if (g_runtime.gameplay_session_bundle_loaded &&
        !import_default_owner_ai_snapshot_from_session_records()) {
        g_runtime.gameplay_session_bundle_loaded = false;
    }
    if (!g_runtime.gameplay_session_bundle_loaded) {
        ReleaseTerrainTileSheetBankResources(g_runtime.gameplay_terrain_tile_sheet);
        g_runtime.gameplay_terrain_tile_sheet_loaded = false;
    }

    char text[512]{};
    std::snprintf(text, sizeof(text),
        "Gameplay session bundle import %s for '%s' (terrain=%s).\n",
        g_runtime.gameplay_session_bundle_loaded ? "succeeded" : "failed",
        g_runtime.gameplay_session_archive_path.c_str(),
        g_runtime.gameplay_terrain_tile_sheet_loaded ? "loaded" : "not loaded");
    append_startup_log("gameplay import %s archive=%s terrain=%s",
        g_runtime.gameplay_session_bundle_loaded ? "ok" : "failed",
        g_runtime.gameplay_session_archive_path.c_str(),
        g_runtime.gameplay_terrain_tile_sheet_loaded ? "ok" : "failed");
    OutputDebugStringA(text);
    return g_runtime.gameplay_session_bundle_loaded;
}

const UnitMovementDefinition* default_unit_lifecycle_find_definition(
    UnitLifecycleContext& lifecycle, u32 unit_type);

void default_gameplay_startup_unit_placed(UnitMovementUnit& unit) {
    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    UnitMovementContext* movement =
        lifecycle != nullptr ? lifecycle->movement : nullptr;
    if (movement == nullptr) {
        append_startup_log(
            "start-slots: unit placed skipped missing movement id=%lu type=%lu owner=%lu",
            static_cast<unsigned long>(unit.id),
            static_cast<unsigned long>(unit.type_id),
            static_cast<unsigned long>(unit.owner_id));
        return;
    }

    auto remove_unit = [&unit](std::vector<UnitMovementUnit*>& units) {
        units.erase(std::remove(units.begin(), units.end(), &unit), units.end());
    };
    remove_unit(movement->free_units);
    remove_unit(movement->lifecycle_units);
    remove_unit(movement->active_units);
    unit.active = true;
    unit.linked_unit = &unit;
    movement->active_units.insert(movement->active_units.begin(), &unit);
    append_startup_log(
        "start-slots: unit placed id=%lu type=%lu owner=%lu xy=%ld,%ld active_units=%zu placed=%zu",
        static_cast<unsigned long>(unit.id),
        static_cast<unsigned long>(unit.type_id),
        static_cast<unsigned long>(unit.owner_id),
        static_cast<long>(unit.x), static_cast<long>(unit.y),
        movement->active_units.size(),
        g_runtime.gameplay_startup_state.placed_units.size());
}

void default_gameplay_startup_initialize_local_camera(i32 x, i32 y) {
    sync_default_ui_overlay_runtime_from_gameplay_state();
    UiOverlayState& overlay = ui_overlay_state();
    ConfigureGameplayUiOverlayLayout(overlay);
    ClampCameraToMinimapPoint(overlay, x, y);
    SeedInitialCameraBookmark(overlay);
    publish_default_ui_overlay_camera(overlay);

    GameplayHudAlertMarkerState& markers = g_runtime.gameplay_hud_alert_markers;
    markers.last_alert_world_x = overlay.camera_x;
    markers.last_alert_world_y = overlay.camera_y;
    markers.last_alert_valid = true;
    overlay.stored_minimap_world_x = overlay.camera_x;
    overlay.stored_minimap_world_y = overlay.camera_y;
    overlay.stored_minimap_point_valid = true;
}

void default_gameplay_startup_after_session_snapshot(
    const std::vector<u8>& snapshot) {
    (void)snapshot;
    // append_snapshot is a reconstruction-only compact diagnostic view
    // (eight bytes per owner), not the original 0x374-byte P_PLAYE layout.
    // Copying it over record 3 corrupts factions, resources and start points
    // before the first save.  Keep the imported raw record and update only its
    // evidenced live fields in their original offsets.
    sync_default_gameplay_player_session_record();
}

void default_gameplay_session_update_owner_display_name(
    GameplaySessionRuntimeResetState& state, u32 owner) {
    if (owner >= state.owner_display_names.size() ||
        owner >= g_runtime.gameplay_startup_state.owner_display_names.size()) {
        return;
    }
    g_runtime.gameplay_startup_state.owner_display_names[owner] =
        state.owner_display_names[owner];
}

void default_gameplay_session_unit_reset_or_removed(
    GameplaySessionRuntimeResetState&, UnitMovementUnit& unit) {
    if (unit.active) {
        return;
    }

    unit.target = nullptr;
    unit.linked_unit = nullptr;
    unit.pending_command = UnitQueuedCommand{};
    unit.active_command_payload = UnitQueuedCommand{};
    unit.deferred_commands = {};
    unit.deferred_command_count = 0;
}

void sync_default_gameplay_session_runtime_views_after_reset() {
    UnitMovementContext* movement = default_gameplay_movement_context();
    if (movement == nullptr) {
        g_runtime.gameplay_damage_record_links.clear();
        g_runtime.gameplay_damage_context.active_units.clear();
        g_runtime.gameplay_targeting_context = UnitTargetingContext{};
        return;
    }

    purge_default_inactive_movement_units(*movement);
    rebuild_default_unit_spatial_indexes();
    rebuild_default_damage_record_links(movement, nullptr, nullptr);
    g_runtime.gameplay_targeting_context = UnitTargetingContext{};
    g_runtime.gameplay_targeting_context.active_units =
        g_runtime.gameplay_damage_context.active_units;
    sync_default_gameplay_end_condition_state();
}

void default_gameplay_startup_reset_runtime_objects() {
    const u32 start_tick = RefreshLegacyTickTime();
    g_runtime.gameplay_session_start_tick_ms = start_tick;
    GameplayLoopState& loop = gameplay_loop_state();
    loop.current_tick_ms = start_tick;
    loop.frame_time_anchor = start_tick;
    loop.simulation_frame_counter = 0;
    loop.present_frame_counter = 0;
    reset_default_gameplay_terrain_frame_cache();

    g_runtime.gameplay_end_condition_state = GameplayEndConditionState{};
    g_runtime.gameplay_end_condition_state.scenario_victory_condition_mask =
        g_runtime.gameplay_startup_state.scenario_victory_condition_mask;
    g_runtime.gameplay_end_condition_state.scenario_defeat_condition_mask =
        g_runtime.gameplay_startup_state.scenario_defeat_condition_mask;
    g_runtime.gameplay_started_player_mask = 0;
    g_runtime.gameplay_end_condition_units.clear();
    g_runtime.gameplay_online_transition_state = GameplayOnlineTransitionState{};
    g_runtime.gameplay_result_screen_rendered = false;
    g_runtime.gameplay_leave_reset_processed = false;

    GameplayModalUiState& modal = gameplay_modal_ui_state();
    modal.committed_observer_mode = 3;
    modal.pending_observer_mode = 3;
    modal.committed_observer_mask = 0;
    modal.pending_observer_mask = 0;

    ResetCameraBookmarks(ui_overlay_state());
    ExportSetupU32(kSetupVisibilityGateOffset,
        g_runtime.gameplay_startup_state.fog_reveal_disabled ? 0u : 1u);
}

void reset_default_gameplay_startup_slots(GameplaySessionStartupState& startup) {
    startup = GameplaySessionStartupState{};
    g_runtime.gameplay_movement_context = UnitMovementContext{};
    g_runtime.gameplay_lifecycle_context = UnitLifecycleContext{};
    g_runtime.gameplay_lifecycle_context.owner_population_limit.fill(0);
    std::fill_n(g_runtime.gameplay_lifecycle_context.owner_population_limit.begin(),
        kPlayerSlotCount, 0xb4u);
    g_runtime.gameplay_lifecycle_context.movement =
        &g_runtime.gameplay_movement_context;
    // The original installs the complete unit-runtime callback surface before
    // it materializes scenario/player units.  In particular, the two RNG calls
    // in InitializePlacedUnitFromMapSlot (0x004cf3e9/0x004cf431) must already
    // be live here; deferring this until simulation phase 1 gives every startup
    // unit the same direction/frame and leaves the gameplay RNG stream behind.
    configure_default_unit_lifecycle_callbacks(
        g_runtime.gameplay_lifecycle_context);
    g_runtime.gameplay_unit_spatial_indexes = UnitSpatialIndexSet{};
    InitializeUnitSpatialIndexSet(g_runtime.gameplay_unit_spatial_indexes);
    g_runtime.gameplay_unit_effect_runtime = UnitEffectRuntimeState{};
    g_runtime.gameplay_unit_effect_definitions_initialized = false;
    g_runtime.gameplay_action_damage_profiles = UnitActionDamageProfileTable{};
    g_runtime.gameplay_action_damage_profiles_initialized = false;
    g_runtime.gameplay_frame_random_state = GameplayFrameRandomState{};
    g_runtime.gameplay_terrain_layer = MinimapTerrainLayer{};
    reset_default_gameplay_terrain_frame_cache();
    ResetTerrainTilePulseState(g_runtime.gameplay_terrain_pulse_state);
    startup.players = &g_runtime.gameplay_player_slots;
    startup.lifecycle = &g_runtime.gameplay_lifecycle_context;
    startup.callbacks.reset_runtime_objects =
        default_gameplay_startup_reset_runtime_objects;
    startup.callbacks.reset_owner_ai = reset_default_owner_ai_runtime;
    startup.callbacks.on_unit_placed = default_gameplay_startup_unit_placed;
    startup.callbacks.initialize_local_camera =
        default_gameplay_startup_initialize_local_camera;
    startup.callbacks.after_session_snapshot =
        default_gameplay_startup_after_session_snapshot;
    startup.local_owner_id = 0;
    startup.session_mode = 0;
    startup.active_slot_count = kPlayerSlotCount;
    startup.owner_slots[0].slot_state =
        static_cast<u8>(PlayerSlotState::player_controlled);
    startup.owner_slots[0].map_slot = 0;
    startup.owner_slots[0].faction_id = 0;
    startup.owner_slots[0].tribe_id = 0;
    startup.owner_slots[0].start_x = 0x400;
    startup.owner_slots[0].start_y = 0x400;
    startup.owner_slots[0].starting_unit_type = kDefaultFactionStartingUnitTypes[0];
    startup.owner_slots[0].secondary_starting_unit_type =
        kDefaultFactionSecondaryStartingUnitTypes[0];
    for (std::size_t slot = 1; slot < startup.owner_slots.size(); ++slot) {
        startup.owner_slots[slot].slot_state = static_cast<u8>(PlayerSlotState::disabled);
        startup.owner_slots[slot].map_slot = static_cast<u32>(slot);
    }
}

void mirror_startup_slots_to_player_runtime(
    const GameplaySessionStartupState& startup, PlayerSlotRuntimeState& players) {
    players.active_slot_count = std::min<u32>(
        std::max<u32>(startup.active_slot_count, 1), kPlayerSlotCount);
    players.local_player_slot =
        NormalizePlayerOrNoLocalSlot(startup.local_owner_id);
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        const GameplayScenarioOwnerSlot& slot = startup.owner_slots[owner];
        players.slot_states[owner] = slot.slot_state;
        players.lobby_slot_states[owner] = slot.slot_state;
        // DAT_007253D4/D8 is indexed by the raw map-start slot.  The lobby's
        // owner-to-map permutation is applied only when the owner's actual
        // starting units are placed; AI target selection still reads this raw
        // coordinate table directly by owner index.
        const u32 map_slot = std::min<u32>(slot.map_slot, kPlayerSlotCount - 1);
        players.owner_start_x[map_slot] = slot.start_x;
        players.owner_start_y[map_slot] = slot.start_y;
    }
}

u32 default_primary_miles_music_policy_faction(
    const GameplaySessionStartupState& startup) {
    const u32 local_owner = std::min<u32>(startup.local_owner_id,
        kPlayerSlotCount - 1);
    return startup.owner_slots[local_owner].faction_id;
}

void sync_default_primary_miles_music_policy_faction() {
    SetPrimaryMilesMusicPolicyFactionIndex(
        default_primary_miles_music_policy_faction(
            g_runtime.gameplay_startup_state));
}

void sync_startup_owner_factions_to_lifecycle(
    const GameplaySessionStartupState& startup) {
    SetPrimaryMilesMusicPolicyFactionIndex(
        default_primary_miles_music_policy_faction(startup));

    if (startup.lifecycle == nullptr) {
        return;
    }

    for (u32 owner = 0; owner < kPlayerSlotCount &&
         owner < startup.lifecycle->owner_faction_ids.size(); ++owner) {
        startup.lifecycle->owner_faction_ids[owner] =
            startup.owner_slots[owner].faction_id;
    }
}

void set_default_primary_miles_music_policy_mode(u32 mode) {
    sync_default_primary_miles_music_policy_faction();
    const DWORD caller_thread = GetCurrentThreadId();
    const DWORD window_thread = g_runtime.main_window != nullptr ?
        GetWindowThreadProcessId(g_runtime.main_window, nullptr) : 0;
    const bool defer_title_music =
        mode == 2u && window_thread != 0 && caller_thread != window_thread;
    if (defer_title_music) {
        // Gameplay/session cleanup reaches title policy on the background
        // worker before the actual title HWND is presented.  Opening MCI
        // music there gives it worker-thread ownership; open_title_main_menu_
        // frontend then observes that device from the window thread and can
        // open a second copy.  Retire the worker-owned stream now and let the
        // title presentation edge below start exactly one stream on its UI
        // owner thread.
        SetPrimaryMilesMusicPolicyMode(1);
        return;
    }
    SetPrimaryMilesMusicPolicyMode(mode);
}

void reset_default_mode1_packet_state_from_player_slots() {
    ResetMode1GameplayPacketDispatch();
    ResetMode1ReliablePacketState();

    const PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;
    Mode1GameplayPacketDispatchState& packets = mode1_gameplay_packet_dispatch_state();
    // A fresh session starts with DAT_007334c0 == 1.  A loaded session may
    // already contain the toggled fog state, so keep the next cheat XOR edge
    // consistent with the visibility gate restored from its JW2 record.
    packets.local_toggle_state =
        !g_runtime.gameplay_startup_state.fog_reveal_disabled;
    u32 active_count = 0;

    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        Mode1GameplayPlayerPacketState& packet_player = packets.players[owner];
        // The reliable runtime is initialized from all eight raw
        // DAT_007251F4 state bytes.  active_slot_count only bounds lobby team
        // partitioning; it must not erase a restored/resynchronized tail slot.
        const bool disabled = players.slot_states[owner] ==
            static_cast<u8>(PlayerSlotState::disabled);
        packet_player.status = disabled ?
            static_cast<u8>(PlayerSlotState::disabled) :
            players.slot_states[owner];
        packet_player.inactive = disabled;
        packet_player.relation_mask = players.owner_relation_masks[owner];
        packet_player.relation_block_mask = players.owner_visibility_masks[owner];
        SetMode1ReliablePlayerStatus(owner, packet_player.status);
        if (packet_player.status != static_cast<u8>(PlayerSlotState::player_controlled) &&
            packet_player.status != static_cast<u8>(PlayerSlotState::disabled)) {
            ++active_count;
        }
    }

    SetMode1GameplayActivePlayerCount(active_count);
}

std::size_t default_session_runtime_pair_byte_count(
    const SessionRuntimeBufferPair& pair) {
    return static_cast<std::size_t>(pair.count) * pair.record_size;
}

bool session_archive_record_has_original_size(
    const char* archive_name, u32 record_index, std::size_t expected_size) {
    if (archive_name == nullptr || archive_name[0] == '\0' ||
        expected_size > 0xffffffffu) {
        return false;
    }

    u32 original_size = 0;
    return QueryTrcRecordSizes(
               archive_name, record_index, nullptr, &original_size, nullptr) &&
        original_size == static_cast<u32>(expected_size);
}

void write_default_session_buffer_u32(
    std::vector<u8>& bytes, std::size_t offset, u32 value) {
    if (offset > bytes.size() || bytes.size() - offset < sizeof(value)) {
        return;
    }
    bytes[offset + 0] = static_cast<u8>(value & 0xffu);
    bytes[offset + 1] = static_cast<u8>((value >> 8) & 0xffu);
    bytes[offset + 2] = static_cast<u8>((value >> 16) & 0xffu);
    bytes[offset + 3] = static_cast<u8>((value >> 24) & 0xffu);
}

bool write_default_session_pair_snapshot_record(SessionRuntimeBufferPair& pair,
    u32 index, const RuntimeDefinitionRecord& record) {
    if (index >= pair.count || record.bytes.size() < pair.record_size) {
        return false;
    }
    const std::size_t offset = static_cast<std::size_t>(index) * pair.record_size;
    if (offset > pair.snapshot.size() ||
        pair.record_size > pair.snapshot.size() - offset) {
        return false;
    }
    std::memcpy(pair.snapshot.data() + offset,
        record.bytes.data(), pair.record_size);
    return true;
}

bool copy_default_pristine_auxiliary_runtime_records(
    std::vector<RuntimeDefinitionRecord>& tail8_records,
    std::vector<RuntimeDefinitionRecord>& tail4_records) {
    tail8_records.clear();
    tail4_records.clear();

    std::vector<std::vector<u8>> jw212_definitions;
    std::vector<std::vector<u8>> jw211_definitions;
    if (!CopyPristineJw212RuntimeDefinitionBytes(jw212_definitions) ||
        !CopyPristineJw211RuntimeDefinitionBytes(jw211_definitions)) {
        return false;
    }

    tail8_records.resize(jw212_definitions.size());
    for (std::size_t index = 0; index < jw212_definitions.size(); ++index) {
        tail8_records[index].bytes = std::move(jw212_definitions[index]);
    }
    tail4_records.resize(jw211_definitions.size());
    for (std::size_t index = 0; index < jw211_definitions.size(); ++index) {
        tail4_records[index].bytes = std::move(jw211_definitions[index]);
    }
    return true;
}

void seed_default_session_runtime_base_auxiliary_snapshots(
    SessionRuntimeBufferPairs& buffers) {
    std::vector<RuntimeDefinitionRecord> tail8_records;
    std::vector<RuntimeDefinitionRecord> tail4_records;
    if (!copy_default_pristine_auxiliary_runtime_records(
            tail8_records, tail4_records)) {
        return;
    }

    SessionRuntimeBufferPair& tail8 = buffers.categories[3];
    const u32 tail8_count = std::min<u32>(tail8.count,
        static_cast<u32>(tail8_records.size()));
    for (u32 index = 0; index < tail8_count; ++index) {
        RuntimeDefinitionRecord compact{};
        if (ExportEightDwordSessionRuntimeTailRecord(
                compact, tail8_records[index])) {
            write_default_session_pair_snapshot_record(
                tail8, index, compact);
        }
    }

    SessionRuntimeBufferPair& tail4 = buffers.categories[4];
    const u32 tail4_count = std::min<u32>(tail4.count,
        static_cast<u32>(tail4_records.size()));
    for (u32 index = 0; index < tail4_count; ++index) {
        RuntimeDefinitionRecord compact{};
        if (ExportFourDwordSessionRuntimeTailRecord(
                compact, tail4_records[index])) {
            write_default_session_pair_snapshot_record(
                tail4, index, compact);
        }
    }
}

bool seed_default_active_session_auxiliary_definitions_from_catalog() {
    return copy_default_pristine_auxiliary_runtime_records(
        g_runtime.active_session_definitions.tail8_records,
        g_runtime.active_session_definitions.tail4_records);
}

bool publish_default_active_session_auxiliary_definitions() {
    const auto& tail8_records =
        g_runtime.active_session_definitions.tail8_records;
    const auto& tail4_records =
        g_runtime.active_session_definitions.tail4_records;
    if (tail8_records.size() != kJw212RuntimeCatalogCount ||
        tail4_records.size() != kJw211RuntimeCatalogCount) {
        return false;
    }

    std::vector<std::vector<u8>> jw212_definitions(tail8_records.size());
    for (std::size_t index = 0; index < tail8_records.size(); ++index) {
        if (tail8_records[index].bytes.size() !=
            kAuxiliaryRuntimeCatalogRecordBytes) {
            return false;
        }
        jw212_definitions[index] = tail8_records[index].bytes;
    }
    std::vector<std::vector<u8>> jw211_definitions(tail4_records.size());
    for (std::size_t index = 0; index < tail4_records.size(); ++index) {
        if (tail4_records[index].bytes.size() !=
            kAuxiliaryRuntimeCatalogRecordBytes) {
            return false;
        }
        jw211_definitions[index] = tail4_records[index].bytes;
    }

    if (!PublishJw21xSessionRuntimeTailDefinitionBytes(
            std::move(jw212_definitions), std::move(jw211_definitions))) {
        return false;
    }

    g_runtime.gameplay_action_damage_profiles = UnitActionDamageProfileTable{};
    g_runtime.gameplay_action_damage_profiles_initialized = false;
    g_runtime.gameplay_unit_effect_runtime.definitions.clear();
    g_runtime.gameplay_unit_effect_runtime.linked_health_restore_secondary_cost = 0;
    g_runtime.gameplay_unit_effect_runtime.linked_health_restore_amount = 0;
    g_runtime.gameplay_unit_effect_runtime.linked_health_restore_globals_loaded = false;
    g_runtime.gameplay_unit_effect_definitions_initialized = false;
    gameplay_production_action_state().definitions.clear();
    return true;
}

void seed_default_session_runtime_base_unit_snapshot(
    SessionRuntimeBufferPairs& buffers) {
    if (!UnitDefinitionResourceCatalogImageResourcesValid() &&
        !LoadUnitDefinitionResourceCatalog()) {
        return;
    }

    SessionRuntimeBufferPair& units = buffers.categories[1];
    const UnitDefinitionResourceCatalogState& catalog =
        unit_definition_resource_catalog_state();
    const u32 count = std::min<u32>(
        units.count, static_cast<u32>(catalog.records.size()));
    for (u32 type = 0; type < count; ++type) {
        const UnitDefinitionResourceRecord& catalog_record = catalog.records[type];
        if (!catalog_record.loaded || catalog_record.definition_bytes.empty()) {
            continue;
        }
        RuntimeDefinitionRecord live{};
        live.bytes = catalog_record.definition_bytes;
        RuntimeDefinitionRecord compact{};
        if (ExportUnitSessionRuntimeDefinitionRecord(type, compact, live)) {
            write_default_session_pair_snapshot_record(units, type, compact);
        }
    }
}

void seed_default_session_runtime_base_production_snapshot(
    SessionRuntimeBufferPairs& buffers) {
    constexpr std::size_t kHeaderBytes = 8;
    constexpr std::size_t kRecordBytes = 0x44c;
    std::vector<u8> payload;
    if (!LoadTrcRecordAlloc("JW2_10.TRC", 0, payload) ||
        payload.size() < kHeaderBytes) {
        return;
    }

    SessionRuntimeBufferPair& orders = buffers.categories[2];
    const u32 payload_count = read_runtime_catalog_u32(payload, 4, 0);
    const u32 count = std::min(orders.count, payload_count);
    SessionRuntimeExportState base_export{};
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (!load.records.empty() && load.record_loaded[0]) {
        const std::vector<u8>& header = load.records[0];
        for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
            for (u32 order = 0; order < kProductionOrderCount; ++order) {
                const std::size_t header_offset =
                    kGameplayHeaderProductionOrderStateOffset +
                    static_cast<std::size_t>(owner) *
                        kGameplayHeaderProductionOwnerStride +
                    static_cast<std::size_t>(order) *
                        kGameplayHeaderProductionOrderStride;
                const std::size_t variant_offset =
                    static_cast<std::size_t>(order) * sizeof(u32);
                if (header_offset >= header.size() ||
                    variant_offset >=
                        base_export.owner_order_variants[owner].size()) {
                    continue;
                }
                // FUN_00451d90 exports the live primary-record variant + 1
                // into the pristine US_UPG snapshot.  The primary JW2 record
                // is loaded before this snapshot is made.
                base_export.owner_order_variants[owner][variant_offset] =
                    header[header_offset];
            }
        }
    }
    for (u32 order = 0; order < count; ++order) {
        const std::size_t offset = kHeaderBytes +
            static_cast<std::size_t>(order) * kRecordBytes;
        if (offset > payload.size() || kRecordBytes > payload.size() - offset) {
            break;
        }
        RuntimeDefinitionRecord live{};
        live.bytes.assign(payload.begin() + offset,
            payload.begin() + offset + kRecordBytes);
        RuntimeDefinitionRecord compact{};
        if (ExportProductionOrderSessionRuntimeRecord(
                base_export, order, compact, live)) {
            write_default_session_pair_snapshot_record(orders, order, compact);
        }
    }
}

void initialize_default_session_runtime_staging_buffers(
    SessionRuntimeBufferPairs& buffers) {
    InitializeSessionRuntimeBufferPairs(buffers);
    for (SessionRuntimeBufferPair& pair : buffers.categories) {
        pair.snapshot.assign(default_session_runtime_pair_byte_count(pair), 0);
    }

    SessionRuntimeBufferPair& fixed =
        buffers.categories[kSessionRuntimeForcesRecordIndex];
    if (fixed.count == 0 || fixed.record_size < 0x34) {
        return;
    }

    write_default_session_buffer_u32(fixed.snapshot, 0x20, 0xff);
    for (u32 index = 0; index < fixed.count; ++index) {
        const std::size_t offset =
            static_cast<std::size_t>(index) * fixed.record_size;
        write_default_session_buffer_u32(fixed.snapshot, offset + 0x24, 1);
        write_default_session_buffer_u32(fixed.snapshot, offset + 0x28, 1);
        write_default_session_buffer_u32(fixed.snapshot, offset + 0x2c, 1);
        write_default_session_buffer_u32(fixed.snapshot, offset + 0x30, 1);
    }

    // DAT_01243270/74/78 are compact backups of the pristine live definition
    // tables.  Map US_* records are read into the separate active buffers at
    // DAT_01243284/88/8c and are only overlaid by the mode-5 branch.
    seed_default_session_runtime_base_unit_snapshot(buffers);
    seed_default_session_runtime_base_production_snapshot(buffers);
    seed_default_session_runtime_base_auxiliary_snapshots(buffers);
}

bool unpack_default_session_runtime_records(
    std::vector<RuntimeDefinitionRecord>& records,
    const SessionRuntimeBufferPair& pair, const std::vector<u8>& bytes) {
    const std::size_t expected_size = default_session_runtime_pair_byte_count(pair);
    records.clear();
    if (expected_size == 0) {
        return true;
    }
    if (pair.record_size == 0 || bytes.size() < expected_size) {
        return false;
    }

    records.resize(pair.count);
    for (u32 index = 0; index < pair.count; ++index) {
        const std::size_t offset =
            static_cast<std::size_t>(index) * pair.record_size;
        records[index].bytes.assign(bytes.begin() + offset,
            bytes.begin() + offset + pair.record_size);
    }
    return true;
}

bool unpack_default_session_runtime_definitions(
    const SessionRuntimeBufferPairs& buffers,
    SessionRuntimeDefinitionTableSet& definitions, bool snapshot) {
    const auto& bytes = [snapshot](const SessionRuntimeBufferPair& pair)
        -> const std::vector<u8>& {
        return snapshot ? pair.snapshot : pair.active;
    };
    return
        unpack_default_session_runtime_records(
            definitions.fixed44_records, buffers.categories[0],
            bytes(buffers.categories[0])) &&
        unpack_default_session_runtime_records(
            definitions.unit_records, buffers.categories[1],
            bytes(buffers.categories[1])) &&
        unpack_default_session_runtime_records(
            definitions.production_order_records, buffers.categories[2],
            bytes(buffers.categories[2])) &&
        unpack_default_session_runtime_records(
            definitions.tail8_records, buffers.categories[3],
            bytes(buffers.categories[3])) &&
        unpack_default_session_runtime_records(
            definitions.tail4_records, buffers.categories[4],
            bytes(buffers.categories[4]));
}

bool unpack_default_session_runtime_fixed_records(
    const SessionRuntimeBufferPairs& buffers, const std::vector<u8>& bytes,
    std::vector<RuntimeDefinitionRecord>& fixed44_records) {
    return unpack_default_session_runtime_records(
        fixed44_records, buffers.categories[kSessionRuntimeForcesRecordIndex], bytes);
}

bool default_session_runtime_user_override_records_available(
    const char* archive_name, const SessionRuntimeBufferPairs& buffers) {
    for (u32 index = 0; index < kSessionRuntimeUserRecordCount; ++index) {
        const SessionRuntimeBufferPair& pair = buffers.categories[index];
        if (!session_archive_record_has_original_size(archive_name,
                kSessionRuntimeUserRecordFirstIndex + index,
                default_session_runtime_pair_byte_count(pair))) {
            return false;
        }
    }
    return true;
}

bool stage_default_session_runtime_override_definitions() {
    g_runtime.gameplay_session_user_runtime_overrides_loaded = false;
    g_runtime.gameplay_session_forces_record_loaded = false;
    g_runtime.gameplay_session_runtime_definitions_staged = false;
    g_runtime.gameplay_session_forces_fixed_records.clear();
    g_runtime.base_session_definitions = SessionRuntimeDefinitionTableSet{};
    g_runtime.staged_session_definitions = SessionRuntimeDefinitionTableSet{};

    if (g_runtime.gameplay_session_archive_path.empty()) {
        return false;
    }

    SessionRuntimeBufferPairs& buffers =
        g_runtime.gameplay_session_runtime_buffers;
    if (!ResizeSessionRuntimeBufferPairs(buffers,
            kGameplaySessionRuntimeFixedRecordCount,
            kGameSessionUnitTypeCount,
            kGameplaySessionRuntimeProductionOrderRecordCount,
            kGameplaySessionRuntimeTail8RecordCount,
            kGameplaySessionRuntimeTail4RecordCount,
            initialize_default_session_runtime_staging_buffers)) {
        return false;
    }

    SessionRuntimeDefinitionTableSet base;
    if (!unpack_default_session_runtime_definitions(buffers, base, true)) {
        return false;
    }
    g_runtime.base_session_definitions = std::move(base);

    const char* archive_name = g_runtime.gameplay_session_archive_path.c_str();
    const bool user_records_available =
        default_session_runtime_user_override_records_available(
            archive_name, buffers);
    if (user_records_available &&
        LoadUserSessionRuntimeOverrideRecords(archive_name, buffers)) {
        SessionRuntimeDefinitionTableSet staged;
        if (unpack_default_session_runtime_definitions(
                buffers, staged, false)) {
            g_runtime.staged_session_definitions = std::move(staged);
            g_runtime.gameplay_session_user_runtime_overrides_loaded = true;
        }
    }

    const bool forces_record_available = session_archive_record_has_original_size(
        archive_name, kSessionRuntimeForcesArchiveRecordIndex,
        kSessionRuntimeForcesFixedRecordBytes);
    if (forces_record_available &&
        LoadForcesSessionRuntimeRecord(
            archive_name, buffers, g_runtime.gameplay_session_forces_fixed_records)) {
        g_runtime.gameplay_session_forces_record_loaded =
            unpack_default_session_runtime_fixed_records(
                buffers, g_runtime.gameplay_session_forces_fixed_records,
                g_runtime.active_session_definitions.fixed44_records);
        if (!g_runtime.gameplay_session_user_runtime_overrides_loaded &&
            g_runtime.gameplay_session_forces_record_loaded) {
            g_runtime.staged_session_definitions.fixed44_records =
                g_runtime.active_session_definitions.fixed44_records;
        }
    }

    g_runtime.gameplay_session_runtime_definitions_staged =
        g_runtime.gameplay_session_user_runtime_overrides_loaded ||
        g_runtime.gameplay_session_forces_record_loaded;
    return g_runtime.gameplay_session_runtime_definitions_staged;
}

bool seed_default_active_session_unit_definitions_from_catalog() {
    if (!UnitDefinitionResourceCatalogImageResourcesValid() &&
        !LoadUnitDefinitionResourceCatalog()) {
        return false;
    }

    const UnitDefinitionResourceCatalogState& catalog =
        unit_definition_resource_catalog_state();
    std::vector<RuntimeDefinitionRecord>& active_records =
        g_runtime.active_session_definitions.unit_records;
    active_records.clear();
    active_records.resize(catalog.records.size());
    for (std::size_t type = 0; type < catalog.records.size(); ++type) {
        const UnitDefinitionResourceRecord& source = catalog.records[type];
        if (source.loaded) {
            active_records[type].bytes = source.definition_bytes;
        }
    }
    g_runtime.unit_definition_cache_valid.fill(false);
    return true;
}

bool sync_default_production_catalog_from_runtime_records(
    const std::vector<RuntimeDefinitionRecord>& records,
    std::size_t record_body_offset) {
    constexpr std::size_t kRuntimeProductionRecordBytes = 0x44c;
    constexpr std::size_t kRuntimeProductionHeaderBytes = 8;
    const std::size_t count = std::min<std::size_t>(
        records.size(), kProductionOrderCount);
    if (count == 0) {
        return false;
    }

    std::vector<u8> payload(kRuntimeProductionHeaderBytes +
        count * kRuntimeProductionRecordBytes, 0);
    write_default_session_buffer_u32(payload, 0, 0x64);
    write_default_session_buffer_u32(payload, sizeof(u32),
        static_cast<u32>(count));
    for (std::size_t order = 0; order < count; ++order) {
        const std::vector<u8>& source = records[order].bytes;
        if (record_body_offset > source.size() ||
            source.size() - record_body_offset < kRuntimeProductionRecordBytes) {
            return false;
        }
        std::memcpy(payload.data() + kRuntimeProductionHeaderBytes +
                order * kRuntimeProductionRecordBytes,
            source.data() + record_body_offset,
            kRuntimeProductionRecordBytes);
    }

    ProductionOrderCatalog catalog;
    if (!LoadProductionOrderCatalogFromBytes(
            payload.data(), payload.size(), catalog)) {
        return false;
    }
    g_runtime.gameplay_production_catalog = std::move(catalog);
    return true;
}

bool restore_default_production_runtime_from_session_header() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (load.records.empty() || !load.record_loaded[0]) {
        return false;
    }

    const std::vector<u8>& header = load.records[0];
    if (header.size() < kGameplayHeaderProductionRuntimeEndOffset) {
        return false;
    }

    ProductionOrderRuntimeState& production =
        g_runtime.gameplay_production_runtime;
    for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
        for (u32 type = 0; type < kProductionOrderTypeCount; ++type) {
            const std::size_t count_offset =
                kGameplayHeaderOwnerUnitTypeCountOffset +
                static_cast<std::size_t>(owner) *
                    kGameplayHeaderOwnerUnitTypeCountStride +
                type;
            production.completed_type_counts[owner][type] =
                header[count_offset];
        }
        for (u32 order = 0; order < kProductionOrderCount; ++order) {
            const std::size_t offset =
                kGameplayHeaderProductionOrderStateOffset +
                static_cast<std::size_t>(owner) *
                    kGameplayHeaderProductionOwnerStride +
                static_cast<std::size_t>(order) *
                    kGameplayHeaderProductionOrderStride;
            production.variant_counts[owner][order] = header[offset];
            production.lock_flags[owner][order] = header[offset + 1];
            production.order_cell_opaque_bytes[owner][order][0] =
                header[offset + 2];
            production.order_cell_opaque_bytes[owner][order][1] =
                header[offset + 3];
        }
        production.order_2b_bonus_totals[owner] = static_cast<i32>(
            read_default_session_record_u32(header,
                kGameplayHeaderOrder2bBonusOffset +
                    static_cast<std::size_t>(owner) * sizeof(u32),
                0));
    }

    for (u32 effect = 0;
         effect < kProductionOrderCompletionEffectCount; ++effect) {
        for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
            for (u32 type = 0; type < kProductionOrderTypeCount; ++type) {
                const std::size_t offset =
                    kGameplayHeaderProductionEffectOffset +
                    static_cast<std::size_t>(effect) *
                        kGameplayHeaderProductionEffectStride +
                    static_cast<std::size_t>(owner) *
                        kGameplayHeaderProductionEffectOwnerStride +
                    static_cast<std::size_t>(type) * sizeof(u32);
                production.completion_effect_totals[effect][owner][type] =
                    static_cast<i32>(
                        read_default_session_record_u32(header, offset, 0));
            }
        }
    }
    production.order_2b_refresh_requests = 0;
    return true;
}

void sync_default_production_runtime_to_session_header(
    std::vector<u8>& header) {
    if (header.size() < kGameplayHeaderProductionRuntimeEndOffset) {
        return;
    }

    const ProductionOrderRuntimeState& production =
        g_runtime.gameplay_production_runtime;
    const UnitLifecycleContext* lifecycle =
        g_runtime.gameplay_startup_state.lifecycle;
    for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
        for (u32 type = 0; type < kProductionOrderTypeCount; ++type) {
            u32 count = production.completed_type_counts[owner][type];
            if (lifecycle != nullptr &&
                owner < lifecycle->owner_unit_type_counts.size() &&
                type < lifecycle->owner_unit_type_counts[owner].size()) {
                // DAT_00707430 is the live DWORD unit-lifecycle table inside
                // JW2.  The session header stores only each entry's low byte.
                count = lifecycle->owner_unit_type_counts[owner][type];
            }
            const std::size_t count_offset =
                kGameplayHeaderOwnerUnitTypeCountOffset +
                static_cast<std::size_t>(owner) *
                    kGameplayHeaderOwnerUnitTypeCountStride +
                type;
            header[count_offset] = static_cast<u8>(count);
        }
        for (u32 order = 0; order < kProductionOrderCount; ++order) {
            const std::size_t offset =
                kGameplayHeaderProductionOrderStateOffset +
                static_cast<std::size_t>(owner) *
                    kGameplayHeaderProductionOwnerStride +
                static_cast<std::size_t>(order) *
                    kGameplayHeaderProductionOrderStride;
            header[offset] = production.variant_counts[owner][order];
            header[offset + 1] = production.lock_flags[owner][order];
            header[offset + 2] =
                production.order_cell_opaque_bytes[owner][order][0];
            header[offset + 3] =
                production.order_cell_opaque_bytes[owner][order][1];
        }
        write_default_session_buffer_u32(header,
            kGameplayHeaderOrder2bBonusOffset +
                static_cast<std::size_t>(owner) * sizeof(u32),
            static_cast<u32>(production.order_2b_bonus_totals[owner]));
    }

    for (u32 effect = 0;
         effect < kProductionOrderCompletionEffectCount; ++effect) {
        for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
            for (u32 type = 0; type < kProductionOrderTypeCount; ++type) {
                const std::size_t offset =
                    kGameplayHeaderProductionEffectOffset +
                    static_cast<std::size_t>(effect) *
                        kGameplayHeaderProductionEffectStride +
                    static_cast<std::size_t>(owner) *
                        kGameplayHeaderProductionEffectOwnerStride +
                    static_cast<std::size_t>(type) * sizeof(u32);
                write_default_session_buffer_u32(header, offset,
                    static_cast<u32>(
                        production.completion_effect_totals[effect][owner][type]));
            }
        }
    }
}

void mirror_default_production_variants_to_session_import_state() {
    SessionRuntimeImportState& import = g_runtime.session_runtime_import_state;
    for (u32 owner = 0;
         owner < import.owner_order_variants.size() &&
         owner < g_runtime.gameplay_production_runtime.variant_counts.size();
         ++owner) {
        for (u32 order = 0;
             order < g_runtime.gameplay_production_runtime.variant_counts[owner].size();
             ++order) {
            const std::size_t offset =
                static_cast<std::size_t>(order) * sizeof(u32);
            if (offset >= import.owner_order_variants[owner].size()) {
                break;
            }
            import.owner_order_variants[owner][offset] =
                g_runtime.gameplay_production_runtime.variant_counts[owner][order];
        }
    }
}

void default_session_apply_production_completion(u32 owner, u32 order_id) {
    const ProductionOrderDefinition* definition =
        default_production_order_definition(order_id);
    if (definition == nullptr || owner >= kProductionOrderOwnerCount ||
        order_id >= kProductionOrderCount) {
        return;
    }

    const ProductionOrderCompletionResult result = CompleteProductionOrder(
        g_runtime.gameplay_production_runtime, *definition, owner);
    const std::size_t variant_offset =
        static_cast<std::size_t>(order_id) * sizeof(u32);
    if (variant_offset < g_runtime.session_runtime_import_state
            .owner_order_variants[owner].size()) {
        g_runtime.session_runtime_import_state.owner_order_variants[owner]
            [variant_offset] =
            g_runtime.gameplay_production_runtime.variant_counts[owner][order_id];
    }
    if (result.order_2b_refresh_requested) {
        UnitMovementContext* movement = default_gameplay_movement_context();
        const bool active_units_materialized = movement != nullptr &&
            std::any_of(movement->active_units.begin(), movement->active_units.end(),
                [](const UnitMovementUnit* unit) {
                    return unit != nullptr && unit->active;
                });
        if (active_units_materialized) {
            refresh_default_order_2b_active_unit_progress();
        } else {
            // The original has already materialized record 7 when FUN_00450f90
            // replays saved US_UPG variants.  Our session flow decodes record 7
            // later, so retain the exact owner-bonus state after each 0x2b
            // completion and replay those list walks once those units exist.
            g_runtime.gameplay_pending_order_2b_bonus_snapshots.push_back(
                g_runtime.gameplay_production_runtime.order_2b_bonus_totals);
        }
    }
}

void prepare_default_base_session_runtime_definition_import() {
    g_runtime.gameplay_pending_order_2b_bonus_snapshots.clear();
    // Clear the prior session first.  Callers then hydrate the newly loaded
    // primary JW2 record before the compact tables perform their monotonic
    // catch-up, matching 0x4d1ccc -> 0x450f90.
    ResetProductionOrderRuntimeState(g_runtime.gameplay_production_runtime);
    seed_default_active_session_unit_definitions_from_catalog();
    seed_default_active_session_auxiliary_definitions_from_catalog();
    if (!sync_default_production_catalog_from_runtime_records(
            g_runtime.base_session_definitions.production_order_records, 4)) {
        ProductionOrderCatalog base_catalog;
        if (LoadProductionOrderCatalogFromJw210Trc(base_catalog)) {
            g_runtime.gameplay_production_catalog = std::move(base_catalog);
        }
    }
    mirror_default_production_variants_to_session_import_state();
    g_runtime.session_runtime_import_state.apply_production_completion =
        default_session_apply_production_completion;
}

void prepare_default_non_empty_session_runtime_definition_import() {
    sync_default_production_catalog_from_runtime_records(
        g_runtime.staged_session_definitions.production_order_records, 4);
    g_runtime.session_runtime_import_state.apply_production_completion =
        default_session_apply_production_completion;
}

void default_gameplay_session_prepare_non_empty_runtime_definition_import(
    GameplaySessionRuntimeResetState&) {
    prepare_default_non_empty_session_runtime_definition_import();
}

void sync_default_active_session_unit_names() {
    ClearGameplayUnitNameOverrides();
    for (std::size_t type = 0; type < kUnitDefinitionResourceCount; ++type) {
        if (type >= g_runtime.active_session_definitions.unit_records.size()) {
            continue;
        }
        SetGameplayUnitNameOverride(
            static_cast<u32>(type), ReadSessionUnitDefinitionNameField(
                g_runtime.active_session_definitions.unit_records[type]));
    }
}

void refresh_default_units_after_runtime_definition_import() {
    g_runtime.unit_definition_cache_valid.fill(false);
    UnitMovementContext* movement = default_gameplay_movement_context();
    if (movement == nullptr) {
        return;
    }
    for (UnitMovementUnit* unit : movement->active_units) {
        if (unit != nullptr) {
            refresh_default_unit_definition_runtime_fields(*unit);
        }
    }
    for (UnitMovementUnit* unit : movement->lifecycle_units) {
        if (unit != nullptr) {
            refresh_default_unit_definition_runtime_fields(*unit);
        }
    }
}

void finalize_default_session_runtime_definition_import() {
    if (!publish_default_active_session_auxiliary_definitions()) {
        append_startup_log(
            "session runtime auxiliary tail publication failed");
    }
    sync_default_production_catalog_from_runtime_records(
        g_runtime.active_session_definitions.production_order_records, 0);
    sync_default_active_session_unit_names();
    refresh_default_units_after_runtime_definition_import();
    sync_default_gameplay_tooltip_unit_definitions();
}

u32 read_default_session_record_u32(
    const std::vector<u8>& record, std::size_t offset, u32 fallback) {
    if (offset > record.size() || record.size() - offset < sizeof(u32)) {
        return fallback;
    }
    return static_cast<u32>(record[offset]) |
        (static_cast<u32>(record[offset + 1]) << 8) |
        (static_cast<u32>(record[offset + 2]) << 16) |
        (static_cast<u32>(record[offset + 3]) << 24);
}

u32 default_gameplay_session_map_dimension_tiles(std::size_t offset) {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionMapRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionMapRecordIndex]) {
        return kGameplayScenarioDefaultMapTiles;
    }

    const u32 value = read_default_session_record_u32(
        load.records[kGameplaySessionMapRecordIndex], offset, 0);
    if (value == 0) {
        return kGameplayScenarioDefaultMapTiles;
    }
    return std::min<u32>(value, kGameplayScenarioMapLayerStrideTiles);
}

u32 default_gameplay_session_map_width_tiles() {
    return default_gameplay_session_map_dimension_tiles(
        kSessionMapRecordWidthTilesOffset);
}

u32 default_gameplay_session_map_height_tiles() {
    return default_gameplay_session_map_dimension_tiles(
        kSessionMapRecordHeightTilesOffset);
}

std::string read_default_session_record_string(
    const std::vector<u8>& record, std::size_t offset, std::size_t length) {
    if (offset > record.size() || record.size() - offset < length) {
        return {};
    }

    const auto begin = record.begin() + offset;
    const auto end = begin + length;
    const auto nul = std::find(begin, end, 0);
    return std::string(
        reinterpret_cast<const char*>(&*begin),
        static_cast<std::size_t>(nul - begin));
}

const std::vector<u8>* default_session_scenario_record() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionScenarioRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionScenarioRecordIndex]) {
        return nullptr;
    }

    const std::vector<u8>& record = load.records[kGameplaySessionScenarioRecordIndex];
    if (record.size() < kGameplaySessionScenarioRecordBytes) {
        return nullptr;
    }
    return &record;
}

const std::vector<u8>* default_session_map_record() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionMapRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionMapRecordIndex]) {
        return nullptr;
    }

    const std::vector<u8>& record = load.records[kGameplaySessionMapRecordIndex];
    if (record.size() < kSessionMapRecordAmbientEffectGateOffset + sizeof(u32)) {
        return nullptr;
    }
    return &record;
}

const std::vector<u8>* default_session_player_record() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionPlayerRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionPlayerRecordIndex]) {
        // GameplaySessionStartupState::snapshot is a compact diagnostic view,
        // not the original P_PLAYE layout.  Treating it as record 3 reads
        // owner bytes as local/faction/resource dwords.
        return nullptr;
    }

    const std::vector<u8>& record = load.records[kGameplaySessionPlayerRecordIndex];
    if (record.size() < kGameplaySessionPlayerRecordBytes) {
        return nullptr;
    }
    return &record;
}

const std::vector<u8>* default_gameplay_result_metric_record() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplayResultMetricRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplayResultMetricRecordIndex]) {
        return nullptr;
    }

    const std::vector<u8>& record = load.records[kGameplayResultMetricRecordIndex];
    if (record.size() < kGameplayResultMetricRecordBytes) {
        return nullptr;
    }
    return &record;
}

bool default_session_player_slot_state_valid(u32 state) {
    return state == static_cast<u32>(PlayerSlotState::active) ||
        state == static_cast<u32>(PlayerSlotState::player_controlled) ||
        state == static_cast<u32>(PlayerSlotState::observer) ||
        state == static_cast<u32>(PlayerSlotState::rotation_reserve) ||
        state == static_cast<u32>(PlayerSlotState::disabled);
}

bool import_default_session_map_record_startup_state() {
    const std::vector<u8>* record = default_session_map_record();
    if (record == nullptr) {
        return false;
    }

    GameplaySessionStartupState& startup = g_runtime.gameplay_startup_state;
    startup.ambient_map_effect_spawn_gate = read_default_session_record_u32(
        *record, kSessionMapRecordAmbientEffectGateOffset,
        startup.ambient_map_effect_spawn_gate);
    return true;
}

bool import_default_session_scenario_record_startup_state() {
    const std::vector<u8>* record = default_session_scenario_record();
    if (record == nullptr) {
        return false;
    }

    GameplaySessionStartupState& startup = g_runtime.gameplay_startup_state;
    startup.session_mode = read_default_session_record_u32(
        *record, kSessionScenarioRecordModeOffset, startup.session_mode);

    const u32 active_slot_count = read_default_session_record_u32(
        *record, kSessionScenarioRecordActiveSlotCountOffset,
        startup.active_slot_count);
    if (active_slot_count != 0) {
        startup.active_slot_count = std::min<u32>(
            active_slot_count, kPlayerSlotCount);
    }
    startup.scenario_victory_condition_mask = read_default_session_record_u32(
        *record, kSessionScenarioRecordVictoryConditionMaskOffset, 0);
    startup.scenario_defeat_condition_mask = read_default_session_record_u32(
        *record, kSessionScenarioRecordDefeatConditionMaskOffset, 0);
    return true;
}

bool import_default_session_player_record_startup_state() {
    const std::vector<u8>* record = default_session_player_record();
    if (record == nullptr) {
        return false;
    }

    GameplaySessionStartupState& startup = g_runtime.gameplay_startup_state;
    PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;

    const u32 local_owner = read_default_session_record_u32(
        *record, kSessionPlayerRecordLocalOwnerOffset, startup.local_owner_id);
    if (IsPlayerOrNoLocalSlot(local_owner)) {
        startup.local_owner_id = local_owner;
        players.local_player_slot = local_owner;
    }

    const u32 active_slot_count = std::min<u32>(
        std::max<u32>(startup.active_slot_count, 1), kPlayerSlotCount);
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        GameplayScenarioOwnerSlot& slot = startup.owner_slots[owner];
        std::string display_name = read_default_session_record_string(
            *record,
            kSessionPlayerRecordNameBaseOffset +
                static_cast<std::size_t>(owner) *
                    kSessionPlayerRecordNameStride,
            kSessionPlayerRecordNameStride);
        if (!display_name.empty()) {
            startup.owner_display_names[owner] = std::move(display_name);
        }

        if (owner >= active_slot_count) {
            slot.slot_state = static_cast<u8>(PlayerSlotState::disabled);
        }
        else {
            const u32 slot_state = read_default_session_record_u32(
                *record,
                kSessionPlayerRecordSlotStateBaseOffset + owner * sizeof(u32),
                slot.slot_state);
            if (default_session_player_slot_state_valid(slot_state)) {
                slot.slot_state = static_cast<u8>(slot_state);
            }
        }

        const u32 faction = read_default_session_record_u32(
            *record, kSessionPlayerRecordFactionBaseOffset + owner * sizeof(u32),
            slot.faction_id);
        slot.faction_id = faction <= 3 ? faction : 0;
        slot.tribe_id = slot.faction_id;
        slot.map_slot = owner;
        startup.owner_faction_ids[owner] = slot.faction_id;
        startup.owner_tribe_ids[owner] = slot.tribe_id;

        const std::size_t start_offset =
            kSessionPlayerRecordStartCoordinateBaseOffset +
            static_cast<std::size_t>(owner) *
                kSessionPlayerRecordStartCoordinateStride;
        const u32 start_x = read_default_session_record_u32(
            *record, start_offset, 0xffffffffu);
        const u32 start_y = read_default_session_record_u32(
            *record, start_offset + sizeof(u32), 0xffffffffu);
        if (start_x != 0xffffffffu && start_y != 0xffffffffu) {
            slot.start_x = static_cast<i32>(start_x);
            slot.start_y = static_cast<i32>(start_y);
            players.owner_start_x[owner] = slot.start_x;
            players.owner_start_y[owner] = slot.start_y;
        }
    }

    for (u32 owner = 0; owner < kPlayerOwnerResourceSlots; ++owner) {
        const std::size_t resource_offset = static_cast<std::size_t>(owner) *
            sizeof(u32);
        players.owner_primary_resources[owner] =
            read_default_session_record_u32(
                *record,
                kSessionPlayerRecordOwnerResourcePrimaryBaseOffset +
                    resource_offset,
                players.owner_primary_resources[owner]);
        players.owner_secondary_resources[owner] =
            read_default_session_record_u32(
                *record,
                kSessionPlayerRecordOwnerResourceSecondaryBaseOffset +
                    resource_offset,
                players.owner_secondary_resources[owner]);
        players.owner_aux_resources[owner] =
            read_default_session_record_u32(
                *record,
                kSessionPlayerRecordOwnerResourceAuxBaseOffset + resource_offset,
                players.owner_aux_resources[owner]);
    }

    return true;
}

bool import_default_session_starting_unit_types() {
    const u32 active_slot_count = std::min<u32>(
        std::max<u32>(g_runtime.gameplay_startup_state.active_slot_count, 1),
        kPlayerSlotCount);
    for (u32 owner = 0; owner < active_slot_count; ++owner) {
        GameplayScenarioOwnerSlot& slot =
            g_runtime.gameplay_startup_state.owner_slots[owner];
        const u32 faction = std::min<u32>(slot.faction_id,
            static_cast<u32>(kDefaultFactionStartingUnitTypes.size() - 1));
        slot.starting_unit_type = kDefaultFactionStartingUnitTypes[faction];
        slot.secondary_starting_unit_type =
            kDefaultFactionSecondaryStartingUnitTypes[faction];
    }
    return true;
}

bool link_lobby_startup_session_seed_present(const LinkLobbyState& lobby) {
    return std::any_of(lobby.session_seed_payload.begin(),
        lobby.session_seed_payload.end(), [](u8 value) { return value != 0; });
}

u32 read_link_lobby_startup_seed_u32(
    const LinkLobbyState& lobby, std::size_t offset) {
    return read_packet_u32_raw(lobby.session_seed_payload.data(),
        lobby.session_seed_payload.size(), offset);
}

u32 link_lobby_startup_active_slot_count(const LinkLobbyState& lobby) {
    if (link_lobby_startup_session_seed_present(lobby)) {
        const u32 max_players = read_link_lobby_startup_seed_u32(
            lobby, kLinkLobbyStartupSessionSeedMaxPlayersOffset);
        if (max_players != 0) {
            return std::min<u32>(max_players, kPlayerSlotCount);
        }
    }

    u32 active_count = 0;
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        const u32 state = lobby.start_states[owner];
        if (default_session_player_slot_state_valid(state) &&
            state != static_cast<u32>(PlayerSlotState::disabled)) {
            active_count = owner + 1;
        }
    }
    return std::max<u32>(active_count, 1);
}

std::string link_lobby_startup_player_name(
    const LinkLobbyState& lobby, u32 owner) {
    if (owner >= kPlayerSlotCount) {
        return {};
    }

    std::string name = fixed_packet_string_raw(
        reinterpret_cast<const u8*>(lobby.players[owner].name.data()),
        lobby.players[owner].name.size(), 0, lobby.players[owner].name.size());
    if (!name.empty()) {
        return name;
    }

    return fixed_packet_string_raw(lobby.player_payloads[owner].data(),
        lobby.player_payloads[owner].size(), kLinkLobbyStartupPlayerNamePayloadOffset,
        kLinkLobbyStartupPlayerNamePayloadBytes);
}

u8 normalized_link_lobby_startup_slot_state(u8 value) {
    return default_session_player_slot_state_valid(value) ? value :
        static_cast<u8>(PlayerSlotState::disabled);
}

bool link_lobby_startup_parameters_available() {
    return g_runtime.link_lobby_start_parameters_pending &&
        GameplayLaunchUsesLinkLobby(g_runtime.gameplay_launch_source) &&
        !link_lobby_state().start_parameter_payload.empty();
}

bool hydrate_replay_link_lobby_startup_parameters() {
    const ReplayRecordingState& replay = replay_recording_state();
    const P2PGameSessionStartState& p2p = g_runtime.p2p_session_start_state;
    if (!replay.playback_mode || !p2p.start_parameter_payload_present) {
        return false;
    }

    LinkLobbyState& lobby = link_lobby_state();
    if (!LoadLinkLobbyStartParametersPayload(lobby,
            p2p.start_parameter_payload.data(),
            p2p.start_parameter_payload.size())) {
        return false;
    }

    lobby.local_player_index = static_cast<int>(std::min<u32>(
        p2p.copied_runtime_local_player, kPlayerSlotCount - 1));
    g_runtime.link_lobby_start_parameters_pending = true;
    return true;
}

void populate_p2p_session_start_input_from_link_lobby(
    P2PGameSessionStartInput& input) {
    if (!link_lobby_startup_parameters_available()) {
        return;
    }

    const LinkLobbyState& lobby = link_lobby_state();
    input.start_parameter_payload.fill(0);
    const std::size_t start_parameter_bytes = std::min<std::size_t>(
        input.start_parameter_payload.size(), lobby.start_parameter_payload.size());
    std::memcpy(input.start_parameter_payload.data(),
        lobby.start_parameter_payload.data(), start_parameter_bytes);
    input.start_parameter_payload_present = start_parameter_bytes != 0;
    input.copied_runtime_local_player = static_cast<u32>(
        std::clamp(lobby.local_player_index, 0, static_cast<int>(kPlayerSlotCount - 1)));
    input.network_player_count = 0;

    for (u32 owner = 0; owner < kPlayerSlotCount &&
         input.network_player_count < input.players.size(); ++owner) {
        const u8 slot_state = normalized_link_lobby_startup_slot_state(
            lobby.start_states[owner]);
        // DAT_007251F4 state 1 is a Computer owner.  The original P2P owner
        // lookup is built from the DirectPlay participant array, so Computer
        // slots never consume an entry in that array.  Keeping them here made
        // a local-host-versus-Computer match wait for a nonexistent network
        // peer during the surrender/exit vote.
        if (slot_state == static_cast<u8>(PlayerSlotState::player_controlled) ||
            slot_state == static_cast<u8>(PlayerSlotState::disabled)) {
            continue;
        }

        P2PGameSessionPlayerSetup& player =
            input.players[input.network_player_count++];
        std::string name = link_lobby_startup_player_name(lobby, owner);
        if (name.empty()) {
            char fallback[32]{};
            std::snprintf(fallback, sizeof(fallback), "Player %u", owner);
            name = fallback;
        }
        copy_result_text(player.name, name.c_str());
        player.owner_slot = static_cast<u8>(owner);
    }

    if (input.network_player_count == 0) {
        input.network_player_count = 1;
        input.players[0].owner_slot = static_cast<u8>(input.copied_runtime_local_player);
    }
}

void sync_default_owner_resource_runtime_slots(
    u32 owner, u32 primary, u32 secondary, UnitLifecycleContext* lifecycle) {
    if (owner < g_runtime.gameplay_player_slots.owner_primary_resources.size() &&
        owner < g_runtime.gameplay_player_slots.owner_secondary_resources.size()) {
        g_runtime.gameplay_player_slots.owner_primary_resources[owner] = primary;
        g_runtime.gameplay_player_slots.owner_secondary_resources[owner] = secondary;
    }
    if (owner < g_runtime.gameplay_production_runtime.owner_primary_resources.size() &&
        owner <
            g_runtime.gameplay_production_runtime.owner_secondary_resources.size()) {
        g_runtime.gameplay_production_runtime.owner_primary_resources[owner] = primary;
        g_runtime.gameplay_production_runtime.owner_secondary_resources[owner] =
            secondary;
    }
    if (owner < g_runtime.gameplay_unit_commands.owner_resources.size() &&
        owner < g_runtime.gameplay_unit_commands.owner_secondary_resources.size()) {
        g_runtime.gameplay_unit_commands.owner_resources[owner] = primary;
        g_runtime.gameplay_unit_commands.owner_secondary_resources[owner] = secondary;
    }
    if (lifecycle != nullptr &&
        owner < lifecycle->owner_primary_resources.size() &&
        owner < lifecycle->owner_secondary_resources.size()) {
        lifecycle->owner_primary_resources[owner] = primary;
        lifecycle->owner_secondary_resources[owner] = secondary;
    }
}

void sync_default_owner_resource_runtime_slots(u32 owner, u32 primary, u32 secondary) {
    sync_default_owner_resource_runtime_slots(owner, primary, secondary,
        g_runtime.gameplay_startup_state.lifecycle);
}

void sync_link_lobby_startup_resources_to_lifecycle(
    const PlayerSlotRuntimeState& players, UnitLifecycleContext* lifecycle) {
    for (u32 owner = 0; owner < kPlayerOwnerResourceSlots &&
         owner < players.owner_primary_resources.size() &&
         owner < players.owner_secondary_resources.size(); ++owner) {
        sync_default_owner_resource_runtime_slots(owner,
            players.owner_primary_resources[owner],
            players.owner_secondary_resources[owner], lifecycle);
    }
}

bool apply_pending_link_lobby_start_parameters_to_gameplay_startup() {
    if (!g_runtime.link_lobby_start_parameters_pending) {
        return false;
    }
    g_runtime.link_lobby_start_parameters_pending = false;

    LinkLobbyState& lobby = link_lobby_state();
    if (lobby.start_parameter_payload.empty()) {
        return false;
    }

    GameplaySessionStartupState& startup = g_runtime.gameplay_startup_state;
    PlayerSlotRuntimeState& players = g_runtime.gameplay_player_slots;

    std::array<i32, kPlayerSlotCount> imported_start_x{};
    std::array<i32, kPlayerSlotCount> imported_start_y{};
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        imported_start_x[owner] = startup.owner_slots[owner].start_x;
        imported_start_y[owner] = startup.owner_slots[owner].start_y;
    }

    startup.local_owner_id = static_cast<u32>(
        std::clamp(lobby.local_player_index, 0, static_cast<int>(kPlayerSlotCount - 1)));
    startup.session_mode = static_cast<u32>(std::max(0, lobby.game_type));
    startup.active_slot_count = link_lobby_startup_active_slot_count(lobby);
    startup.frame_interval_index = static_cast<u32>(
        std::clamp(lobby.map_selection_index, 0,
            static_cast<int>(kGameplayFrameIntervalsMs.size() - 1)));
    startup.fog_reveal_disabled =
        read_packet_u32_raw(lobby.start_parameter_payload.data(),
            lobby.start_parameter_payload.size(),
            kLinkLobbyStartupFogRevealDisabledOffset) != 0;
    ExportSetupU32(kSetupVisibilityGateOffset,
        startup.fog_reveal_disabled ? 0u : 1u);

    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        GameplayScenarioOwnerSlot& slot = startup.owner_slots[owner];
        u8 slot_state = normalized_link_lobby_startup_slot_state(
            lobby.start_states[owner]);
        if (owner >= startup.active_slot_count) {
            slot_state = static_cast<u8>(PlayerSlotState::disabled);
        }

        const u32 map_slot = std::min<u32>(lobby.randomized_slots[owner],
            kPlayerSlotCount - 1);
        const u32 faction = lobby.tribe_choices[owner] <= 3 ?
            lobby.tribe_choices[owner] : 0;
        slot.slot_state = slot_state;
        slot.map_slot = map_slot;
        slot.faction_id = faction;
        slot.tribe_id = faction;
        slot.start_x = imported_start_x[map_slot];
        slot.start_y = imported_start_y[map_slot];
        slot.starting_unit_type = kDefaultFactionStartingUnitTypes[faction];
        slot.secondary_starting_unit_type =
            kDefaultFactionSecondaryStartingUnitTypes[faction];

        startup.owner_faction_ids[owner] = faction;
        startup.owner_tribe_ids[owner] = faction;
        players.slot_states[owner] = slot.slot_state;
        players.lobby_slot_states[owner] = slot.slot_state;
        players.owner_start_x[map_slot] = slot.start_x;
        players.owner_start_y[map_slot] = slot.start_y;

        std::string display_name = link_lobby_startup_player_name(lobby, owner);
        if (!display_name.empty()) {
            startup.owner_display_names[owner] = std::move(display_name);
        }
    }

    const int start_resource = lobby.start_resource_index;
    if (start_resource > 0 &&
        start_resource < static_cast<int>(kLinkLobbyStartResourcePrimaryValues.size())) {
        const u32 value =
            kLinkLobbyStartResourcePrimaryValues[static_cast<std::size_t>(start_resource)];
        players.owner_primary_resources.fill(value);
    }

    mirror_startup_slots_to_player_runtime(startup, players);
    sync_startup_owner_factions_to_lifecycle(startup);
    sync_link_lobby_startup_resources_to_lifecycle(players, startup.lifecycle);
    // The original startup packet is consumed by the same synchronous call.
    // The P2P session state already owns its replay/flight-recorder copy.
    lobby.start_parameter_payload.clear();
    return true;
}

bool import_default_session_owner_unit_availability() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionOwnerUnitAvailabilityRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionOwnerUnitAvailabilityRecordIndex]) {
        return false;
    }

    const std::vector<u8>& record =
        load.records[kGameplaySessionOwnerUnitAvailabilityRecordIndex];
    if (record.size() < kGameplaySessionOwnerUnitAvailabilityRecordBytes) {
        return false;
    }

    for (u32 owner = 0; owner < kGameSessionOwnerCount; ++owner) {
        const std::size_t offset =
            static_cast<std::size_t>(owner) * kGameSessionUnitTypeCount;
        std::copy(record.begin() + offset,
            record.begin() + offset + kGameSessionUnitTypeCount,
            g_runtime.session_runtime_import_state
                .owner_unit_availability[owner].begin());
    }
    return true;
}

bool decode_default_owner_ai_unit_pointer(u32 raw_pointer, u32& unit_id) {
    unit_id = 0;
    if (raw_pointer == 0) {
        return true;
    }

    const u32 first_unit_pointer =
        kGameplayOriginalUnitPoolBaseAddress + kGameplayScenarioObjectStride;
    const u32 pool_end_pointer =
        kGameplayOriginalUnitPoolBaseAddress + kGameplayOriginalUnitPoolByteCount;
    if (raw_pointer < first_unit_pointer || raw_pointer >= pool_end_pointer) {
        return false;
    }

    const u32 offset = raw_pointer - kGameplayOriginalUnitPoolBaseAddress;
    if (offset % kGameplayScenarioObjectStride != 0) {
        return false;
    }
    unit_id = offset;
    return true;
}

bool encode_default_owner_ai_unit_pointer(u32 runtime_reference,
    const UnitMovementUnit* unit, u32& raw_pointer) {
    raw_pointer = 0;
    const auto encode_runtime_slot = [&](u32 runtime_slot) {
        if (runtime_slot == 0 ||
            runtime_slot >= kGameplayScenarioObjectMaxSlots) {
            return false;
        }
        raw_pointer = kGameplayOriginalUnitPoolBaseAddress +
            runtime_slot * kGameplayScenarioObjectStride;
        return true;
    };

    if (unit != nullptr &&
        encode_runtime_slot(unit->runtime_slot_index)) {
        return true;
    }
    if (runtime_reference == 0) {
        return true;
    }

    // Imported active units can temporarily keep a legacy slot-index id
    // (for example 54) rather than slot*0x1d0.  Resolve the live unit first so
    // export always uses its fixed-pool slot and never rejects that valid id.
    const UnitMovementUnit* resolved =
        find_default_movement_unit_by_id(runtime_reference);
    if (resolved != nullptr &&
        encode_runtime_slot(resolved->runtime_slot_index)) {
        return true;
    }

    // Unresolved stale route entries retain the canonical pool-byte id decoded
    // from the raw pointer.  A small unresolved value is accepted as the
    // legacy slot-index form only after the canonical-offset test.
    if (runtime_reference >= kGameplayScenarioObjectStride &&
        runtime_reference < kGameplayOriginalUnitPoolByteCount &&
        runtime_reference % kGameplayScenarioObjectStride == 0) {
        raw_pointer =
            kGameplayOriginalUnitPoolBaseAddress + runtime_reference;
        return true;
    }
    return encode_runtime_slot(runtime_reference);
}

i32 read_default_owner_ai_snapshot_i32(
    const std::vector<u8>& snapshot, std::size_t offset) {
    const u32 raw = read_default_session_record_u32(snapshot, offset, 0);
    return WrappedU32ToI32(raw);
}

bool import_default_owner_transport_state_from_snapshot(
    const std::vector<u8>& snapshot) {
    if (snapshot.size() != kOwnerAiSnapshotByteCount) {
        return false;
    }

    std::array<OwnerTransportQueueState, kOwnerAiOwnerCount> queues{};
    std::array<OwnerTransportRouteState, kOwnerAiOwnerCount> routes{};
    std::array<bool, kOwnerAiOwnerCount> invalid_route_counts{};
    std::array<OwnerStrategicTargetState, kOwnerAiOwnerCount>
        strategic_targets{};
    std::array<u32, kOwnerAiOwnerCount> strategic_preferred_target_ids{};
    std::array<OwnerProductionPlacementAnchorSet, kOwnerAiOwnerCount>
        placement_anchors{};
    std::array<UnitMovementPoint, kOwnerAiOwnerCount>
        production_path_targets{};

    const auto read_point = [&](std::size_t offset) {
        return UnitMovementPoint{
            read_default_owner_ai_snapshot_i32(snapshot, offset),
            read_default_owner_ai_snapshot_i32(
                snapshot, offset + sizeof(i32))};
    };

    for (u32 owner = 0; owner < kOwnerAiOwnerCount; ++owner) {
        OwnerStrategicTargetState& strategic = strategic_targets[owner];
        const OwnerAiSlotRuntime& ai_owner =
            g_runtime.gameplay_owner_ai_state.owners[owner];
        strategic.target_owner_id = ai_owner.primary_target_owner >= 0 ?
            static_cast<u32>(ai_owner.primary_target_owner) :
            kInvalidOwnerTransportQueueSlot;
        strategic.strategic_point = {
            ai_owner.primary_target_point.x, ai_owner.primary_target_point.y};
        strategic.has_strategic_point = strategic.strategic_point.x != -1;
        strategic.blocked_owner_mask = 0;
        const u32 preferred_raw_pointer = read_default_session_record_u32(
            snapshot,
            kOwnerAiStrategicPreferredUnitPointerOffset + owner * sizeof(u32),
            0);
        if (!decode_default_owner_ai_unit_pointer(preferred_raw_pointer,
                strategic_preferred_target_ids[owner])) {
            return false;
        }
        strategic.preferred_target = nullptr;
        strategic.has_preferred_target = false;
        strategic.preferred_target_point = {
            read_default_owner_ai_snapshot_i32(snapshot,
                kOwnerAiStrategicPreferredPointOffset + owner * 2 * sizeof(i32)),
            read_default_owner_ai_snapshot_i32(snapshot,
                kOwnerAiStrategicPreferredPointOffset +
                    owner * 2 * sizeof(i32) + sizeof(i32))};

        OwnerProductionPlacementAnchorSet& anchors = placement_anchors[owner];
        anchors.base_tile = read_point(kOwnerAiPlacementBasePointOffset +
            owner * kOwnerAiSerializedPointStride);
        for (u32 index = 0; index < anchors.placement_class_1_points.size();
             ++index) {
            anchors.placement_class_1_points[index] = read_point(
                kOwnerAiPlacementClass1PointsOffset +
                owner * anchors.placement_class_1_points.size() *
                    kOwnerAiSerializedPointStride +
                index * kOwnerAiSerializedPointStride);
        }
        for (u32 index = 0; index < anchors.placement_class_2_points.size();
             ++index) {
            anchors.placement_class_2_points[index] = read_point(
                kOwnerAiPlacementClass2PointsOffset +
                owner * anchors.placement_class_2_points.size() *
                    kOwnerAiSerializedPointStride +
                index * kOwnerAiSerializedPointStride);
        }
        for (u32 index = 0; index < anchors.placement_class_3_points.size();
             ++index) {
            anchors.placement_class_3_points[index] = read_point(
                kOwnerAiPlacementClass3PointsOffset +
                owner * anchors.placement_class_3_points.size() *
                    kOwnerAiSerializedPointStride +
                index * kOwnerAiSerializedPointStride);
        }
        for (u32 index = 0; index < anchors.placement_class_4_points.size();
             ++index) {
            anchors.placement_class_4_points[index] = read_point(
                kOwnerAiPlacementClass4PointsOffset +
                owner * anchors.placement_class_4_points.size() *
                    kOwnerAiSerializedPointStride +
                index * kOwnerAiSerializedPointStride);
        }
        anchors.placement_class_5_point = read_point(
            kOwnerAiPlacementClass5PointOffset +
            owner * kOwnerAiSerializedPointStride);
        production_path_targets[owner] = read_point(
            kOwnerAiProductionPathTargetPointOffset +
            owner * kOwnerAiSerializedPointStride);

        OwnerTransportRouteState& route = routes[owner];
        const u32 raw_route_count = read_default_session_record_u32(snapshot,
            kOwnerAiRouteCountOffset + owner * sizeof(u32), 0);
        if (raw_route_count == kOwnerAiRouteCountInvalid) {
            route.route_count = 0;
            invalid_route_counts[owner] = true;
        }
        else if (raw_route_count <= route.targets.size()) {
            route.route_count = raw_route_count;
        }
        else {
            return false;
        }

        route.load_percent = read_default_session_record_u32(snapshot,
            kOwnerAiRouteLoadPercentOffset + owner * sizeof(u32), 0);
        for (u32 index = 0; index < route.targets.size(); ++index) {
            OwnerTransportRouteTarget& target = route.targets[index];
            const std::size_t value_offset =
                static_cast<std::size_t>(owner) * kOwnerAiRouteOwnerStride +
                static_cast<std::size_t>(index) * sizeof(u32);
            const std::size_t point_offset =
                static_cast<std::size_t>(owner) *
                    kOwnerAiRoutePointOwnerStride +
                static_cast<std::size_t>(index) * kOwnerAiRoutePointStride;
            const u32 raw_pointer = read_default_session_record_u32(snapshot,
                kOwnerAiRouteUnitPointerOffset + value_offset, 0);
            if (!decode_default_owner_ai_unit_pointer(
                    raw_pointer, target.target.match_value)) {
                return false;
            }
            target.unit = nullptr;
            target.target.target_x = read_default_owner_ai_snapshot_i32(snapshot,
                kOwnerAiRouteNearestTileOffset + point_offset);
            target.target.target_y = read_default_owner_ai_snapshot_i32(snapshot,
                kOwnerAiRouteNearestTileOffset + point_offset + sizeof(i32));
            target.target.route_index = index;
            target.desired_count_base = read_default_session_record_u32(snapshot,
                kOwnerAiRouteDesiredCountOffset + value_offset, 0);
            target.secondary_count_base = read_default_session_record_u32(snapshot,
                kOwnerAiRouteSecondaryCountOffset + value_offset, 0);
            target.priority = read_default_session_record_u32(snapshot,
                kOwnerAiRoutePriorityOffset + value_offset, 0);
            target.flags = read_default_session_record_u32(snapshot,
                kOwnerAiRouteFlagsOffset + value_offset, 0);
        }

        OwnerTransportQueueState& queue = queues[owner];
        for (u32 index = 0; index < queue.slots.size(); ++index) {
            OwnerTransportQueueSlot& slot = queue.slots[index];
            const std::size_t slot_offset = kOwnerAiTransportQueueOffset +
                static_cast<std::size_t>(owner) *
                    kOwnerAiTransportQueueOwnerStride +
                static_cast<std::size_t>(index) *
                    kOwnerAiTransportQueueSlotStride;
            slot.count = read_default_session_record_u32(
                snapshot, slot_offset + 0x00, 0);
            slot.state = read_default_session_record_u32(
                snapshot, slot_offset + 0x04, 0);
            slot.completed_count = read_default_session_record_u32(
                snapshot, slot_offset + 0x08, 0);
            slot.phase_ticks = read_default_session_record_u32(
                snapshot, slot_offset + 0x0c, 0);
            slot.aux_value = read_default_session_record_u32(
                snapshot, slot_offset + 0x10, 0);
            const u32 raw_pointer = read_default_session_record_u32(
                snapshot, slot_offset + 0x14, 0);
            if (!decode_default_owner_ai_unit_pointer(
                    raw_pointer, slot.match_value)) {
                return false;
            }
            slot.target_x = read_default_owner_ai_snapshot_i32(
                snapshot, slot_offset + 0x18);
            slot.target_y = read_default_owner_ai_snapshot_i32(
                snapshot, slot_offset + 0x1c);
            slot.route_index = read_default_session_record_u32(
                snapshot, slot_offset + 0x20, 0);
            slot.linked_group = read_default_session_record_u32(
                snapshot, slot_offset + 0x24, 0);
        }
    }

    g_runtime.gameplay_owner_transport_queues = std::move(queues);
    g_runtime.gameplay_owner_transport_routes = std::move(routes);
    g_runtime.gameplay_owner_transport_route_count_invalid =
        invalid_route_counts;
    g_runtime.gameplay_owner_strategic_targets =
        std::move(strategic_targets);
    g_runtime.gameplay_owner_strategic_preferred_target_ids =
        strategic_preferred_target_ids;
    g_runtime.gameplay_owner_production_placement_anchors =
        std::move(placement_anchors);
    g_runtime.gameplay_owner_production_placement_anchor_valid.fill(true);
    g_runtime.gameplay_owner_production_placement_target_points =
        production_path_targets;
    return true;
}

bool overlay_default_owner_transport_state_on_snapshot(
    std::vector<u8>& snapshot) {
    if (snapshot.size() != kOwnerAiSnapshotByteCount) {
        return false;
    }

    const auto write_point = [&](std::size_t offset,
                                 const UnitMovementPoint& point) {
        write_default_session_buffer_u32(
            snapshot, offset, static_cast<u32>(point.x));
        write_default_session_buffer_u32(snapshot, offset + sizeof(i32),
            static_cast<u32>(point.y));
    };

    for (u32 owner = 0; owner < kOwnerAiOwnerCount; ++owner) {
        const OwnerStrategicTargetState& strategic =
            g_runtime.gameplay_owner_strategic_targets[owner];
        const u32 preferred_reference = strategic.preferred_target != nullptr ?
            strategic.preferred_target->id :
            g_runtime.gameplay_owner_strategic_preferred_target_ids[owner];
        u32 preferred_raw_pointer = 0;
        if (!encode_default_owner_ai_unit_pointer(preferred_reference,
                strategic.preferred_target, preferred_raw_pointer)) {
            return false;
        }
        write_default_session_buffer_u32(snapshot,
            kOwnerAiStrategicPreferredUnitPointerOffset + owner * sizeof(u32),
            preferred_raw_pointer);
        write_default_session_buffer_u32(snapshot,
            kOwnerAiStrategicPreferredPointOffset + owner * 2 * sizeof(i32),
            static_cast<u32>(strategic.preferred_target_point.x));
        write_default_session_buffer_u32(snapshot,
            kOwnerAiStrategicPreferredPointOffset +
                owner * 2 * sizeof(i32) + sizeof(i32),
            static_cast<u32>(strategic.preferred_target_point.y));

        const OwnerProductionPlacementAnchorSet& anchors =
            g_runtime.gameplay_owner_production_placement_anchors[owner];
        write_point(kOwnerAiPlacementBasePointOffset +
                owner * kOwnerAiSerializedPointStride,
            anchors.base_tile);
        for (u32 index = 0; index < anchors.placement_class_1_points.size();
             ++index) {
            write_point(kOwnerAiPlacementClass1PointsOffset +
                    owner * anchors.placement_class_1_points.size() *
                        kOwnerAiSerializedPointStride +
                    index * kOwnerAiSerializedPointStride,
                anchors.placement_class_1_points[index]);
        }
        for (u32 index = 0; index < anchors.placement_class_2_points.size();
             ++index) {
            write_point(kOwnerAiPlacementClass2PointsOffset +
                    owner * anchors.placement_class_2_points.size() *
                        kOwnerAiSerializedPointStride +
                    index * kOwnerAiSerializedPointStride,
                anchors.placement_class_2_points[index]);
        }
        for (u32 index = 0; index < anchors.placement_class_3_points.size();
             ++index) {
            write_point(kOwnerAiPlacementClass3PointsOffset +
                    owner * anchors.placement_class_3_points.size() *
                        kOwnerAiSerializedPointStride +
                    index * kOwnerAiSerializedPointStride,
                anchors.placement_class_3_points[index]);
        }
        for (u32 index = 0; index < anchors.placement_class_4_points.size();
             ++index) {
            write_point(kOwnerAiPlacementClass4PointsOffset +
                    owner * anchors.placement_class_4_points.size() *
                        kOwnerAiSerializedPointStride +
                    index * kOwnerAiSerializedPointStride,
                anchors.placement_class_4_points[index]);
        }
        write_point(kOwnerAiPlacementClass5PointOffset +
                owner * kOwnerAiSerializedPointStride,
            anchors.placement_class_5_point);
        write_point(kOwnerAiProductionPathTargetPointOffset +
                owner * kOwnerAiSerializedPointStride,
            g_runtime.gameplay_owner_production_placement_target_points[owner]);

        const OwnerTransportRouteState& route =
            g_runtime.gameplay_owner_transport_routes[owner];
        if (route.route_count > route.targets.size()) {
            return false;
        }
        const bool invalid_count =
            g_runtime.gameplay_owner_transport_route_count_invalid[owner] &&
            route.route_count == 0;
        write_default_session_buffer_u32(snapshot,
            kOwnerAiRouteCountOffset + owner * sizeof(u32),
            invalid_count ? kOwnerAiRouteCountInvalid : route.route_count);
        // route_load_percent is a single original dword shared by the owner-AI
        // script and the typed route view; the script field is authoritative.
        write_default_session_buffer_u32(snapshot,
            kOwnerAiRouteLoadPercentOffset + owner * sizeof(u32),
            g_runtime.gameplay_owner_ai_state.owners[owner].route_load_percent);

        for (u32 index = 0; index < route.targets.size(); ++index) {
            const OwnerTransportRouteTarget& target = route.targets[index];
            const std::size_t value_offset =
                static_cast<std::size_t>(owner) * kOwnerAiRouteOwnerStride +
                static_cast<std::size_t>(index) * sizeof(u32);
            const std::size_t point_offset =
                static_cast<std::size_t>(owner) *
                    kOwnerAiRoutePointOwnerStride +
                static_cast<std::size_t>(index) * kOwnerAiRoutePointStride;
            u32 raw_pointer = 0;
            if (!encode_default_owner_ai_unit_pointer(
                    target.target.match_value, target.unit, raw_pointer)) {
                return false;
            }
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteUnitPointerOffset + value_offset, raw_pointer);
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteNearestTileOffset + point_offset,
                static_cast<u32>(target.target.target_x));
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteNearestTileOffset + point_offset + sizeof(i32),
                static_cast<u32>(target.target.target_y));
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteDesiredCountOffset + value_offset,
                target.desired_count_base);
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteSecondaryCountOffset + value_offset,
                target.secondary_count_base);
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRoutePriorityOffset + value_offset, target.priority);
            write_default_session_buffer_u32(snapshot,
                kOwnerAiRouteFlagsOffset + value_offset, target.flags);
        }

        const OwnerTransportQueueState& queue =
            g_runtime.gameplay_owner_transport_queues[owner];
        for (u32 index = 0; index < queue.slots.size(); ++index) {
            const OwnerTransportQueueSlot& slot = queue.slots[index];
            const std::size_t slot_offset = kOwnerAiTransportQueueOffset +
                static_cast<std::size_t>(owner) *
                    kOwnerAiTransportQueueOwnerStride +
                static_cast<std::size_t>(index) *
                    kOwnerAiTransportQueueSlotStride;
            u32 raw_pointer = 0;
            if (!encode_default_owner_ai_unit_pointer(
                    slot.match_value, nullptr, raw_pointer)) {
                return false;
            }
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x00, slot.count);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x04, slot.state);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x08, slot.completed_count);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x0c, slot.phase_ticks);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x10, slot.aux_value);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x14, raw_pointer);
            write_default_session_buffer_u32(snapshot,
                slot_offset + 0x18, static_cast<u32>(slot.target_x));
            write_default_session_buffer_u32(snapshot,
                slot_offset + 0x1c, static_cast<u32>(slot.target_y));
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x20, slot.route_index);
            write_default_session_buffer_u32(
                snapshot, slot_offset + 0x24, slot.linked_group);
            // +0x28..+0x54 have no evidenced consumers.  They deliberately
            // remain whatever ExportOwnerAiSnapshot copied from raw backing.
        }
    }
    return true;
}

void bind_default_owner_transport_route_units() {
    u32 unresolved_live_target_count = 0;
    for (u32 owner = 0; owner < kOwnerAiOwnerCount; ++owner) {
        OwnerStrategicTargetState& strategic =
            g_runtime.gameplay_owner_strategic_targets[owner];
        strategic.preferred_target = find_default_movement_unit_by_id(
            g_runtime.gameplay_owner_strategic_preferred_target_ids[owner]);
        strategic.has_preferred_target =
            strategic.preferred_target != nullptr;
        if (strategic.preferred_target != nullptr) {
            g_runtime.gameplay_owner_strategic_preferred_target_ids[owner] =
                strategic.preferred_target->id;
        }

        OwnerTransportRouteState& route =
            g_runtime.gameplay_owner_transport_routes[owner];
        for (u32 index = 0; index < route.targets.size(); ++index) {
            OwnerTransportRouteTarget& target = route.targets[index];
            target.unit = find_default_movement_unit_by_id(
                target.target.match_value);
            if (target.unit != nullptr) {
                // Runtime queue comparisons use the reconstruction object's
                // actual id, which can still be a legacy slot index.
                target.target.match_value = target.unit->id;
            }
            if (index < route.route_count && target.target.match_value != 0 &&
                target.unit == nullptr) {
                ++unresolved_live_target_count;
            }
        }
        for (OwnerTransportQueueSlot& slot :
             g_runtime.gameplay_owner_transport_queues[owner].slots) {
            if (slot.match_value == 0) {
                continue;
            }
            UnitMovementUnit* unit =
                find_default_movement_unit_by_id(slot.match_value);
            if (unit != nullptr) {
                slot.match_value = unit->id;
            }
        }
    }
    if (unresolved_live_target_count != 0) {
        append_startup_log(
            "owner AI route bind unresolved_live_targets=%lu",
            static_cast<unsigned long>(unresolved_live_target_count));
    }
}

bool import_default_owner_ai_snapshot_from_session_records() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplaySessionOwnerAiRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplaySessionOwnerAiRecordIndex]) {
        return false;
    }

    const std::vector<u8>& record = load.records[kGameplaySessionOwnerAiRecordIndex];
    OwnerAiRuntimeState previous_owner_ai = g_runtime.gameplay_owner_ai_state;
    if (!ImportOwnerAiSnapshot(g_runtime.gameplay_owner_ai_state, record.data(),
            static_cast<u32>(record.size())) ||
        !import_default_owner_transport_state_from_snapshot(record)) {
        // Keep a failed/invalid load atomic.  The transport decoder commits
        // only after validating its complete temporary image, whereas the
        // typed owner-AI decoder necessarily hydrates in place first.
        g_runtime.gameplay_owner_ai_state = std::move(previous_owner_ai);
        return false;
    }
    // A loaded record replaces the process BSS image.  A later fresh session
    // must apply FUN_0043cc00's partial owner reset to this image rather than
    // incorrectly bootstrapping a second all-zero record.
    g_default_owner_ai_bss_bootstrapped = true;
    for (u32 owner = 0; owner < kOwnerAiOwnerCount; ++owner) {
        g_runtime.gameplay_owner_ai_reserved_primary_cost[owner] =
            g_runtime.gameplay_owner_ai_state.owners[owner]
                .route_refresh_counter;
    }
    return true;
}

bool export_default_owner_ai_snapshot_to_payload(std::vector<u8>& payload) {
    for (u32 owner = 0; owner < kOwnerAiOwnerCount; ++owner) {
        OwnerAiSlotRuntime& ai_owner =
            g_runtime.gameplay_owner_ai_state.owners[owner];
        ai_owner.route_refresh_counter =
            g_runtime.gameplay_owner_ai_reserved_primary_cost[owner];
        g_runtime.gameplay_owner_transport_routes[owner].load_percent =
            ai_owner.route_load_percent;
    }
    payload.assign(kOwnerAiSnapshotByteCount, 0);
    if (!ExportOwnerAiSnapshot(g_runtime.gameplay_owner_ai_state, payload.data(),
            static_cast<u32>(payload.size())) ||
        !overlay_default_owner_transport_state_on_snapshot(payload)) {
        payload.clear();
        return false;
    }
    return true;
}

bool append_default_session_runtime_export_records(
    std::vector<TrcWriteRecord>& records) {
    // HandleGameplaySessionBundleExport -> FUN_004506a0 writes the active
    // compact buffers verbatim.  Their first DWORD is an archive/editor-owned
    // marker; rebuilding rows from the live definitions would zero or invent
    // those markers and change the next mode-5 import.
    const SessionRuntimeBufferPairs& buffers =
        g_runtime.gameplay_session_runtime_buffers;

    if (!AppendUserSessionRuntimeOverrideWriteRecords(records, buffers)) {
        return false;
    }

    TrcWriteRecord res2{};
    res2.name = "RES2";
    res2.method = 0;
    res2.payload.assign(4, 0);
    records.push_back(res2);

    return AppendForcesSessionRuntimeWriteRecord(records, buffers);
}

void apply_default_session_fixed44_player_slot_masks() {
    // FUN_00450ba0 applies the active/user fixed table only in mode 5.
    // Normal P2P sessions have already imported the base table and must not
    // interpret the map's US_FORCE records as live player-team masks.
    if (g_runtime.gameplay_startup_state.session_mode != 5 ||
        g_runtime.active_session_definitions.fixed44_records.empty()) {
        return;
    }

    RebuildSessionPlayerSlotMasksFromFixed44Records(
        g_runtime.gameplay_player_slots,
        g_runtime.active_session_definitions.fixed44_records);
    // The synthesized default FORCES record uses a shared 0xff mask.  Direct
    // link modes do not use that record as a team declaration: each active
    // player is an opponent unless a dedicated team mode grouped the slots.
    // Re-apply the session-mode relation builder so the fixed44 import cannot
    // turn every P2P player and Computer slot into allies.
    const u32 session_mode = g_runtime.gameplay_startup_state.session_mode;
    if (session_mode == 1 || session_mode == 5 || session_mode == 6) {
        BuildGameplaySessionPlayerRelationMasks(
            g_runtime.gameplay_player_slots, session_mode);
    }
    SelectNearestHostilePlayerSlots(g_runtime.gameplay_player_slots);
}

void default_gameplay_session_reset_effect_runtime(
    GameplaySessionRuntimeResetState&) {
    g_runtime.map_effect_context = MapEffectContext{};
    g_runtime.gameplay_unit_effect_runtime = UnitEffectRuntimeState{};
    g_runtime.gameplay_unit_effect_definitions_initialized = false;
    g_runtime.gameplay_action_damage_profiles = UnitActionDamageProfileTable{};
    g_runtime.gameplay_action_damage_profiles_initialized = false;
}

void default_gameplay_session_reset_ui_runtime_flags(
    GameplaySessionRuntimeResetState&) {
    GameplayModalUiState& modal = gameplay_modal_ui_state();
    modal.quit_to_frontend_requested = false;
    modal.surrender_requested = false;
    modal.worker_exit_requested = false;
    modal.end_session_requested = false;
    // HandleGameplaySessionBundleImport copies P_SCENA to 0x00722868 in the
    // original, so DAT_00722870 is already populated before this reset runs.
    // Read that fixed-record field directly; campaign archives do not need an
    // opcode-0x0d trigger merely to establish their initial objective text.
    std::string objective;
    if (const std::vector<u8>* record = default_session_scenario_record();
        record != nullptr) {
        objective = ReadGameplayScenarioObjectiveText(*record);
    }
    modal.scenario_message_text = objective;
    modal.fallback_scenario_message_text = std::move(objective);

    UiOverlayState& overlay = ui_overlay_state();
    StopGameplayHudPulse(overlay);
    ResetGameplaySelectionState(overlay);
    ResetCameraBookmarks(overlay);
    ResetGameplayHudAlertMarkers(g_runtime.gameplay_hud_alert_markers);
}

bool load_default_game_session_avatar_runtime() {
    constexpr u32 kOriginalAvatarRecord = 9;
    ResetGameSessionAvatarRuntime(g_runtime.gameplay_avatar_runtime);
    g_runtime.gameplay_avatar_runtime_loaded = false;

    if (g_runtime.gameplay_session_archive_path.empty()) {
        return false;
    }

    const char* archive_name = g_runtime.gameplay_session_archive_path.c_str();
    if (LoadGameSessionAvatarRuntimeRecord(
            g_runtime.gameplay_avatar_runtime, archive_name, kOriginalAvatarRecord)) {
        g_runtime.gameplay_avatar_runtime_loaded = true;
        return true;
    }

    u32 record_count = 0;
    if (!QueryTrcArchiveRecordCount(archive_name, &record_count)) {
        return false;
    }

    for (u32 record = 0; record < record_count; ++record) {
        TrcDirectoryEntry entry{};
        if (!QueryTrcRecordSizes(archive_name, record, nullptr, nullptr, &entry) ||
            entry.name != "AVATAR" ||
            entry.original_size > kGameSessionAvatarRuntimeBytes) {
            continue;
        }
        if (!LoadGameSessionAvatarRuntimeRecord(
                g_runtime.gameplay_avatar_runtime, archive_name, record)) {
            return false;
        }
        g_runtime.gameplay_avatar_runtime_loaded = true;
        return true;
    }

    return false;
}

bool load_default_gameplay_script_triggers_from_session_archive(
    GameplayScriptTriggerState& script) {
    constexpr u32 kOriginalTriggerRecord = 5;
    g_runtime.gameplay_script_triggers_loaded = false;
    g_runtime.gameplay_script_trigger_record_index = 0xffffffffu;

    if (g_runtime.gameplay_session_archive_path.empty()) {
        return false;
    }

    TrcDirectoryEntry original_entry{};
    if (QueryTrcRecordSizes(g_runtime.gameplay_session_archive_path.c_str(),
            kOriginalTriggerRecord, nullptr, nullptr, &original_entry) &&
        original_entry.original_size >= kGameplayScriptTriggerRuntimeOffset &&
        LoadGameplayScriptTriggersRecord(script,
            g_runtime.gameplay_session_archive_path.c_str(), kOriginalTriggerRecord)) {
        g_runtime.gameplay_script_triggers_loaded = true;
        g_runtime.gameplay_script_trigger_record_index = kOriginalTriggerRecord;
        return true;
    }

    u32 record_count = 0;
    if (!QueryTrcArchiveRecordCount(g_runtime.gameplay_session_archive_path.c_str(),
            &record_count)) {
        return false;
    }

    for (u32 record = 0; record < record_count; ++record) {
        TrcDirectoryEntry entry{};
        if (!QueryTrcRecordSizes(g_runtime.gameplay_session_archive_path.c_str(),
                record, nullptr, nullptr, &entry)) {
            continue;
        }
        if (entry.name != "TRIGGERS" ||
            entry.original_size < kGameplayScriptTriggerRuntimeOffset) {
            continue;
        }

        if (!LoadGameplayScriptTriggersRecord(script,
                g_runtime.gameplay_session_archive_path.c_str(), record)) {
            return false;
        }
        g_runtime.gameplay_script_triggers_loaded = true;
        g_runtime.gameplay_script_trigger_record_index = record;
        return true;
    }

    return false;
}

u32 read_default_scenario_object_u32(const std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset) {
    const std::size_t offset = object_base + field_offset;
    if (offset > bytes.size() || bytes.size() - offset < sizeof(u32)) {
        return 0;
    }
    return static_cast<u32>(bytes[offset]) |
        (static_cast<u32>(bytes[offset + 1]) << 8) |
        (static_cast<u32>(bytes[offset + 2]) << 16) |
        (static_cast<u32>(bytes[offset + 3]) << 24);
}

i32 read_default_scenario_object_i32(const std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset) {
    return static_cast<i32>(
        read_default_scenario_object_u32(bytes, object_base, field_offset));
}

float read_default_scenario_object_float(const std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset) {
    static_assert(sizeof(float) == sizeof(u32),
        "scenario float fields must be 32-bit IEEE-754 values");
    const u32 bits =
        read_default_scenario_object_u32(bytes, object_base, field_offset);
    float value = 0.0f;
    std::memcpy(&value, &bits, sizeof(value));
    return value;
}

void write_default_scenario_object_u32(std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset, u32 value) {
    const std::size_t offset = object_base + field_offset;
    if (offset > bytes.size() || bytes.size() - offset < sizeof(u32)) {
        return;
    }
    bytes[offset + 0] = static_cast<u8>(value & 0xffu);
    bytes[offset + 1] = static_cast<u8>((value >> 8) & 0xffu);
    bytes[offset + 2] = static_cast<u8>((value >> 16) & 0xffu);
    bytes[offset + 3] = static_cast<u8>((value >> 24) & 0xffu);
}

void write_default_scenario_object_i32(std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset, i32 value) {
    write_default_scenario_object_u32(
        bytes, object_base, field_offset, static_cast<u32>(value));
}

void write_default_scenario_object_float(std::vector<u8>& bytes,
    std::size_t object_base, std::size_t field_offset, float value) {
    static_assert(sizeof(float) == sizeof(u32),
        "scenario float fields must be 32-bit IEEE-754 values");
    u32 bits = 0;
    std::memcpy(&bits, &value, sizeof(bits));
    write_default_scenario_object_u32(
        bytes, object_base, field_offset, bits);
}

bool scenario_object_uses_equipment_slot_zero(u32 type_id) {
    return type_id < 0x60;
}

bool scenario_object_uses_cell_render_scratch(u32 type_id) {
    return !scenario_object_uses_equipment_slot_zero(type_id);
}

u32 default_scenario_object_reference_to_unit_id(u32 value) {
    if (value != 0 && value % kGameplayScenarioObjectStride == 0) {
        const u32 object_index = value / kGameplayScenarioObjectStride;
        if (object_index < kGameplayScenarioObjectMaxSlots) {
            return object_index;
        }
    }
    return value;
}

u32 default_scenario_object_id_to_reference(u32 value) {
    if (value != 0 && value < kGameplayScenarioObjectMaxSlots) {
        return value * kGameplayScenarioObjectStride;
    }
    return value;
}

u32 default_unit_id_to_scenario_object_reference(const UnitMovementUnit* unit,
    u32 value) {
    if (unit != nullptr && unit->target != nullptr && value == unit->target->id) {
        const u32 slot = unit->target->runtime_slot_index;
        if (slot != 0 && slot != kInvalidUnitRuntimeSlotIndex &&
            slot < kGameplayScenarioObjectMaxSlots) {
            return slot * kGameplayScenarioObjectStride;
        }
    }
    return value;
}

bool default_command_payload_uses_unit_reference(u32 state, u32 command_value) {
    if (command_value == 0 || (command_value & 0x80000000u) != 0) {
        return false;
    }
    if ((state & 0x20000000u) != 0) {
        return true;
    }

    switch (state & kUnitCommandStateMask) {
    case 0x02:
    case 0x03:
    case 0x04:
    case 0x05:
    case 0x0a:
    case 0x0b:
    case 0x23:
        return true;
    default:
        return false;
    }
}

bool default_unit_command_value_uses_target_reference(u32 state) {
    switch (state & kUnitCommandStateMask) {
    case 0x03:
    case 0x04:
    case 0x14:
    case 0x16:
    case 0x17:
    case 0x1c:
    case 0x1d:
    case 0x1e:
    case 0x1f:
    case 0x20:
    case 0x21:
    case 0x22:
    case 0x24:
    case 0x2b:
    case 0x2c:
    case 0x37:
    case 0x38:
    case 0x39:
    case 0x3a:
    case 0x3c:
    case 0x3d:
    case 0x3e:
    case 0x3f:
    case 0x41:
    case 0x45:
    case 0x48:
    case 0x49:
    case 0x5b:
    case 0x5f:
    case 0x60:
    case 0x61:
        return true;
    default:
        return false;
    }
}

bool default_active_command_payload_uses_target_reference(u32 state) {
    switch (state & kUnitCommandStateMask) {
    case 0x0c:
    case 0x0d:
    case 0x0e:
    case 0x10:
    case 0x11:
    case 0x12:
    case 0x64:
    case 0x65:
    case 0x66:
    case 0x69:
    case 0x6a:
    case 0x73:
    case 0x74:
    case 0x75:
    case 0x7d:
    case 0x7e:
    case 0x7f:
    case 0x87:
    case 0x88:
    case 0x89:
        return true;
    default:
        return false;
    }
}

u32 default_unit_target_reference(const UnitMovementUnit& unit) {
    // Raw +0x68 is a state-dependent union.  Construction nodes and the
    // target-bearing runtime states store a fixed-pool offset directly.
    if (unit.action_mode_gate == 1 ||
        default_unit_command_value_uses_target_reference(unit.command_state)) {
        return unit.command_value;
    }

    // Several active command tuples retain the target offset at raw +0xd8
    // while typed runtime code uses +0x68 for an amount, type or counter.
    if (default_active_command_payload_uses_target_reference(
            unit.active_command_payload.state)) {
        return static_cast<u32>(unit.active_command_payload.x);
    }
    return 0;
}

u32 default_command_payload_reference_to_unit_id(u32 state, u32 value) {
    // Record 7 is a byte-for-byte image of the original fixed unit pool.
    // Target-bearing queued commands already store the target's 0x1d0-byte
    // pool offset, which is also the reconstructed runtime unit id.  Dividing
    // it into a scenario slot here made a restored command point at a unit id
    // that can never be resolved.
    (void)state;
    return value;
}

u32 default_unit_id_to_command_payload_reference(u32 state, u32 value) {
    // The command tuple shares the raw fixed-pool namespace used at runtime;
    // no slot-index conversion occurs when the original saves this record.
    (void)state;
    return value;
}

u32 compose_default_scenario_object_command_state(
    const GameplayScriptTriggerObjectState& object) {
    return (object.command_state_raw & 0xff000000u) |
        (object.script_state & 0x00ffffffu);
}

GameplayScriptCommandPayload read_default_scenario_object_command_payload(
    const std::vector<u8>& bytes, std::size_t object_base,
    std::size_t state_offset, std::size_t value_offset, std::size_t x_offset,
    std::size_t y_offset) {
    GameplayScriptCommandPayload payload{};
    payload.state =
        read_default_scenario_object_u32(bytes, object_base, state_offset);
    payload.command_value = static_cast<i32>(
        default_command_payload_reference_to_unit_id(payload.state,
            read_default_scenario_object_u32(bytes, object_base, value_offset)));
    payload.x_payload =
        read_default_scenario_object_i32(bytes, object_base, x_offset);
    payload.y_payload =
        read_default_scenario_object_u32(bytes, object_base, y_offset);
    return payload;
}

void write_default_scenario_object_command_payload(std::vector<u8>& bytes,
    std::size_t object_base, std::size_t state_offset,
    std::size_t value_offset, std::size_t x_offset, std::size_t y_offset,
    const GameplayScriptCommandPayload& payload) {
    write_default_scenario_object_u32(bytes, object_base, state_offset,
        payload.state);
    write_default_scenario_object_u32(bytes, object_base, value_offset,
        default_unit_id_to_command_payload_reference(payload.state,
            static_cast<u32>(payload.command_value)));
    write_default_scenario_object_i32(bytes, object_base, x_offset,
        payload.x_payload);
    write_default_scenario_object_u32(bytes, object_base, y_offset,
        payload.y_payload);
}

UnitQueuedCommand to_unit_queued_command(
    const GameplayScriptCommandPayload& payload) {
    return UnitQueuedCommand{
        payload.state,
        payload.command_value,
        payload.x_payload,
        payload.y_payload,
    };
}

GameplayScriptCommandPayload from_unit_queued_command(
    const UnitQueuedCommand& command) {
    return GameplayScriptCommandPayload{
        command.state,
        command.x,
        command.y,
        command.value,
    };
}

void load_default_gameplay_script_scenario_object(
    GameplayScriptTriggerObjectState& object, const std::vector<u8>& bytes,
    u32 object_index) {
    const std::size_t object_base =
        static_cast<std::size_t>(object_index) * kGameplayScenarioObjectStride;
    object = GameplayScriptTriggerObjectState{};
    object.scenario_object_index = object_index;
    object.type_id = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectTypeOffset);
    object.owner_id = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectOwnerOffset);
    object.string_slot = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectStringSlotOffset);
    object.area_marker_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectAreaFlagsOffset);
    object.stat_18 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMaxHealthOffset);
    object.stat_secondary_max = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMaxSecondaryOffset);
    object.stat_20 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectHealthOffset);
    object.stat_1c = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectRuntimeStat1cOffset);
    object.stat_24 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectRuntimeStat20Offset);
    object.stat_secondary_current = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectSecondaryCurrentOffset);
    object.stat_28 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectRuntimeStat28Offset);
    object.stat_2c = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectStat2cOffset);
    object.stat_30 = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectStat30Offset);
    for (std::size_t slot = 0; slot < object.equipment_slots.size(); ++slot) {
        object.equipment_slots[slot] = read_default_scenario_object_u32(
            bytes, object_base, kGameplayScenarioObjectEquipmentSlotOffsets[slot]);
    }
    if (!scenario_object_uses_equipment_slot_zero(object.type_id)) {
        object.equipment_slots[0] = 0;
    }
    object.dynamic_string_slot = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectDynamicStringSlotOffset);
    object.stat_50 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectEliteProgressOffset);
    object.stat_54 = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectStatusTimerOffset);
    object.type_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectTypeFlagsOffset);
    object.command_bit_mask = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandBitsOffset);
    object.command_state_raw = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandStateOffset);
    object.script_state = object.command_state_raw & 0x00ffffffu;
    object.cargo_amount = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCargoAmountOffset);
    object.animation_frame = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectAnimationFrameOffset);
    // Raw +0x68 is a runtime-state-dependent union.  It can be an object pool
    // offset, a building-definition index, an order id, or a counter.  Runtime
    // unit ids already use original pool offsets, so preserving this DWORD
    // verbatim avoids interpreting the current-state and command namespaces as
    // though they were the same enum.
    object.command_value = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandValueOffset);
    object.scripted_target_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectPathTargetXOffset);
    object.scripted_target_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectPathTargetYOffset);
    object.previous_command_state = read_default_scenario_object_u32(
        bytes, object_base,
        kGameplayScenarioObjectPreviousCommandStateOffset) & 0x00ffffffu;
    object.pending_command = read_default_scenario_object_command_payload(bytes,
        object_base, kGameplayScenarioObjectPendingCommandStateOffset,
        kGameplayScenarioObjectPendingCommandValueOffset,
        kGameplayScenarioObjectPendingCommandXOffset,
        kGameplayScenarioObjectPendingCommandYOffset);
    // Raw +0x94 is another fixed-pool byte offset, not an intrusive-list slot.
    object.linked_object_id = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectLinkedObjectOffset);
    object.command_entry_lockout_ticks = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandEntryLockoutTicksOffset);
    object.command_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandFlagsOffset);
    object.flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectFlagsOffset);
    object.draw_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectDrawFlagsOffset);
    object.direction = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectDirectionOffset);
    object.movement_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMovementFlagsOffset);
    object.movement_state = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMovementStateOffset);
    object.movement_turn_ticks = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMovementTurnTicksOffset);
    object.x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectXOffset);
    object.y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectYOffset);
    object.destination_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectDestinationXOffset);
    object.destination_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectDestinationYOffset);
    object.destination_aux_state = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectDestinationAuxStateOffset);
    object.current_cell_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectCurrentCellXOffset);
    object.current_cell_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectCurrentCellYOffset);
    object.next_path_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectNextPathXOffset);
    object.next_path_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectNextPathYOffset);
    object.saved_path_target_x = object.next_path_x;
    object.saved_path_target_y = object.next_path_y;
    object.anchor_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectAnchorXOffset);
    object.anchor_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectAnchorYOffset);
    object.active_command_payload = read_default_scenario_object_command_payload(
        bytes, object_base, kGameplayScenarioObjectActiveCommandStateOffset,
        kGameplayScenarioObjectActiveCommandValueOffset,
        kGameplayScenarioObjectActiveCommandXOffset,
        kGameplayScenarioObjectActiveCommandYOffset);
    object.script_bit_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectScriptBitFlagsOffset);
    object.animation_timer = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectAnimationTimerOffset);
    object.linked_effect_slot_offset = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectLinkedEffectSlotOffset);
    object.command_lockout_ticks = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectCommandLockoutTicksOffset);
    object.saved_type_flags = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectSavedTypeFlagsOffset);
    object.placement_reset_scratch = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectPlacementResetScratchOffset);
    object.distance_check_mode = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectDistanceCheckModeOffset);
    object.movement_step_accumulator = read_default_scenario_object_u32(
        bytes, object_base, kGameplayScenarioObjectMovementStepAccumulatorOffset);
    object.movement_residual_x = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectMovementResidualXOffset);
    object.movement_residual_y = read_default_scenario_object_i32(
        bytes, object_base, kGameplayScenarioObjectMovementResidualYOffset);
    object.movement_interpolation_x = read_default_scenario_object_float(
        bytes, object_base, kGameplayScenarioObjectMovementInterpolationXOffset);
    object.movement_interpolation_y = read_default_scenario_object_float(
        bytes, object_base, kGameplayScenarioObjectMovementInterpolationYOffset);
    object.deferred_command_count = std::min<u32>(
        read_default_scenario_object_u32(bytes, object_base,
            kGameplayScenarioObjectDeferredCommandCountOffset),
        kGameplayScenarioObjectDeferredCommandCapacity);
    for (u32 slot = 0; slot < object.deferred_command_count; ++slot) {
        const std::size_t slot_base =
            kGameplayScenarioObjectDeferredCommandSlotsOffset +
            static_cast<std::size_t>(slot) *
                kGameplayScenarioObjectDeferredCommandStride;
        object.deferred_commands[slot] =
            read_default_scenario_object_command_payload(bytes, object_base,
                slot_base + 0x00, slot_base + 0x04, slot_base + 0x08,
                slot_base + 0x0c);
    }
    object.previous_object_index = default_scenario_object_reference_to_unit_id(
        read_default_scenario_object_u32(
            bytes, object_base, kGameplayScenarioObjectPreviousLinkOffset));
    object.next_object_index = default_scenario_object_reference_to_unit_id(
        read_default_scenario_object_u32(
            bytes, object_base, kGameplayScenarioObjectNextLinkOffset));
    object.remove_from_triggers = object.flags == 0 || (object.flags & 4u) != 0;
}

bool load_default_gameplay_script_scenario_objects(
    GameplayScriptTriggerState& script) {
    g_runtime.gameplay_script_scenario_objects_loaded = false;
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplayScenarioObjectRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplayScenarioObjectRecordIndex]) {
        return false;
    }

    const std::vector<u8>& objects =
        load.records[kGameplayScenarioObjectRecordIndex];
    if (objects.size() < kGameplayScenarioObjectStride * 2) {
        return false;
    }

    const u32 object_count = std::min<u32>(
        static_cast<u32>(objects.size() / kGameplayScenarioObjectStride),
        kGameplayScenarioObjectMaxSlots);
    if (script.objects.size() < object_count) {
        script.objects.resize(object_count);
    }

    for (u32 object_index = 1; object_index < object_count; ++object_index) {
        load_default_gameplay_script_scenario_object(
            script.objects[object_index], objects, object_index);
    }

    g_runtime.gameplay_script_scenario_objects_loaded = true;
    return true;
}

u32 read_default_map_layer_u32(const std::vector<u8>& bytes, u32 cell_index) {
    const std::size_t offset = static_cast<std::size_t>(cell_index) * sizeof(u32);
    if (offset > bytes.size() || bytes.size() - offset < sizeof(u32)) {
        return 0;
    }
    return static_cast<u32>(bytes[offset]) |
        (static_cast<u32>(bytes[offset + 1]) << 8) |
        (static_cast<u32>(bytes[offset + 2]) << 16) |
        (static_cast<u32>(bytes[offset + 3]) << 24);
}

void initialize_default_gameplay_movement_map_from_session_records(
    UnitMovementContext& movement) {
    UnitMovementMap map{};
    map.width = default_gameplay_session_map_width_tiles();
    map.height = default_gameplay_session_map_height_tiles();
    map.stride_tiles = kGameplayScenarioMapLayerStrideTiles;
    const std::size_t cell_count =
        static_cast<std::size_t>(UnitMovementMapStrideTiles(map)) * map.height;
    map.cells.resize(cell_count);

    const GameplaySessionLoadState& load = gameplay_session_load_state();
    const std::vector<u8>* source_layer = nullptr;
    if (kGameplayMapSourceLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayMapSourceLayerRecordIndex]) {
        source_layer = &load.records[kGameplayMapSourceLayerRecordIndex];
    }
    const std::vector<u8>* terrain_layer = nullptr;
    if (kGameplayScenarioMapLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayScenarioMapLayerRecordIndex]) {
        terrain_layer = &load.records[kGameplayScenarioMapLayerRecordIndex];
    }
    const std::vector<u8>* brush_layer = nullptr;
    if (kGameplayMapEffectLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayMapEffectLayerRecordIndex]) {
        brush_layer = &load.records[kGameplayMapEffectLayerRecordIndex];
    }

    // HandleGameplaySessionBundleImport loads these three fixed legacy grids
    // directly into DAT_00e99e74, DAT_00f19e74 and DAT_00758d40.  Their
    // presence is a property of the map, not of the value stored by one tile:
    // an all-zero source/brush tile must still take the original class-entry
    // path and is impassable for movement class 0.
    map.legacy_entry_layers_present =
        source_layer != nullptr && terrain_layer != nullptr &&
        brush_layer != nullptr;

    for (u32 y = 0; y < map.height; ++y) {
        for (u32 x = 0; x < map.width; ++x) {
            const u32 cell = UnitMovementMapTileIndex(map, x, y);
            u32 flags = terrain_layer != nullptr ?
                read_default_map_layer_u32(*terrain_layer, cell) : 0;
            if (terrain_layer == nullptr && (flags & kMapCellTerrainMask) == 0) {
                flags |= kMapCellPassableTerrain;
            }
            map.cells[cell].flags = flags;
            map.cells[cell].alternate_flags = source_layer != nullptr ?
                read_default_map_layer_u32(*source_layer, cell) : 0;
            map.cells[cell].visibility_flags = brush_layer != nullptr ?
                read_default_map_layer_u32(*brush_layer, cell) : 0;
        }
    }

    movement.map = std::move(map);
}

bool default_session_map_effect_offset_valid(u32 offset, u32 object_count) {
    return offset != 0 &&
        offset % kGameplayMapEffectObjectStride == 0 &&
        offset / kGameplayMapEffectObjectStride < object_count;
}

bool default_session_map_effect_link_offset_valid(u32 offset, u32 object_count) {
    return offset == 0 ||
        default_session_map_effect_offset_valid(offset, object_count);
}

bool default_session_map_effect_slot_has_occupancy(
    const std::vector<u8>& record, u32 index) {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (kGameplayMapEffectLayerRecordIndex >= load.records.size() ||
        !load.record_loaded[kGameplayMapEffectLayerRecordIndex]) {
        return true;
    }

    const std::size_t object_base =
        static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
    const i32 x = read_default_scenario_object_i32(
        record, object_base, kGameplayMapEffectObjectXOffset);
    const i32 y = read_default_scenario_object_i32(
        record, object_base, kGameplayMapEffectObjectYOffset);
    if (x < 0 || y < 0) {
        return false;
    }

    const UnitMovementCell* cell = GetMovementCell(
        g_runtime.gameplay_movement_context.map,
        static_cast<u32>(x) >> 5, static_cast<u32>(y) >> 5);
    return cell != nullptr &&
        (cell->visibility_flags & kMapEffectTileFlag) != 0;
}

bool recover_default_session_map_effect_chain_from_head(
    const std::vector<u8>& record, u32 object_count, u32 head_offset,
    std::vector<u32>& indices) {
    indices.clear();
    if (head_offset == 0) {
        return true;
    }
    if (!default_session_map_effect_offset_valid(head_offset, object_count)) {
        return false;
    }

    std::vector<bool> seen(object_count, false);
    u32 previous_offset = 0;
    u32 current_offset = head_offset;
    while (current_offset != 0) {
        if (!default_session_map_effect_offset_valid(
                current_offset, object_count)) {
            indices.clear();
            return false;
        }
        const u32 index = current_offset / kGameplayMapEffectObjectStride;
        if (seen[index]) {
            indices.clear();
            return false;
        }
        seen[index] = true;

        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        const u32 stored_previous = read_default_scenario_object_u32(
            record, object_base, kGameplayMapEffectObjectPreviousOffset);
        const u32 stored_next = read_default_scenario_object_u32(
            record, object_base, kGameplayMapEffectObjectNextOffset);
        if (stored_previous != previous_offset ||
            !default_session_map_effect_link_offset_valid(
                stored_next, object_count)) {
            indices.clear();
            return false;
        }

        indices.push_back(index);
        previous_offset = current_offset;
        current_offset = stored_next;
    }
    return true;
}

std::vector<u32> recover_default_session_active_map_effect_indices(
    const std::vector<u8>& record, u32 object_count) {
    std::vector<u32> best_indices;
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    const bool occupancy_layer_loaded =
        kGameplayMapEffectLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayMapEffectLayerRecordIndex];

    for (u32 head_index = 1; head_index < object_count; ++head_index) {
        const std::size_t head_base =
            static_cast<std::size_t>(head_index) * kGameplayMapEffectObjectStride;
        if (read_default_scenario_object_u32(
                record, head_base, kGameplayMapEffectObjectPreviousOffset) != 0) {
            continue;
        }

        std::vector<u32> indices;
        std::vector<bool> seen(object_count, false);
        u32 previous_offset = 0;
        u32 current_offset = head_index * kGameplayMapEffectObjectStride;
        bool valid = true;

        while (current_offset != 0) {
            if (!default_session_map_effect_offset_valid(
                    current_offset, object_count)) {
                valid = false;
                break;
            }
            const u32 index = current_offset / kGameplayMapEffectObjectStride;
            if (seen[index]) {
                valid = false;
                break;
            }
            seen[index] = true;

            const std::size_t object_base =
                static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
            if (read_default_scenario_object_u32(
                    record, object_base, kGameplayMapEffectObjectPreviousOffset) !=
                    previous_offset ||
                !default_session_map_effect_link_offset_valid(
                    read_default_scenario_object_u32(
                        record, object_base, kGameplayMapEffectObjectNextOffset),
                    object_count)) {
                valid = false;
                break;
            }

            const u32 effect_id = read_default_scenario_object_u32(
                record, object_base, kGameplayMapEffectObjectTypeOffset);
            // With no authoritative header list, the BGI occupancy bit is the
            // only evidence that distinguishes active type 0 from a free node
            // whose stale payload is also zero.  Older/headerless bundles can
            // omit that layer, so retain the prior nonzero-type fallback then.
            if (default_session_map_effect_slot_has_occupancy(record, index) &&
                (effect_id != 0 || occupancy_layer_loaded)) {
                indices.push_back(index);
            }
            previous_offset = current_offset;
            current_offset = read_default_scenario_object_u32(
                record, object_base, kGameplayMapEffectObjectNextOffset);
        }

        if (valid && indices.size() > best_indices.size()) {
            best_indices = std::move(indices);
        }
    }

    if (!best_indices.empty()) {
        return best_indices;
    }

    for (u32 index = 1; index < object_count; ++index) {
        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        const u32 effect_id = read_default_scenario_object_u32(
            record, object_base, kGameplayMapEffectObjectTypeOffset);
        if (default_session_map_effect_slot_has_occupancy(record, index) &&
            (effect_id != 0 || occupancy_layer_loaded)) {
            best_indices.push_back(index);
        }
    }
    return best_indices;
}

void initialize_default_map_effect_context_from_session_records() {
    MapEffectContext& context = g_runtime.map_effect_context;
    context = MapEffectContext{};
    context.effects.resize(1);
    context.effects[0].id = 0;

    std::vector<u8>* record =
        MutableGameplaySessionLoadedRecord(kGameplayMapEffectObjectRecordIndex);
    if (record == nullptr ||
        record->size() < kGameplayMapEffectObjectStride * 2) {
        configure_default_map_effect_context();
        return;
    }

    const u32 object_count = std::min<u32>(
        static_cast<u32>(record->size() / kGameplayMapEffectObjectStride),
        kGameplayMapEffectObjectMaxSlots);
    context.effects.assign(object_count, MapEffectInstance{});
    for (u32 index = 0; index < object_count; ++index) {
        const std::size_t object_base =
            static_cast<std::size_t>(index) * kGameplayMapEffectObjectStride;
        MapEffectInstance& effect = context.effects[index];
        effect.id = index;
        HydrateMapEffectRawRecord(effect, record->data() + object_base,
            record->size() - object_base);
    }

    std::vector<u32> active_indices;
    std::vector<u32> free_head_to_tail;
    bool restored_header_lists = false;
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (!load.records.empty() && load.record_loaded[0] &&
        load.records[0].size() >=
            kGameplayHeaderMapEffectFreeListHeadOffset + sizeof(u32)) {
        const std::vector<u8>& header = load.records[0];
        const u32 active_head = read_default_session_record_u32(
            header, kGameplayHeaderMapEffectActiveListHeadOffset, 0);
        const u32 free_head = read_default_session_record_u32(
            header, kGameplayHeaderMapEffectFreeListHeadOffset, 0);
        const bool active_chain_valid =
            recover_default_session_map_effect_chain_from_head(
                *record, object_count, active_head, active_indices);
        const bool free_chain_valid =
            recover_default_session_map_effect_chain_from_head(
                *record, object_count, free_head, free_head_to_tail);

        if (active_chain_valid && free_chain_valid) {
            std::vector<bool> listed(object_count, false);
            restored_header_lists = true;
            for (u32 index : active_indices) {
                if (listed[index]) {
                    restored_header_lists = false;
                    break;
                }
                listed[index] = true;
            }
            if (restored_header_lists) {
                for (u32 index : free_head_to_tail) {
                    if (listed[index]) {
                        restored_header_lists = false;
                        break;
                    }
                    listed[index] = true;
                }
            }
            if (restored_header_lists) {
                for (u32 index = 1; index < object_count; ++index) {
                    if (!listed[index]) {
                        restored_header_lists = false;
                        break;
                    }
                }
            }
        }
    }
    if (!restored_header_lists) {
        active_indices = recover_default_session_active_map_effect_indices(
            *record, object_count);
        free_head_to_tail.clear();
    }

    std::vector<bool> active(object_count, false);
    for (u32 index : active_indices) {
        if (index == 0 || index >= object_count || active[index]) {
            continue;
        }

        MapEffectInstance& effect = context.effects[index];
        effect.active = true;
        if (effect.linked_unit_raw_offset != 0) {
            effect.linked_unit = find_default_movement_unit_by_id(
                effect.linked_unit_raw_offset);
        }
        context.active_effect_indices.push_back(index);
        active[index] = true;
    }

    if (restored_header_lists) {
        // AllocateMapEffect pops the vector back, so reverse the serialized
        // free chain to keep its original head as the next allocation.
        context.free_effect_indices.assign(
            free_head_to_tail.rbegin(), free_head_to_tail.rend());
    } else {
        for (u32 index = object_count; index > 1; --index) {
            const u32 slot = index - 1;
            if (!active[slot]) {
                context.free_effect_indices.push_back(slot);
            }
        }
    }
    configure_default_map_effect_context();
    ResetImportedMapEffectsForSessionMode(context,
        g_runtime.gameplay_startup_state.session_mode);
}

void initialize_default_unit_effect_runtime_from_session_records() {
    UnitEffectRuntimeState& effects =
        g_runtime.gameplay_unit_effect_runtime;
    effects.effect_slot_capacity = kGameplayUnitEffectUsableSlotCount;
    effects.effect_slots.assign(
        kGameplayUnitEffectUsableSlotCount, UnitEffectRuntime{});
    effects.active_effect_indices.clear();
    effects.free_effect_indices.clear();
    configure_default_unit_effect_runtime_state(effects);

    const GameplaySessionLoadState& load = gameplay_session_load_state();
    const std::vector<u8>* record = nullptr;
    if (kGameplayUnitEffectObjectRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayUnitEffectObjectRecordIndex] &&
        load.records[kGameplayUnitEffectObjectRecordIndex].size() >=
            static_cast<std::size_t>(kGameplayUnitEffectRawBlockCount) *
                kGameplayUnitEffectObjectStride) {
        record = &load.records[kGameplayUnitEffectObjectRecordIndex];
    }

    if (record != nullptr) {
        for (std::size_t index = 0;
             index < effects.effect_slots.size(); ++index) {
            UnitEffectRuntime& effect = effects.effect_slots[index];
            const std::size_t object_base =
                (index + 1u) * kGameplayUnitEffectObjectStride;
            const auto read_field = [&](std::size_t field, u32 fallback = 0u) {
                return read_default_session_record_u32(
                    *record, object_base + field, fallback);
            };
            const auto read_signed_field = [&](std::size_t field) {
                const u32 raw = read_field(field);
                return WrappedU32ToI32(raw);
            };

            effect.effect_id = read_field(kGameplayUnitEffectObjectIdOffset);
            effect.direction = read_field(
                kGameplayUnitEffectObjectDirectionOffset);
            effect.flags = read_field(kGameplayUnitEffectObjectFlagsOffset);
            effect.amount = read_field(kGameplayUnitEffectObjectAmountOffset);
            effect.source_unit_id = read_field(
                kGameplayUnitEffectObjectSourceUnitOffset);
            const u32 target_reference = read_field(
                kGameplayUnitEffectObjectTargetUnitOffset);
            effect.target_unit_id = target_reference;
            effect.linked_unit_id = target_reference;
            effect.x = read_signed_field(kGameplayUnitEffectObjectXOffset);
            effect.y = read_signed_field(kGameplayUnitEffectObjectYOffset);
            effect.target_x = read_signed_field(
                kGameplayUnitEffectObjectTargetXOffset);
            effect.target_y = read_signed_field(
                kGameplayUnitEffectObjectTargetYOffset);
            effect.delta_x = effect.target_x - effect.x;
            effect.delta_y = effect.target_y - effect.y;
            effect.step_x = read_signed_field(
                kGameplayUnitEffectObjectStepXOffset);
            effect.step_y = read_signed_field(
                kGameplayUnitEffectObjectStepYOffset);
            effect.closest_distance = read_field(
                kGameplayUnitEffectObjectClosestDistanceOffset,
                0xffffffffu);

            const u32 raw_counter0c = read_field(
                kGameplayUnitEffectObjectCounter0cOffset);
            const u32 raw_state10 = read_field(
                kGameplayUnitEffectObjectState10Offset);
            const bool uses_serialized_path_axes =
                default_unit_effect_uses_serialized_path_axes(effects, effect);
            if (effect.effect_id >= 0x3du && uses_serialized_path_axes) {
                effect.tick = raw_counter0c;
                effect.range = raw_state10;
                // Keep the dynamic raw +0x10 alias coherent for render paths
                // that inspect frame immediately as impact is entered.
                effect.frame = raw_state10;
            } else if (effect.effect_id >= 0x3du) {
                effect.tick = raw_counter0c;
                effect.frame = raw_state10;
            } else if (effect.effect_id == 0x1eu ||
                (effect.effect_id == 0x20u &&
                    (effect.flags & kUnitEffectFlagAfterimageClone) != 0)) {
                effect.frame = raw_counter0c;
                effect.tick = raw_state10;
            } else if ((effect.flags & kUnitEffectFlagStartup) != 0) {
                effect.tick = raw_counter0c;
                effect.frame = raw_state10;
            } else {
                effect.frame = raw_counter0c;
                effect.tick = raw_counter0c;
                if ((effect.flags & kUnitEffectFlagImpact) == 0) {
                    effect.range = raw_state10;
                }
            }
            if ((effect.effect_id == 0x22u || effect.effect_id == 0x26u) &&
                (effect.flags & kUnitEffectFlagImpact) != 0) {
                // The original increments raw +0x10 before its one-shot
                // impact call; restoring false would apply the damage twice.
                effect.initial_impact_applied = raw_state10 != 0;
            }

            const u32 raw_axis30 = read_field(
                kGameplayUnitEffectObjectAxis30Offset);
            const u32 raw_axis34 = read_field(
                kGameplayUnitEffectObjectAxis34Offset);
            const u32 raw_abs_x = read_field(
                kGameplayUnitEffectObjectAbsXOffset);
            const u32 raw_abs_y = read_field(
                kGameplayUnitEffectObjectAbsYOffset);
            effect.previous_x = WrappedU32ToI32(raw_axis30);
            effect.previous_y = WrappedU32ToI32(raw_axis34);
            if (uses_serialized_path_axes) {
                effect.previous_x = effect.x;
                effect.previous_y = effect.y;
                effect.abs_delta_x = raw_abs_x;
                effect.abs_delta_y = raw_abs_y;
                if ((effect.flags &
                        kUnitEffectFlagProjectileYMajor) != 0) {
                    effect.accumulator_x = raw_axis30;
                    effect.accumulator_y = raw_abs_y;
                } else {
                    effect.accumulator_x = raw_abs_x;
                    effect.accumulator_y = raw_axis34;
                }
            } else {
                // High-id handlers reuse +0x30/+0x34 for typed counters.
                // Seed all aliases; export overlays only the evidenced one.
                effect.abs_delta_x = raw_axis30;
                effect.abs_delta_y = raw_axis34;
                effect.accumulator_x = raw_abs_x;
                effect.accumulator_y = raw_abs_y;
            }

            if (effect.effect_id == 0x17u) {
                effect.chain_remaining = read_field(
                    kGameplayUnitEffectObjectHitHistoryOffset);
                for (std::size_t chain = 0;
                     chain < effect.chained_target_ids.size(); ++chain) {
                    effect.chained_target_ids[chain] = read_field(
                        kGameplayUnitEffectObjectHitHistoryOffset +
                        (chain + 1u) * sizeof(u32));
                }
            } else if (effect.effect_id < 0x3du) {
                const u32 hit_count = std::min<u32>(read_field(
                    kGameplayUnitEffectObjectHitCountOffset),
                    kGameplayUnitEffectHitHistoryCapacity);
                effect.hit_unit_ids.reserve(hit_count);
                for (u32 hit = 0; hit < hit_count; ++hit) {
                    effect.hit_unit_ids.push_back(read_field(
                        kGameplayUnitEffectObjectHitHistoryOffset +
                        static_cast<std::size_t>(hit) * sizeof(u32)));
                }
            }
        }
    }

    std::vector<std::size_t> active_head_to_tail;
    std::vector<std::size_t> free_head_to_tail;
    bool restored_lists = false;
    if (record != nullptr && !load.records.empty() && load.record_loaded[0]) {
        restored_lists = recover_default_unit_effect_serialized_lists(
            load.records[0], *record,
            active_head_to_tail, free_head_to_tail);
    }
    if (!restored_lists) {
        active_head_to_tail.clear();
        free_head_to_tail.resize(kGameplayUnitEffectUsableSlotCount);
        std::iota(free_head_to_tail.begin(), free_head_to_tail.end(), 0u);
    }
    effects.active_effect_indices = active_head_to_tail;
    effects.free_effect_indices = free_head_to_tail;
    for (const std::size_t index : effects.active_effect_indices) {
        if (index < effects.effect_slots.size()) {
            effects.effect_slots[index].active = true;
        }
    }

    UnitLifecycleContext* lifecycle =
        g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle != nullptr && lifecycle->movement != nullptr) {
        const auto bind_reserved_effects = [&](
            const std::vector<UnitMovementUnit*>& units) {
            for (UnitMovementUnit* unit : units) {
                if (unit == nullptr) {
                    continue;
                }
                rebind_default_reserved_tile_effect_from_raw_cargo(*unit);
            }
        };
        bind_reserved_effects(lifecycle->movement->active_units);
        bind_reserved_effects(lifecycle->movement->lifecycle_units);
        bind_reserved_effects(lifecycle->movement->free_units);
        sync_default_unit_effect_runtime_units(effects, *lifecycle);
    }
}

void initialize_default_gameplay_terrain_layer_from_session_records() {
    MinimapTerrainLayer layer{};
    layer.width_tiles = default_gameplay_session_map_width_tiles();
    layer.height_tiles = default_gameplay_session_map_height_tiles();
    layer.stride_tiles = kGameplayScenarioMapLayerStrideTiles;
    const std::size_t cell_count =
        static_cast<std::size_t>(layer.stride_tiles) * layer.height_tiles;
    layer.terrain_flags.resize(cell_count);
    layer.overlay_flags.resize(cell_count);

    const GameplaySessionLoadState& load = gameplay_session_load_state();
    const std::vector<u8>* terrain_source = nullptr;
    if (kGameplayMapSourceLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayMapSourceLayerRecordIndex]) {
        terrain_source = &load.records[kGameplayMapSourceLayerRecordIndex];
    }
    const std::vector<u8>* overlay_source = nullptr;
    if (kGameplayMapOverlayLayerRecordIndex < load.records.size() &&
        load.record_loaded[kGameplayMapOverlayLayerRecordIndex]) {
        overlay_source = &load.records[kGameplayMapOverlayLayerRecordIndex];
    }

    for (u32 y = 0; y < layer.height_tiles; ++y) {
        for (u32 x = 0; x < layer.width_tiles; ++x) {
            const u32 cell = y * layer.stride_tiles + x;
            if (terrain_source != nullptr) {
                layer.terrain_flags[cell] =
                    read_default_map_layer_u32(*terrain_source, cell);
            }
            if (overlay_source != nullptr) {
                layer.overlay_flags[cell] =
                    read_default_map_layer_u32(*overlay_source, cell);
            }
        }
    }

    g_runtime.gameplay_terrain_layer = std::move(layer);
    reset_default_gameplay_terrain_frame_cache();
    ResetTerrainTilePulseState(g_runtime.gameplay_terrain_pulse_state);
}

void default_gameplay_frame_draw_terrain(
    GameplayFrameRenderContext& context, i32 camera_x, i32 camera_y) {
    if (!g_runtime.gameplay_terrain_tile_sheet_loaded ||
        g_runtime.gameplay_terrain_tile_sheet.tile_pixels.empty() ||
        g_runtime.gameplay_terrain_layer.terrain_flags.empty()) {
        return;
    }

    const SpriteRenderState& sprite_state = sprite_render_state();
    if (!sprite_state.active || sprite_state.target.pixels == nullptr ||
        sprite_state.target.width == 0 || sprite_state.target.height == 0) {
        return;
    }

    TerrainViewportRenderState& state =
        g_runtime.gameplay_terrain_viewport_render_state;
    state.target_width_pixels = sprite_state.target.width;
    state.target_height_pixels = sprite_state.target.height;
    state.target_pitch_pixels = sprite_state.target.stride_words != 0 ?
        sprite_state.target.stride_words : sprite_state.target.width;
    BuildTerrainTileDrawCommands(
        state, g_runtime.gameplay_terrain_layer, camera_x, camera_y);

    SpriteRenderTarget target = sprite_state.target;
    const u32 animation_slot = context.animation_frame_slot;
    if (restore_default_gameplay_terrain_frame_cache(
            target, camera_x, camera_y, animation_slot)) {
        return;
    }

    for (const TerrainTileDrawCommand& command : state.draw_commands) {
        switch (command.kind) {
        case TerrainTileDrawKind::uniform:
            default_gameplay_draw_uniform_terrain_tile(
                g_runtime.gameplay_terrain_tile_sheet, command, target,
                animation_slot);
            break;
        case TerrainTileDrawKind::blended:
            default_gameplay_draw_blended_terrain_tile(
                g_runtime.gameplay_terrain_tile_sheet, command, target,
                animation_slot);
            break;
        case TerrainTileDrawKind::overlay:
            default_gameplay_draw_overlay_terrain_tile(
                g_runtime.gameplay_terrain_tile_sheet, command, target,
                animation_slot);
            break;
        default:
            break;
        }
    }
    // The terrain layer is static between camera or animation-slot changes.
    // Replaying its roughly two-millisecond software tile composite on every
    // present-only pass slowed the random wizard construction/harvest trail
    // from the original executable's roughly 300 redraws/s to about 200.
    // Cache only this base layer; units, effects, fog, and the HUD are still
    // rebuilt every pass, so the visible trail and all dynamic state retain
    // their original per-present behavior.
    capture_default_gameplay_terrain_frame_cache(
        target, camera_x, camera_y, animation_slot);
}

void default_gameplay_frame_draw_terrain_decorations(
    GameplayFrameRenderContext& context) {
    if (context.render_command_queue == nullptr ||
        g_runtime.gameplay_terrain_layer.terrain_flags.empty()) {
        return;
    }

    const Jw207ResourcePackState& jw207 = jw207_resource_pack_state();
    const bool terrain_type1_loaded =
        jw207.berry_start != kInvalidResourceEntry;
    const bool terrain_type3_loaded =
        g_runtime.gameplay_terrain_tile_sheet_loaded &&
        TerrainTileSheetBankAllocationsValid(
            g_runtime.gameplay_terrain_tile_sheet) &&
        g_runtime.gameplay_terrain_tile_sheet.resource_start !=
            kInvalidTerrainTileResourceIndex;
    if (!terrain_type1_loaded && !terrain_type3_loaded) {
        return;
    }

    TerrainDecorationLayer terrain_layer{};
    terrain_layer.width_tiles = g_runtime.gameplay_terrain_layer.width_tiles;
    terrain_layer.height_tiles = g_runtime.gameplay_terrain_layer.height_tiles;
    terrain_layer.stride_tiles = g_runtime.gameplay_terrain_layer.stride_tiles;
    terrain_layer.tile_flags = g_runtime.gameplay_terrain_layer.terrain_flags;

    const GameplayVisibilityGrid& visibility_grid =
        g_runtime.gameplay_visibility_grid;
    if (!visibility_grid.terrain_backup.empty() &&
        visibility_grid.width == terrain_layer.width_tiles &&
        visibility_grid.height == terrain_layer.height_tiles) {
        terrain_layer.stride_tiles = visibility_grid.width;
        terrain_layer.tile_flags = visibility_grid.terrain_backup;
    }

    TerrainDecorationLayer brush_layer{};
    brush_layer.width_tiles = terrain_layer.width_tiles;
    brush_layer.height_tiles = terrain_layer.height_tiles;
    brush_layer.stride_tiles = terrain_layer.stride_tiles;
    if (!visibility_grid.previous.empty() &&
        visibility_grid.width == terrain_layer.width_tiles &&
        visibility_grid.height == terrain_layer.height_tiles) {
        brush_layer.stride_tiles = visibility_grid.width;
        brush_layer.tile_flags = visibility_grid.previous;
    }
    TerrainDecorationResourceTable brush_resources{};
    const bool unit_resource_images_valid =
        UnitDefinitionResourceCatalogImageResourcesValid() ||
        LoadUnitDefinitionResourceCatalog();
    const UnitDefinitionResourceCatalogState& unit_resources =
        unit_definition_resource_catalog_state();
    if (unit_resource_images_valid) {
        brush_resources.resource_base_by_id.resize(unit_resources.records.size(), 0);
        for (std::size_t id = 0; id < unit_resources.records.size(); ++id) {
            const UnitDefinitionResourceRecord& record = unit_resources.records[id];
            if (record.loaded &&
                record.first_image_entries[0] != kInvalidResourceEntry) {
                // FUN_00424ba0 indexes DAT_00aebfb8 with the brush id's
                // 0x38-byte definition stride and uses its first image entry.
                brush_resources.resource_base_by_id[id] =
                    static_cast<i32>(record.first_image_entries[0]);
            }
        }
    }

    TerrainDecorationRenderState& state =
        g_runtime.gameplay_terrain_decoration_render_state;
    state.visible_left_world = context.expanded_left;
    state.visible_top_world = context.expanded_top;
    state.visible_right_world = context.expanded_right;
    state.visible_bottom_world = context.expanded_bottom;
    state.camera_x = context.camera_x;
    state.camera_y = context.camera_y;
    state.terrain_type1_resource_base =
        terrain_type1_loaded ? static_cast<i32>(jw207.berry_start) : 0;
    BuildVisibleTerrainDecorationRenderCommands(state, terrain_layer,
        brush_layer, brush_resources, g_runtime.gameplay_terrain_tile_sheet);

    for (const TerrainDecorationRenderCommand& decoration :
         state.render_commands) {
        if (decoration.resource_index < 0) {
            continue;
        }
        if (decoration.kind == TerrainDecorationRenderKind::terrain_type1 &&
            !terrain_type1_loaded) {
            continue;
        }
        if (decoration.kind == TerrainDecorationRenderKind::terrain_type3 &&
            !terrain_type3_loaded) {
            continue;
        }

        GameplayRenderCommand command{};
        command.class_id = decoration.render_layer;
        command.payload = static_cast<u32>(decoration.kind);
        command.sort_key = decoration.sort_key;
        command.sprite_entry_index =
            static_cast<u32>(decoration.resource_index);
        command.screen_x = decoration.screen_x;
        command.screen_y = decoration.screen_y;
        command.packed_flags = decoration.flags;
        QueueGameplayRenderCommand(*context.render_command_queue, command);
    }
}

void sync_default_gameplay_clock_and_random_state_to_session_header(
    std::vector<u8>& header) {
    // OBC raw +0x48 indexes the 256 x 20-byte table at primary-record +0x08.
    // Keep runtime-created names and authored campaign hero names in the same
    // record when saving, exactly as the original fixed string pool does.
    ExportUnitStringSlotsToSessionHeader(
        g_runtime.gameplay_movement_context.string_slots,
        header.data(), header.size());

    const GameplayLoopState& loop = gameplay_loop_state();
    const GameplayFrameRandomState& random =
        g_runtime.gameplay_frame_random_state;
    write_default_session_buffer_u32(header,
        kGameplayHeaderPresentFrameOffset,
        loop.present_frame_counter);
    write_default_session_buffer_u32(header,
        kGameplayHeaderSimulationFrameOffset,
        loop.simulation_frame_counter);
    const UiOverlayState& overlay = ui_overlay_state();
    write_default_session_buffer_u32(header,
        kSessionPrimaryCameraXOffset,
        static_cast<u32>(overlay.camera_x));
    write_default_session_buffer_u32(header,
        kSessionPrimaryCameraYOffset,
        static_cast<u32>(overlay.camera_y));
    write_default_session_buffer_u32(header,
        kGameplayHeaderRandomLimitOffset, random.limit);
    write_default_session_buffer_u32(header,
        kGameplayHeaderRandomSeedOffset, random.seed);
    write_default_session_buffer_u32(header,
        kGameplayHeaderRandomCallCountOffset, random.call_count);
}

bool restore_default_gameplay_camera_from_session_header() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (load.records.empty() || !load.record_loaded[0]) {
        return false;
    }

    const std::vector<u8>& header = load.records[0];
    GameplaySessionPrimaryCamera camera{};
    if (!ReadGameplaySessionPrimaryCamera(
            header.data(), header.size(), camera)) {
        return false;
    }

    // HandleGameplaySessionBundleImport copies the primary record over the
    // live camera globals without centering or clamping them.  A normal local
    // starting unit may replace this value later; mode 5 otherwise retains
    // the serialized viewport exactly.
    UiOverlayState& overlay = ui_overlay_state();
    overlay.camera_x = camera.x;
    overlay.camera_y = camera.y;
    publish_default_ui_overlay_camera(overlay);
    return true;
}

void restore_default_gameplay_simulation_frame_from_session_header() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (load.records.empty() || !load.record_loaded[0]) {
        return;
    }
    const std::vector<u8>& header = load.records[0];
    GameplayLoopState& loop = gameplay_loop_state();
    loop.present_frame_counter = read_default_session_record_u32(
        header, kGameplayHeaderPresentFrameOffset, 0);
    loop.simulation_frame_counter = read_default_session_record_u32(
        header, kGameplayHeaderSimulationFrameOffset, 0);
}

void restore_default_gameplay_random_state_from_session_header() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (load.records.empty() || !load.record_loaded[0]) {
        return;
    }

    const std::vector<u8>& header = load.records[0];
    if (header.size() < kGameplayHeaderRandomCallCountOffset + sizeof(u32)) {
        return;
    }

    // HandleGameplaySessionBundleImport (0x004d1ccc) copies record 0 to
    // DAT_00705d98.  The present/simulation clocks at DAT_007071a0/a4 are
    // therefore +0x1408/+0x140c, and the frame RNG globals at
    // 0x007071b8/0x007071bc/0x007071c0 are +0x1420/+0x1424/+0x1428.
    // Treating a loaded game as frame zero reruns FUN_0043cc00 and changes
    // every later deterministic roll.
    restore_default_gameplay_simulation_frame_from_session_header();
    GameplayFrameRandomState& random = g_runtime.gameplay_frame_random_state;
    random.limit = read_default_session_record_u32(
        header, kGameplayHeaderRandomLimitOffset, random.limit);
    random.seed = read_default_session_record_u32(
        header, kGameplayHeaderRandomSeedOffset, random.seed);
    random.call_count = read_default_session_record_u32(
        header, kGameplayHeaderRandomCallCountOffset, random.call_count);
}

void restore_default_gameplay_unit_string_slots_from_session_header() {
    const GameplaySessionLoadState& load = gameplay_session_load_state();
    if (load.records.empty() || !load.record_loaded[0]) {
        return;
    }

    const std::vector<u8>& header = load.records[0];
    ImportUnitStringSlotsFromSessionHeader(
        g_runtime.gameplay_movement_context.string_slots,
        header.data(), header.size());
}

void run_default_gameplay_session_runtime_reset(
    GameplaySessionStartupState& startup, const char* player_name) {
    mirror_startup_slots_to_player_runtime(startup, g_runtime.gameplay_player_slots);
    sync_startup_owner_factions_to_lifecycle(startup);
    apply_default_gameplay_speed_index(startup.frame_interval_index, true);

    GameplaySessionRuntimeResetState reset{};
    reset.import_state = &g_runtime.session_runtime_import_state;
    reset.active_definitions = &g_runtime.active_session_definitions;
    reset.staged_definitions = &g_runtime.base_session_definitions;
    reset.non_empty_staged_definitions = &g_runtime.staged_session_definitions;
    reset.players = &g_runtime.gameplay_player_slots;
    reset.lifecycle = startup.lifecycle;
    reset.owner_counters = &g_runtime.gameplay_owner_counters;
    reset.script_dialog = &gameplay_script_dialog_state();
    reset.script_triggers = &gameplay_script_trigger_state();
    reset.unit_reference_tables = &g_runtime.unit_reference_tables;
    reset.post_init_snapshot = &g_runtime.gameplay_post_init_snapshot;
    reset.session_mode = startup.session_mode;
    reset.rotation_reset_units = startup.rotation_reset_units;
    reset.default_player_name = player_name != nullptr && player_name[0] != '\0' ?
        player_name : "Player";
    reset.owner_display_names = startup.owner_display_names;
    reset.callbacks.reset_effect_runtime =
        default_gameplay_session_reset_effect_runtime;
    reset.callbacks.reset_ui_runtime_flags =
        default_gameplay_session_reset_ui_runtime_flags;
    reset.callbacks.before_non_empty_runtime_tables_import =
        default_gameplay_session_prepare_non_empty_runtime_definition_import;
    reset.callbacks.on_unit_reset_or_removed =
        default_gameplay_session_unit_reset_or_removed;
    reset.callbacks.update_owner_display_name =
        default_gameplay_session_update_owner_display_name;

    prepare_default_base_session_runtime_definition_import();
    restore_default_production_runtime_from_session_header();
    mirror_default_production_variants_to_session_import_state();
    InitializeGameplaySessionRuntimeState(reset);
    if (startup.session_mode != 5) {
        // FUN_00426770 clears the complete 0x800 order-cell block and effect
        // tables 0..13 on fresh/normal sessions after the definition import.
        // Its four tail tables (14..17) survive; mode 5 keeps all imported
        // production state.
        ResetProductionOrderRuntimeStateForFreshSession(
            g_runtime.gameplay_production_runtime);
        g_runtime.gameplay_pending_order_2b_bonus_snapshots.clear();
        mirror_default_production_variants_to_session_import_state();
    }
    // Player record 3 owns the live resources for mode-5 loads.  The startup
    // lifecycle was freshly constructed after the record was decoded, so
    // publish the imported player values to lifecycle, command and production
    // views only after their reset passes have completed.
    sync_link_lobby_startup_resources_to_lifecycle(
        g_runtime.gameplay_player_slots, startup.lifecycle);
    finalize_default_session_runtime_definition_import();
    restore_default_gameplay_random_state_from_session_header();
    restore_default_gameplay_unit_string_slots_from_session_header();
    sync_default_gameplay_session_runtime_views_after_reset();
    rebuild_default_unit_reference_tables_from_catalog();
    load_default_game_session_avatar_runtime();
    // The original record-5 import at 0x004d1e82 belongs to the mode-5
    // saved-session bundle loader.  Fresh/link sessions still execute the
    // trigger processor every frame, but FUN_00416440 sees the trigger table
    // left empty by the normal-session reset.  Importing a multiplayer map's
    // dormant editor TRIGGERS record here made reconstructed peers execute
    // commands that the original peer never loaded.
    if (startup.session_mode == 5) {
        load_default_gameplay_script_triggers_from_session_archive(
            gameplay_script_trigger_state());
    }
    else {
        g_runtime.gameplay_script_triggers_loaded = false;
        g_runtime.gameplay_script_trigger_record_index = 0xffffffffu;
    }
    load_default_gameplay_script_scenario_objects(gameplay_script_trigger_state());
}

void default_gameplay_flow_start_session_from_slots(GameplaySessionFlowState& state) {
    const bool campaign_stage_session =
        g_runtime.frontend_stage_transition_active;
    const bool frontend_loaded_save = state.loaded_save_session;
    append_startup_log("start-slots: begin archive=%s frontend_mode=%lu",
        g_runtime.gameplay_session_archive_path.c_str(),
        static_cast<unsigned long>(g_runtime.frontend_mode));
    g_runtime.p2p_session_start_state = P2PGameSessionStartState{};
    g_runtime.session_runtime_import_state = SessionRuntimeImportState{};
    g_runtime.active_session_definitions = SessionRuntimeDefinitionTableSet{};
    g_runtime.base_session_definitions = SessionRuntimeDefinitionTableSet{};
    g_runtime.staged_session_definitions = SessionRuntimeDefinitionTableSet{};
    g_runtime.gameplay_session_runtime_buffers = SessionRuntimeBufferPairs{};
    g_runtime.gameplay_session_forces_fixed_records.clear();
    g_runtime.gameplay_session_user_runtime_overrides_loaded = false;
    g_runtime.gameplay_session_forces_record_loaded = false;
    g_runtime.gameplay_session_runtime_definitions_staged = false;
    ResetGameSessionAvatarRuntime(g_runtime.gameplay_avatar_runtime);
    g_runtime.gameplay_avatar_runtime_loaded = false;
    // FUN_00426770 does not clear the three process-global reverse-reference
    // tables.  Keep their prior contents across matches, but discard the
    // typed projection of the previous session's mutable definition records.
    g_runtime.unit_reference_tables.definitions = {};
    g_runtime.unit_reference_tables.post_init_transition_pending = false;
    g_runtime.unit_definition_cache = {};
    g_runtime.unit_definition_cache_valid = {};
    g_runtime.gameplay_owner_counters = OwnerSessionCounterTables{};
    g_runtime.gameplay_post_init_snapshot = PostInitTransitionSnapshot{};
    g_runtime.gameplay_damage_context = UnitDamageContext{};
    g_runtime.gameplay_frame_random_state = GameplayFrameRandomState{};
    g_runtime.gameplay_targeting_context = UnitTargetingContext{};
    g_runtime.gameplay_unit_actions = UnitActionContext{};
    g_runtime.gameplay_unit_commands = UnitCommandContext{};
    g_runtime.gameplay_unit_support_effects = UnitSupportEffectContext{};
    g_runtime.gameplay_visibility_grid = GameplayVisibilityGrid{};
    g_runtime.gameplay_visibility_context = GameplayVisibilityContext{};
    g_runtime.gameplay_visibility_units.clear();
    g_runtime.gameplay_fog_context = GameplayFogRenderContext{};
    g_runtime.gameplay_map_effect_object_assigned_units.fill(nullptr);
    g_runtime.gameplay_damage_record_links.clear();
    g_runtime.gameplay_script_hud_text.clear();
    g_runtime.gameplay_script_spawned_units.clear();
    g_runtime.gameplay_script_unhandled_spawn_requests.clear();
    g_runtime.gameplay_script_last_unit_name_append_requests.clear();
    ClearGameplayUnitNameOverrides();
    g_runtime.gameplay_end_condition_units.clear();
    g_runtime.gameplay_script_triggers_loaded = false;
    g_runtime.gameplay_script_scenario_objects_loaded = false;
    g_runtime.gameplay_script_scenario_record_sync_frame = 0xffffffffu;
    g_runtime.gameplay_script_trigger_record_index = 0xffffffffu;
    g_runtime.gameplay_script_next_unit_id = 0x80000000u;
    g_runtime.gameplay_end_condition_state = GameplayEndConditionState{};
    g_runtime.gameplay_started_player_mask = 0;
    g_runtime.gameplay_online_transition_state = GameplayOnlineTransitionState{};
    g_runtime.gameplay_result_screen_rendered = false;
    g_runtime.gameplay_leave_reset_processed = false;
    reset_default_gameplay_input_action_state();
    reset_default_gameplay_production_action_state();
    configure_default_mode1_gameplay_runtime_callbacks();
    ResetPlayerSlotRuntime(g_runtime.gameplay_player_slots);
    configure_default_mode1_gameplay_runtime_callbacks();
    append_startup_log("start-slots: runtime globals reset ok");
    bool link_lobby_start_parameters_available_for_start =
        link_lobby_startup_parameters_available();
    append_startup_log("start-slots: link params available=%s payload=%zu",
        link_lobby_start_parameters_available_for_start ? "yes" : "no",
        link_lobby_state().start_parameter_payload.size());

    P2PGameSessionStartInput input{};
    input.import_state = &g_runtime.session_runtime_import_state;
    input.active_definitions = &g_runtime.active_session_definitions;
    input.staged_definitions = &g_runtime.base_session_definitions;
    input.reference_tables = &g_runtime.unit_reference_tables;
    input.map_path = g_runtime.gameplay_session_archive_path;
    input.network_player_count = 1;
    input.copied_runtime_local_player = 0;
    input.ai_profile_mode = state.generic_ai_profile_mode != 0 ? 1 : 0;
    input.scenario_ai_profile_override = g_runtime.generic_ai_scenario_active;
    if (g_runtime.frontend_mode == 6 ||
        async_com_state().active_network_transport_mode == 6) {
        input.ai_profile_mode = 2;
    }

    std::string player_name_storage;
    if (GameplayLaunchUsesCommandLineP2P(g_runtime.gameplay_launch_source) &&
        p2p_network_launch_parameters().player_name[0] != '\0') {
        player_name_storage = p2p_network_launch_parameters().player_name.data();
    }
    else if (link_lobby_start_parameters_available_for_start) {
        const LinkLobbyState& lobby = link_lobby_state();
        const u32 local_owner = static_cast<u32>(std::clamp(
            lobby.local_player_index, 0, kLinkLobbyAvatarCount - 1));
        player_name_storage = link_lobby_startup_player_name(lobby, local_owner);
    }
    if (player_name_storage.empty()) {
        player_name_storage = default_online_local_player_name();
    }
    const char* player_name = player_name_storage.c_str();
    copy_result_text(input.players[0].name, player_name);
    input.players[0].owner_slot = 0;
    if (link_lobby_start_parameters_available_for_start) {
        append_startup_log("start-slots: populate link lobby input begin");
        populate_p2p_session_start_input_from_link_lobby(input);
        append_startup_log(
            "start-slots: populate link lobby input ok local=%lu network_players=%lu",
            static_cast<unsigned long>(input.copied_runtime_local_player),
            static_cast<unsigned long>(input.network_player_count));
    }

    append_startup_log("start-slots: import owner availability begin");
    import_default_session_owner_unit_availability();
    append_startup_log("start-slots: import owner availability ok");
    append_startup_log("start-slots: stage runtime definitions begin");
    stage_default_session_runtime_override_definitions();
    append_startup_log("start-slots: stage runtime definitions ok");

    if (g_runtime.gameplay_in_game_load_resume.pending) {
        const GameplayInGameLoadResumeState& resume =
            g_runtime.gameplay_in_game_load_resume;
        // PrepareP2PGameSessionStart also resets the reliable/replay recorder
        // and can restart DirectMusic.  An in-game load keeps those outer
        // wrappers alive, so install the captured state without invoking any
        // of those new-session side effects.
        g_runtime.p2p_session_start_state = resume.p2p_session_start;
        g_runtime.p2p_session_start_prepared =
            resume.p2p_session_start_prepared;
        append_startup_log(
            "start-slots: PrepareP2PGameSessionStart skipped for active load");
    }
    else {
        append_startup_log("start-slots: PrepareP2PGameSessionStart begin");
        g_runtime.p2p_session_start_prepared =
            PrepareP2PGameSessionStart(g_runtime.p2p_session_start_state, input);
        append_startup_log(
            "start-slots: PrepareP2PGameSessionStart ok prepared=%s network_players=%lu local=%lu",
            g_runtime.p2p_session_start_prepared ? "yes" : "no",
            static_cast<unsigned long>(
                g_runtime.p2p_session_start_state.network_player_count),
            static_cast<unsigned long>(
                g_runtime.p2p_session_start_state.local_player_slot));
        if (!link_lobby_start_parameters_available_for_start &&
            hydrate_replay_link_lobby_startup_parameters()) {
            link_lobby_start_parameters_available_for_start = true;
            append_startup_log(
                "start-slots: hydrated replay link params local=%lu",
                static_cast<unsigned long>(
                    g_runtime.p2p_session_start_state.copied_runtime_local_player));
        }
    }
    gameplay_loop_state().fixed_step_mode = 4;
    if (link_lobby_start_parameters_available_for_start) {
        const u32 local_player = std::min<u32>(
            g_runtime.p2p_session_start_state.copied_runtime_local_player,
            kPlayerSlotCount - 1);
        SetMode1ReliableLocalPlayerIndex(local_player);
        // The original uses the same DAT_00725100 local slot both for the
        // reliable channel and for SnapshotLocalGameplayChecksum's packed
        // opcode.  Keeping the input/production publishers at their reset
        // default (slot 0) makes a joining slot-1 client inject its heartbeat
        // packets into the host's channel and leaves its own channel empty.
        gameplay_input_action_state().local_player_index = local_player;
        gameplay_production_action_state().local_player_index = local_player;
    }
    SetRankerMainWindowGenericAiProfileState(
        g_runtime.p2p_session_start_state.generic_ai_profile_mode,
        g_runtime.p2p_session_start_state.scenario_ai_profile_override);
    SetRankerMainWindowNetworkAiProfileOverride(
        g_runtime.p2p_session_start_state.network_ai_profile_override);
    if (g_runtime.gameplay_in_game_load_resume.pending) {
        const GameplayInGameLoadResumeState& resume =
            g_runtime.gameplay_in_game_load_resume;
        const u32 local_player = std::min<u32>(
            resume.local_player_index, kPlayerSlotCount - 1);
        // The captured P2P wrapper was installed above.  Restore the remaining
        // outer transport/profile/local identity before any session reset or
        // owner-AI callback observes the loaded simulation.
        g_runtime.frontend_mode = resume.frontend_mode;
        SetActiveNetworkTransportMode(resume.network_transport_mode);
        SetRankerMainWindowGenericAiProfileState(
            resume.generic_ai_profile_mode,
            resume.generic_ai_scenario_active);
        SetRankerMainWindowNetworkAiProfileOverride(
            resume.network_ai_profile_override);
        SetMode1ReliableLocalPlayerIndex(local_player);
        gameplay_input_action_state().local_player_index = local_player;
        gameplay_production_action_state().local_player_index = local_player;
        mode1_gameplay_packet_dispatch_state().local_player_index = local_player;
    }

    append_startup_log("start-slots: reset startup slots begin");
    reset_default_gameplay_startup_slots(g_runtime.gameplay_startup_state);
    append_startup_log("start-slots: reset startup slots ok lifecycle=%p movement=%p",
        static_cast<void*>(g_runtime.gameplay_startup_state.lifecycle),
        g_runtime.gameplay_startup_state.lifecycle != nullptr ?
            static_cast<void*>(g_runtime.gameplay_startup_state.lifecycle->movement) :
            nullptr);
    append_startup_log("start-slots: import map startup begin");
    import_default_session_map_record_startup_state();
    append_startup_log("start-slots: import map startup ok mode=%lu active_slots=%lu",
        static_cast<unsigned long>(g_runtime.gameplay_startup_state.session_mode),
        static_cast<unsigned long>(g_runtime.gameplay_startup_state.active_slot_count));
    append_startup_log("start-slots: import scenario startup begin");
    import_default_session_scenario_record_startup_state();
    append_startup_log(
        "start-slots: import scenario startup ok victory_mask=0x%lx defeat_mask=0x%lx",
        static_cast<unsigned long>(
            g_runtime.gameplay_startup_state.scenario_victory_condition_mask),
        static_cast<unsigned long>(
            g_runtime.gameplay_startup_state.scenario_defeat_condition_mask));
    append_startup_log("start-slots: import player startup begin");
    import_default_session_player_record_startup_state();
    append_startup_log("start-slots: import player startup ok");
    append_startup_log("start-slots: import starting unit types begin");
    import_default_session_starting_unit_types();
    append_startup_log("start-slots: import starting unit types ok");
    append_startup_log("start-slots: apply pending link params begin");
    apply_pending_link_lobby_start_parameters_to_gameplay_startup();
    if (campaign_stage_session || frontend_loaded_save) {
        // Preserve the archive's 0..7 mission ordinal separately from the
        // gameplay runtime mode.  Frontend progression, including a transition
        // cheat issued after loading a campaign save, consumes this value after
        // the live session has been normalized to Use Map Setting mode 5 below.
        g_runtime.frontend_stage_session_mode =
            g_runtime.gameplay_startup_state.session_mode;
    }
    g_runtime.gameplay_startup_state.session_mode =
        ResolveGameplayMaterializationMode(
            g_runtime.gameplay_startup_state.session_mode,
            frontend_loaded_save,
            g_runtime.gameplay_in_game_load_resume.pending,
            campaign_stage_session);
    if (frontend_loaded_save ||
        g_runtime.gameplay_in_game_load_resume.pending ||
        campaign_stage_session) {
        // The campaign menu's row is a mission/progression index, not the
        // gameplay session mode stored in the extracted map record.  Original
        // faction scenarios enter the same Use Map Setting runtime used by a
        // loaded mode-5 session.  The frontend Load entry at 0x004d94a9 also
        // enters the gameplay loop without fresh-skirmish slot replacement:
        // record-5 triggers, record-7 units, resources, clock and RNG remain
        // the imported saved state.
        append_startup_log(
            "start-slots: saved-session materialization mode=5 frontend=%s active=%s campaign=%s",
            frontend_loaded_save ? "yes" : "no",
            g_runtime.gameplay_in_game_load_resume.pending ? "yes" : "no",
            campaign_stage_session ? "yes" : "no");
    }
    if (g_runtime.gameplay_in_game_load_resume.pending) {
        const u32 local_player = std::min<u32>(
            g_runtime.gameplay_in_game_load_resume.local_player_index,
            kPlayerSlotCount - 1);
        // Saved map/scenario records retain the mode they were originally
        // played in.  The original load entry nevertheless runs all reset
        // logic as mode 5, preserving record-7 units and record-19 AI state.
        g_runtime.gameplay_startup_state.session_mode = 5;
        g_runtime.gameplay_startup_state.local_owner_id = local_player;
        g_runtime.gameplay_player_slots.local_player_slot = local_player;
    }
    append_startup_log("start-slots: apply pending link params ok mode=%lu active_slots=%lu local=%lu",
        static_cast<unsigned long>(g_runtime.gameplay_startup_state.session_mode),
        static_cast<unsigned long>(g_runtime.gameplay_startup_state.active_slot_count),
        static_cast<unsigned long>(g_runtime.gameplay_startup_state.local_owner_id));
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        const GameplayScenarioOwnerSlot& slot =
            g_runtime.gameplay_startup_state.owner_slots[owner];
        append_startup_log(
            "start-slots: owner=%lu state=%lu map_slot=%lu faction=%lu tribe=%lu xy=%ld,%ld units=%lu/%lu",
            static_cast<unsigned long>(owner),
            static_cast<unsigned long>(slot.slot_state),
            static_cast<unsigned long>(slot.map_slot),
            static_cast<unsigned long>(slot.faction_id),
            static_cast<unsigned long>(slot.tribe_id),
            static_cast<long>(slot.start_x),
            static_cast<long>(slot.start_y),
            static_cast<unsigned long>(slot.starting_unit_type),
            static_cast<unsigned long>(slot.secondary_starting_unit_type));
    }
    g_runtime.gameplay_startup_state.frame_interval_index =
        ResolveGameplayInitialSpeedIndex(
            state.generic_ai_profile_mode != 0,
            replay_recording_state().playback_mode,
            g_runtime.gameplay_startup_state.frame_interval_index);
    const bool primary_camera_restored =
        restore_default_gameplay_camera_from_session_header();
    append_startup_log(
        "start-slots: primary camera restore=%s xy=%ld,%ld",
        primary_camera_restored ? "yes" : "no",
        static_cast<long>(ui_overlay_state().camera_x),
        static_cast<long>(ui_overlay_state().camera_y));
    append_startup_log("start-slots: runtime reset begin");
    run_default_gameplay_session_runtime_reset(
        g_runtime.gameplay_startup_state, player_name);
    if (replay_recording_state().playback_mode) {
        // FUN_0044f2c0 copies all eight names from the replay header table
        // (0x20-byte entries) into the live owner-name table before playback.
        // The ordinary runtime reset has just restored the map's generic
        // "Player" labels, so replace only entries actually present in the
        // replay and retain map/AI fallbacks for empty slots.
        const P2PGameSessionStartState& replay_session =
            g_runtime.p2p_session_start_state;
        for (u32 owner = 0;
             owner < g_runtime.gameplay_startup_state.owner_display_names.size() &&
             owner < replay_session.player_names.size(); ++owner) {
            if (replay_session.player_names[owner][0] != '\0') {
                g_runtime.gameplay_startup_state.owner_display_names[owner] =
                    replay_session.player_names[owner].data();
            }
        }
        // FUN_0044f2c0 seeds DAT_00722310 with the four replay observer rows.
        // The runtime reset clears the script opcode mirror, so restore the
        // startup mask only once here instead of reasserting it every frame.
        gameplay_script_trigger_state().opcode_context.resource_hud_flags |=
            g_runtime.p2p_session_start_state.setup_flags & 0x0fu;
    }
    append_startup_log(
        "start-slots: runtime reset ok active_units=%zu lifecycle_units=%zu map=%lux%lu",
        g_runtime.gameplay_movement_context.active_units.size(),
        g_runtime.gameplay_movement_context.lifecycle_units.size(),
        static_cast<unsigned long>(g_runtime.gameplay_movement_context.map.width),
        static_cast<unsigned long>(g_runtime.gameplay_movement_context.map.height));
    append_startup_log("start-slots: movement map init begin");
    initialize_default_gameplay_movement_map_from_session_records(
        g_runtime.gameplay_movement_context);
    append_startup_log("start-slots: movement map init ok map=%lux%lu cells=%zu",
        static_cast<unsigned long>(g_runtime.gameplay_movement_context.map.width),
        static_cast<unsigned long>(g_runtime.gameplay_movement_context.map.height),
        g_runtime.gameplay_movement_context.map.cells.size());
    append_startup_log("start-slots: terrain layer init begin");
    initialize_default_gameplay_terrain_layer_from_session_records();
    append_startup_log("start-slots: terrain layer init ok");
    append_startup_log("start-slots: instantiate script scenario units begin");
    instantiate_default_gameplay_script_scenario_units(gameplay_script_trigger_state());
    replay_pending_default_order_2b_active_unit_progress();
    append_startup_log("start-slots: instantiate script scenario units ok active=%zu spawned=%zu",
        g_runtime.gameplay_movement_context.active_units.size(),
        g_runtime.gameplay_script_spawned_units.size());
    const bool campaign_stage_units = campaign_stage_session;

    // The original imports record 7 into the live unit pool before
    // FUN_00426770.  Our archive decoder materializes those objects later, so
    // replay just the unit portion now: normal sessions remove owners 0..7
    // and clear only six generic slots on neutral survivors; mode 5 preserves
    // every survivor byte except disabled-player removal.  The scenario
    // frontend is a third, authored-map path: its record-7 active/lifecycle
    // chains are the mission roster and must not be converted into generic
    // skirmish starting units.
    GameplaySessionRuntimeResetState imported_unit_reset{};
    imported_unit_reset.players = &g_runtime.gameplay_player_slots;
    imported_unit_reset.lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    imported_unit_reset.session_mode =
        g_runtime.gameplay_startup_state.session_mode;
    imported_unit_reset.callbacks.on_unit_reset_or_removed =
        default_gameplay_session_unit_reset_or_removed;
    if (!campaign_stage_units) {
        ResetGameplaySessionRuntimeUnits(imported_unit_reset);
    }
    if (g_runtime.gameplay_startup_state.lifecycle != nullptr) {
        UnitLifecycleContext& lifecycle =
            *g_runtime.gameplay_startup_state.lifecycle;
        if (campaign_stage_units) {
            lifecycle.owner_unit_active_count.fill(0);
            lifecycle.owner_building_active_count.fill(0);
            lifecycle.owner_unit_score.fill(0);
            lifecycle.owner_building_score.fill(0);
            for (const UnitMovementUnit* unit :
                 g_runtime.gameplay_movement_context.active_units) {
                if (unit == nullptr || !unit->active ||
                    unit->owner_id >= kPlayerSlotCount) {
                    continue;
                }
                const UnitMovementDefinition& definition = unit->definition;
                const u32 score = definition.production_resource_cost +
                    definition.production_secondary_cost;
                if (unit->type_id < 0x60) {
                    ++lifecycle.owner_unit_active_count[unit->owner_id];
                    lifecycle.owner_unit_score[unit->owner_id] += score;
                }
                else {
                    ++lifecycle.owner_building_active_count[unit->owner_id];
                    lifecycle.owner_building_score[unit->owner_id] += score;
                }
            }
            HandleOwnerPopulationReservationTotals(lifecycle);
        }
        for (u32 owner = 0; owner < kProductionOrderOwnerCount; ++owner) {
            sync_default_owner_type_counts_from_lifecycle(
                lifecycle, owner);
        }
    }
    sync_default_gameplay_session_runtime_views_after_reset();
    append_startup_log(
        "start-slots: imported unit reset removed=%lu preserved=%lu active=%zu",
        static_cast<unsigned long>(imported_unit_reset.units_removed),
        static_cast<unsigned long>(imported_unit_reset.units_preserved),
        g_runtime.gameplay_movement_context.active_units.size());
    append_startup_log("start-slots: StartGameplaySessionFromScenarioSlots begin");
    if (campaign_stage_units) {
        StartGameplaySessionFromImportedScenarioUnits(
            g_runtime.gameplay_startup_state);
    }
    else {
        StartGameplaySessionFromScenarioSlots(
            g_runtime.gameplay_startup_state);
    }
    {
        GameplaySessionStartupState& startup =
            g_runtime.gameplay_startup_state;
        const u32 local_owner = startup.local_owner_id;
        if (!startup.local_camera_initialized &&
            local_owner < startup.owner_slots.size()) {
            u8 local_slot_state =
                g_runtime.gameplay_player_slots.lobby_slot_states[local_owner];
            if (local_slot_state == 0xffu) {
                local_slot_state = startup.owner_slots[local_owner].slot_state;
            }
            if (local_slot_state ==
                static_cast<u8>(PlayerSlotState::observer)) {
                // FUN_00426770 centers a local observer on the map midpoint
                // after importing the primary-record camera.  Unlike the
                // ordinary starting-unit path, it does not seed F1 or the HUD
                // alert marker.
                sync_default_ui_overlay_runtime_from_gameplay_state();
                UiOverlayState& overlay = ui_overlay_state();
                ConfigureGameplayUiOverlayLayout(overlay);
                const i32 center_x = static_cast<i32>(
                    (default_gameplay_session_map_width_tiles() >> 1) << 5);
                const i32 center_y = static_cast<i32>(
                    (default_gameplay_session_map_height_tiles() >> 1) << 5);
                ClampCameraToMinimapPoint(overlay, center_x, center_y);
                publish_default_ui_overlay_camera(overlay);
                startup.local_camera_initialized = true;
            }
        }
    }
    append_startup_log("start-slots: StartGameplaySessionFromScenarioSlots ok placed=%zu active=%zu",
        g_runtime.gameplay_startup_state.placed_units.size(),
        g_runtime.gameplay_movement_context.active_units.size());
    if (g_runtime.gameplay_startup_state.session_mode == 5) {
        // start_gameplay_session invokes the common fresh-session callback,
        // which zeros the reconstruction loop clock.  The original mode-5
        // loader keeps primary-record +0x140c and the reliable gate observes
        // that same frame before the next simulation tick.
        restore_default_gameplay_simulation_frame_from_session_header();
        g_runtime.gameplay_startup_state.frame_counter =
            gameplay_loop_state().simulation_frame_counter;
    }
    initialize_default_gameplay_original_unit_pool_slots();
    append_startup_log("start-slots: activate player slots begin");
    if (!campaign_stage_session) {
        activate_default_player_slots_from_active_units();
    }
    append_startup_log("start-slots: activate player slots ok active_count=%lu local=%lu",
        static_cast<unsigned long>(g_runtime.gameplay_player_slots.active_slot_count),
        static_cast<unsigned long>(g_runtime.gameplay_player_slots.local_player_slot));
    append_startup_log("start-slots: map effect init begin");
    initialize_default_map_effect_context_from_session_records();
    append_startup_log("start-slots: map effect init ok");
    append_startup_log("start-slots: fixed slot masks begin");
    apply_default_session_fixed44_player_slot_masks();
    // global_active_slot_mask is the original relation/observer work mask,
    // not a roster of everyone who entered the match.  In direct P2P mode 1
    // both human slots normally carry raw state active(0), so that work mask
    // can legitimately be zero.  Remember the immutable starting roster from
    // the raw slot states instead; the terminal subtype-0x13 exchange needs
    // it after those live states have been changed to disabled(0x14).
    g_runtime.gameplay_started_player_mask = 0;
    for (u32 owner = 0; owner < kPlayerSlotCount; ++owner) {
        const u8 slot_state =
            g_runtime.gameplay_player_slots.slot_states[owner];
        if (slot_state != static_cast<u8>(PlayerSlotState::observer) &&
            slot_state != static_cast<u8>(PlayerSlotState::disabled)) {
            g_runtime.gameplay_started_player_mask |= 1u << owner;
        }
    }
    append_startup_log("start-slots: fixed slot masks ok");
    append_startup_log("start-slots: packet reset begin");
    reset_default_mode1_packet_state_from_player_slots();
    if (g_runtime.gameplay_startup_state.session_mode == 5) {
        // ResetMode1ReliablePacketState clears the replay tick.  Restore the
        // loaded lockstep frame only after that reset so the first packet gate
        // observes the primary-record clock instead of a transient zero.
        SetMode1ReliableReplayFrameTick(
            gameplay_loop_state().simulation_frame_counter);
    }
    append_startup_log("start-slots: packet reset ok");
    append_startup_log("start-slots: owner AI refresh begin");
    refresh_default_owner_ai_target_profiles();
    append_startup_log("start-slots: owner AI refresh ok");
    append_startup_log("start-slots: end condition sync begin");
    sync_default_gameplay_end_condition_state();
    append_startup_log("start-slots: end condition sync ok");
    if (replay_recording_state().playback_mode) {
        // FUN_0044f2c0 changes DAT_00725100 to 9 only after the mode-specific
        // session initializer has used the recorded player to seed the local
        // camera and F1 bookmark. Keep startup.local_owner_id as that camera
        // seed, then publish the no-local-player sentinel for all live replay
        // visibility, feedback and render paths.
        g_runtime.gameplay_player_slots.local_player_slot =
            kNoLocalPlayerSlot;
        ApplyReplayNoLocalPlayerVisibility(
            g_runtime.gameplay_player_slots);
    }
    g_runtime.gameplay_damage_context.local_player_owner_id =
        g_runtime.gameplay_player_slots.local_player_slot;
    g_runtime.gameplay_targeting_context.active_units =
        g_runtime.gameplay_damage_context.active_units;
    g_runtime.gameplay_startup_slots_started = true;
    append_startup_log("start-slots: complete active_units=%zu damage_units=%zu",
        g_runtime.gameplay_movement_context.active_units.size(),
        g_runtime.gameplay_damage_context.active_units.size());
}

void default_frontend_stage_reset_runtime(FrontendStageFlowState& state) {
    g_runtime.frontend_stage_transition_active = true;
    g_runtime.gameplay_session_archive_path = state.active_stage_archive;
    g_runtime.gameplay_session_bundle_loaded = state.stage_bundle_loaded;
    gameplay_loop_state().simulation_frame_counter = 0;
    gameplay_loop_state().present_frame_counter = 0;

    GameplaySessionFlowState& flow = prepare_default_modal_session_flow();
    flow.generic_ai_profile_mode = 0;
    flow.close_requested = false;
    flow.process_shutdown_requested = false;
    default_gameplay_flow_start_session_from_slots(flow);

    state.current_mode = g_runtime.frontend_stage_transition_active ?
        g_runtime.frontend_stage_session_mode :
        g_runtime.gameplay_startup_state.session_mode;
    state.selected_faction_id = g_runtime.gameplay_startup_state.owner_slots[0].faction_id;
    state.active_player_slot_count = g_runtime.gameplay_player_slots.active_slot_count;
    state.runtime_tables_imported =
        !g_runtime.active_session_definitions.fixed44_records.empty() ||
        !g_runtime.active_session_definitions.unit_records.empty() ||
        !g_runtime.active_session_definitions.production_order_records.empty() ||
        !g_runtime.active_session_definitions.tail8_records.empty() ||
        !g_runtime.active_session_definitions.tail4_records.empty();
    state.non_empty_runtime_tables_imported =
        g_runtime.gameplay_startup_state.session_mode == 5 &&
        state.runtime_tables_imported;
    state.player_slot_masks_rebuilt =
        g_runtime.gameplay_session_runtime_definitions_staged;
    state.nearest_hostile_slots_selected = true;

    g_runtime.frontend_stage_session_mode = state.current_mode;
    g_runtime.frontend_stage_selected_faction = state.selected_faction_id;
}

