UnitMovementUnit* find_default_movement_unit_by_id(u32 unit_id) {
    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle == nullptr || lifecycle->movement == nullptr || unit_id == 0) {
        return nullptr;
    }

    // Mode-1 packets do not carry an abstract object id.  The original
    // handlers add packet dword +0x14 directly to the unit-pool field bases
    // (for example HandleSubtype02UnitOrderPacket at 0x004dd55f), so the wire
    // reference is the pool byte offset: runtime slot * 0x1d0.  Keep an exact
    // id lookup first for reconstruction-only objects, then accept both that
    // original wire form and the legacy scenario slot-index form used while a
    // loaded object record is being decoded.
    for (UnitMovementUnit* unit : lifecycle->movement->active_units) {
        if (unit != nullptr && unit->id == unit_id) {
            return unit;
        }
    }
    for (UnitMovementUnit* unit : lifecycle->movement->lifecycle_units) {
        if (unit != nullptr && unit->id == unit_id) {
            return unit;
        }
    }
    for (UnitMovementUnit* unit : lifecycle->movement->free_units) {
        if (unit != nullptr && unit->id == unit_id) {
            return unit;
        }
    }

    u32 runtime_slot_index = kInvalidUnitRuntimeSlotIndex;
    if (unit_id % kGameplayScenarioObjectStride == 0) {
        const u32 candidate = unit_id / kGameplayScenarioObjectStride;
        if (candidate != 0 && candidate < kGameplayScenarioObjectMaxSlots) {
            runtime_slot_index = candidate;
        }
    }
    else if (unit_id < kGameplayScenarioObjectMaxSlots) {
        runtime_slot_index = unit_id;
    }
    if (runtime_slot_index == kInvalidUnitRuntimeSlotIndex) {
        return nullptr;
    }

    for (UnitMovementUnit* unit : lifecycle->movement->active_units) {
        if (unit != nullptr && unit->runtime_slot_index == runtime_slot_index) {
            return unit;
        }
    }
    for (UnitMovementUnit* unit : lifecycle->movement->lifecycle_units) {
        if (unit != nullptr && unit->runtime_slot_index == runtime_slot_index) {
            return unit;
        }
    }
    // Mode-1 handlers address the original fixed pool directly.  They do not
    // require the referenced node to be on the active list before reading its
    // queue fields or applying a resource command.  Replay 7 makes this
    // observable when subtype 0x01 targets zeroed pool slot 211: the original
    // accepts the production request and debits its cost.
    for (UnitMovementUnit* unit : lifecycle->movement->free_units) {
        if (unit != nullptr && unit->runtime_slot_index == runtime_slot_index) {
            return unit;
        }
    }
    return nullptr;
}

bool default_ui_overlay_selection_sound_allowed(
    const UiOverlayState& state, u32 selected_owner) {
    // FUN_004e9ed0 allows the selected response for scenario/neutral owners,
    // observers, the replay-observer override, and the local owner. Ordinary
    // remote-player selections remain silent.
    return selected_owner >= 8 || state.local_player_type == 2 ||
        state.replay_observer_mode ||
        selected_owner == state.local_player_slot;
}

void default_ui_overlay_unit_selected(UiOverlayState& state,
    const UiOverlayMinimapUnit& selected_unit) {
    if (!default_ui_overlay_selection_sound_allowed(
            state, selected_unit.owner_id)) {
        return;
    }

    UnitMovementUnit* unit = find_default_movement_unit_by_id(selected_unit.unit_id);
    if (unit == nullptr) {
        return;
    }

    GameplayUnitSoundDefinition definition;
    GameplayUnitSoundBaseSlots base_slots;
    if (!resolve_default_unit_sound_profile(*unit, definition, base_slots)) {
        return;
    }
    HandleSelectedUnitVoiceCue(g_runtime.gameplay_sound, *unit, definition, base_slots);
}

