void default_unit_command_completion_effect(UnitCommandContext& context,
    UnitMovementUnit& unit) {
    if (unit.owner_id != context.local_owner_id) {
        return;
    }
    QueueGameplayHudAlertMarker(g_runtime.gameplay_hud_alert_markers, 1,
        unit.x, unit.y);
    UnitEquipmentCatalog& catalog = frontend_bootstrap_state().equipment_catalog;
    if (catalog.effects.empty()) {
        LoadUnitEquipmentCatalogFromJw210Trc(catalog);
    }
    const UnitEquipmentEffectDefinition* effect =
        FindUnitEquipmentEffect(catalog, unit.command_value);
    if (effect != nullptr && !effect->display_name.empty()) {
        // Original global completion buffers are three distinct 0x40-byte
        // regions.  Keeping this category on its own fixed buffer preserves
        // the HUD queue's pointer-identity replacement behavior.
        static std::array<char, 0x40> completion_effect_message{};
        std::snprintf(completion_effect_message.data(),
            completion_effect_message.size(), "%s%s", effect->display_name.c_str(),
            startup_platform_row(123, "Supply  "));
        QueueGameplayHudMessage(g_runtime.gameplay_hud_text,
            completion_effect_message.data());
    }
}

bool default_unit_command_advance_completion_effect(UnitCommandContext&,
    UnitMovementUnit& unit) {
    configure_default_map_effect_context();
    UnitEquipmentCatalog& catalog = frontend_bootstrap_state().equipment_catalog;
    if (catalog.effects.empty()) {
        LoadUnitEquipmentCatalogFromJw210Trc(catalog);
    }
    const UnitEquipmentEffectDefinition* definition =
        FindUnitEquipmentEffect(catalog, unit.command_value);
    const u32 period = definition != nullptr ?
        definition->completion_terrain_effect_period : 0;
    return HandleCompletionTerrainEffectSpawnTick(g_runtime.map_effect_context, unit,
        unit.command_value, period);
}

const ProductionOrderDefinition* default_production_order_definition(u32 order_id) {
    if (g_runtime.gameplay_production_catalog.definitions.empty()) {
        LoadProductionOrderCatalogFromJw210Trc(g_runtime.gameplay_production_catalog);
    }
    for (const ProductionOrderDefinition& definition :
         g_runtime.gameplay_production_catalog.definitions) {
        if (definition.id == order_id) {
            return &definition;
        }
    }
    return nullptr;
}

u32 default_unit_completion_order_id(const UnitMovementUnit& unit) {
    if ((unit.active_command_payload.state & kUnitCommandStateMask) == 0x17) {
        return static_cast<u32>(unit.active_command_payload.x);
    }
    return unit.command_value;
}

bool default_unit_command_start_completion_announcement(UnitCommandContext&,
    UnitMovementUnit& unit) {
    const ProductionOrderDefinition* definition =
        default_production_order_definition(default_unit_completion_order_id(unit));
    if (definition == nullptr) {
        return false;
    }

    ProductionOrderUnitRuntime runtime{};
    runtime.owner = unit.owner_id;
    if (!StartSelectedUnitProductionOrder(g_runtime.gameplay_production_runtime,
            *definition, runtime)) {
        return false;
    }

    unit.command_value = runtime.current_order_id;
    // FUN_004ebed0 and ProcessProductionOrderProgressTick share raw unit
    // +0x2c for upgrade progress.  For structures this is the same typed
    // union field named action_mode; work_timer is a different raw slot.
    unit.action_mode = runtime.progress_ticks;
    return true;
}

void refresh_default_order_2b_active_unit_progress() {
    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle == nullptr || lifecycle->movement == nullptr) {
        return;
    }

    UnitEffectRuntimeState& effects = g_runtime.gameplay_unit_effect_runtime;
    bool effect_runtime_synced = false;
    for (UnitMovementUnit* candidate : lifecycle->movement->active_units) {
        // ApplyProductionOrderCompletionEffects (0x0043a33b..0x0043a386)
        // walks the complete active-unit list and calls FUN_004099e0 for
        // definitions whose raw +0x49c flag has bit 1 set.  In the typed
        // catalog that flag is support_target_flags bit 1.
        if (candidate == nullptr || !candidate->active ||
            (candidate->definition.support_target_flags & 2u) == 0) {
            continue;
        }

        UnitRuntimeStatBlock stats{};
        stats.max_health = candidate->max_health;
        stats.max_secondary_value = candidate->max_secondary_value;
        stats.health = candidate->health;
        stats.stat_1c = candidate->runtime_stat_1c;
        stats.stat_20 = candidate->runtime_stat_20;
        stats.secondary_value = candidate->secondary_value;
        stats.stat_28 = candidate->runtime_stat_28;

        bool rank_up = false;
        ApplyUnitVariantProgressFromStoredValue(
            g_runtime.gameplay_production_runtime, *candidate, stats, &rank_up,
            default_gameplay_frame_random_limit);
        if (!rank_up) {
            continue;
        }

        // FUN_004099e0 publishes attachment action 0x2d after at least one
        // stored-progress rank-up through the common availability gate.
        if (!effect_runtime_synced) {
            configure_default_unit_effect_runtime_state(effects);
            sync_default_unit_effect_runtime_units(effects, *lifecycle);
            effect_runtime_synced = true;
        }
        StartAvailableSelectedUnitActionAttachmentEffect(
            effects, 0x2du, *candidate, candidate);
    }
}

void replay_pending_default_order_2b_active_unit_progress() {
    if (g_runtime.gameplay_pending_order_2b_bonus_snapshots.empty()) {
        return;
    }

    ProductionOrderRuntimeState& production =
        g_runtime.gameplay_production_runtime;
    const std::array<i32, kProductionOrderOwnerCount> final_bonuses =
        production.order_2b_bonus_totals;
    for (const std::array<i32, kProductionOrderOwnerCount>& snapshot :
         g_runtime.gameplay_pending_order_2b_bonus_snapshots) {
        production.order_2b_bonus_totals = snapshot;
        refresh_default_order_2b_active_unit_progress();
    }
    production.order_2b_bonus_totals = final_bonuses;
    g_runtime.gameplay_pending_order_2b_bonus_snapshots.clear();
}

bool default_unit_command_advance_completion_announcement(UnitCommandContext&,
    UnitMovementUnit& unit) {
    const ProductionOrderDefinition* definition =
        default_production_order_definition(default_unit_completion_order_id(unit));
    if (definition == nullptr) {
        return true;
    }

    const ProductionOrderCompletionResult result =
        AdvanceProductionOrderProgress(g_runtime.gameplay_production_runtime,
            *definition, unit.owner_id, unit.action_mode);
    if (result.order_2b_refresh_requested) {
        refresh_default_order_2b_active_unit_progress();
    }
    return result.completed;
}

