bool default_unit_command_target_in_action_range(UnitCommandContext& context,
    UnitMovementUnit& unit, UnitMovementUnit& target) {
    UnitActionContext& action_context = g_runtime.gameplay_unit_actions;
    configure_default_unit_action_context(action_context, context);
    const UnitActionTargetValidation validation =
        ValidateUnitActionTarget(action_context, unit, target);
    return validation.valid && validation.in_range;
}

bool default_unit_command_validate_action_target(UnitCommandContext& context,
    UnitMovementUnit& unit, UnitMovementUnit& target) {
    UnitActionContext& action_context = g_runtime.gameplay_unit_actions;
    configure_default_unit_action_context(action_context, context);
    return ValidateUnitActionTarget(action_context, unit, target).valid;
}

bool default_unit_command_can_follow(UnitCommandContext&,
    UnitMovementUnit&, UnitMovementUnit& target) {
    // Original follow states 0x16/0x17 test only raw target +0xa0 bits 0x84
    // (0x004c988d and 0x004c9931).  A packet can retain a valid fixed-pool
    // pointer after that slot is on the free list; active membership and the
    // command-dead high bit are not part of this predicate.
    return (target.runtime_flags & 0x84u) == 0;
}

bool default_unit_command_can_board_transport(UnitCommandContext&,
    UnitMovementUnit&, UnitMovementUnit&) {
    return true;
}

bool default_visibility_grid_ready_for_targeting() {
    const GameplayVisibilityGrid& grid = g_runtime.gameplay_visibility_grid;
    if (grid.width == 0 || grid.height == 0) {
        return false;
    }
    const std::size_t count = static_cast<std::size_t>(grid.width) * grid.height;
    return grid.current.size() >= count && grid.owner.size() >= count;
}

bool default_unit_visibility_allows_target(const UnitMovementUnit& source,
    const UnitMovementUnit& candidate) {
    if (!default_visibility_grid_ready_for_targeting()) {
        return true;
    }
    const GameplayVisibilityGrid& grid = g_runtime.gameplay_visibility_grid;
    const GameplayVisibilityUnit visibility =
        make_default_gameplay_visibility_unit(candidate);
    return CheckUnitFullActionTargetVisibility(g_runtime.gameplay_player_slots,
        grid, visibility, source.owner_id);
}

constexpr bool default_idle_target_lifecycle_class_allows(
    bool source_targets_lifecycle_class1, bool candidate_is_lifecycle_class1,
    bool candidate_special_visible) {
    // FindBestUnitTargetUsingSpatialIndex 0x004c2eaf..0x004c2f0f uses raw
    // source +0x0c bit 31 to select one side of lifecycle class 1.  A
    // candidate carrying raw runtime flag 0x40000 first runs the current-cell
    // visibility test at 0x004c2ec7/0x004c2ef5: visible candidates bypass the
    // class test for a clear source marker and are rejected for a set marker.
    if (candidate_special_visible) {
        return !source_targets_lifecycle_class1;
    }
    return source_targets_lifecycle_class1 == candidate_is_lifecycle_class1;
}

static_assert(default_idle_target_lifecycle_class_allows(false, false, false));
static_assert(!default_idle_target_lifecycle_class_allows(false, true, false));
static_assert(!default_idle_target_lifecycle_class_allows(true, false, false));
static_assert(default_idle_target_lifecycle_class_allows(true, true, false));
static_assert(default_idle_target_lifecycle_class_allows(false, false, true));
static_assert(default_idle_target_lifecycle_class_allows(false, true, true));
static_assert(!default_idle_target_lifecycle_class_allows(true, false, true));
static_assert(!default_idle_target_lifecycle_class_allows(true, true, true));

bool default_idle_target_has_special_current_visibility(
    const UnitMovementUnit& source, const UnitMovementUnit& candidate) {
    constexpr u32 kSpecialCurrentVisibilityFlag = 0x00040000u;
    if ((candidate.runtime_flags & kSpecialCurrentVisibilityFlag) == 0 ||
        source.owner_id >= 32) {
        return false;
    }

    // FUN_004d6cca (0x004d6cca) first tests the candidate owner's visibility
    // mask for the source owner, then the current visibility layer at the
    // candidate's world cell.  This is intentionally narrower than the full
    // common visibility gate below, which also checks the owner layer.
    const GameplayVisibilityUnit visibility =
        make_default_gameplay_visibility_unit(candidate);
    return CheckUnitOwnerMaskOrCurrentVisibilityBit(
        g_runtime.gameplay_player_slots, g_runtime.gameplay_visibility_grid,
        visibility, source.owner_id);
}

bool default_unit_targeting_can_target(UnitTargetingContext&,
    const UnitRecord& source, const UnitRecord& candidate) {
    UnitMovementUnit* source_unit = find_default_damage_record_unit(source);
    UnitMovementUnit* candidate_unit = find_default_damage_record_unit(candidate);
    if (source_unit == nullptr || candidate_unit == nullptr) {
        return default_unit_damage_can_damage(g_runtime.gameplay_damage_context,
            source, candidate);
    }
    // FindBestUnitTargetUsingSpatialIndex applies the owner relationship mask
    // before the common class/profile gate.  Keep automatic acquisition
    // hostile-only now that explicit action validation mirrors FUN_004c209c.
    if (source_unit->owner_id == candidate_unit->owner_id ||
        default_owners_are_related(source_unit->owner_id,
            candidate_unit->owner_id)) {
        return false;
    }
    const bool source_targets_lifecycle_class1 =
        (source_unit->area_marker_flags & 0x80000000u) != 0;
    const bool candidate_is_lifecycle_class1 =
        candidate_unit->definition.lifecycle_class == 1;
    const bool candidate_special_visible =
        default_idle_target_has_special_current_visibility(
            *source_unit, *candidate_unit);
    if (!default_idle_target_lifecycle_class_allows(
            source_targets_lifecycle_class1, candidate_is_lifecycle_class1,
            candidate_special_visible)) {
        return false;
    }
    if (!default_unit_visibility_allows_target(*source_unit, *candidate_unit)) {
        return false;
    }
    return default_unit_action_can_target(g_runtime.gameplay_unit_actions,
        *source_unit, *candidate_unit);
}

bool populate_default_spatial_target_candidates(UnitCommandContext& context,
    UnitMovementUnit& unit, UnitTargetingContext& targeting) {
    if (context.movement == nullptr) {
        return false;
    }

    // ProcessGameplayFrameTick rebuilds all four indexes once at 0x004c1183,
    // before scripts and HandleUnitSimulationListTick.  Original target
    // queries consume that frame snapshot; rebuilding here would let units
    // processed earlier in the active list change later units' candidates.
    UnitMovementUnit* candidate = QueryAllUnitsSpatialIndexAroundUnit(
        g_runtime.gameplay_unit_spatial_indexes, unit, targeting.interaction_range);
    bool queried = candidate != nullptr;
    while (candidate != nullptr) {
        GameplayDamageRecordLink* link = find_default_damage_record_link(candidate);
        if (link != nullptr) {
            targeting.spatial_candidates.push_back(&link->record);
        }
        candidate = NextAllUnitsSpatialIndexResult(
            g_runtime.gameplay_unit_spatial_indexes);
    }
    return queried;
}

UnitMovementUnit* default_unit_command_find_source_bounds_target(
    UnitCommandContext& context, UnitMovementUnit& unit) {
    if (context.movement == nullptr) {
        return nullptr;
    }

    const i32 left = unit.x + unit.definition.interaction_bounds_left;
    const i32 top = unit.y + unit.definition.interaction_bounds_top;
    const i32 right = left + unit.definition.interaction_bounds_width;
    const i32 bottom = top + unit.definition.interaction_bounds_height;
    for (UnitMovementUnit* candidate : context.movement->active_units) {
        if (candidate == nullptr || candidate == &unit || !candidate->active ||
            (candidate->runtime_flags & 0x20000084u) != 0 ||
            candidate->owner_id == unit.owner_id ||
            default_owners_are_related(unit.owner_id, candidate->owner_id)) {
            continue;
        }
        if (candidate->x < left || candidate->x > right ||
            candidate->y < top || candidate->y > bottom) {
            continue;
        }
        if (!default_unit_visibility_allows_target(unit, *candidate) ||
            !default_unit_command_can_attack(context, unit, *candidate)) {
            continue;
        }
        return candidate;
    }
    return nullptr;
}

UnitMovementUnit* default_unit_command_find_nearby_follow_target(
    UnitCommandContext& context, UnitMovementUnit& unit) {
    if (context.movement == nullptr) {
        return nullptr;
    }
    // CheckNearbyFollowCommandTarget (0x004c84b7) queries the non-terminal
    // index directly; it does not rebuild the index during active-list
    // dispatch.  Keep the same frame-start snapshot used by the original.
    return QueryNonTerminalUnitSpatialBox(g_runtime.gameplay_unit_spatial_indexes,
        unit);
}

UnitMovementUnit* default_unit_command_find_dropoff(UnitCommandContext& context,
    UnitMovementUnit& unit) {
    return context.movement != nullptr ?
        FindNearestOwnedDropoffBuilding(*context.movement, unit).unit : nullptr;
}

UnitMovementUnit* default_unit_command_find_target_impl(UnitCommandContext& context,
    UnitMovementUnit& unit, bool allow_type73_active_list_scan) {
    if (context.movement == nullptr) {
        return nullptr;
    }

    UnitActionContext& action_context = g_runtime.gameplay_unit_actions;
    configure_default_unit_action_context(action_context, context);
    rebuild_default_damage_record_links(context.movement, &unit);
    GameplayDamageRecordLink* source_link = find_default_damage_record_link(&unit);
    if (source_link == nullptr) {
        return nullptr;
    }

    UnitTargetingContext& targeting = g_runtime.gameplay_targeting_context;
    targeting = UnitTargetingContext{};
    targeting.callbacks.can_target = default_unit_targeting_can_target;
    targeting.source = &source_link->record;
    targeting.owner_relation_mask =
        unit.owner_id < context.owner_relation_masks.size()
            ? context.owner_relation_masks[unit.owner_id]
            : 0;
    targeting.active_units.reserve(g_runtime.gameplay_damage_record_links.size());
    for (GameplayDamageRecordLink& link : g_runtime.gameplay_damage_record_links) {
        targeting.active_units.push_back(&link.record);
    }
    // Original GetUnitInteractionRange (0x004c3686), consumed by
    // FindBestUnitTargetUsingSpatialIndex (0x004c2e0f), reads the definition's
    // raw archive +0x19c acquisition radius directly.  Action/support ranges
    // and their production/equipment modifiers are separate gates and must not
    // expand the candidate set before target priority is evaluated.
    targeting.interaction_range = unit.definition.target_acquisition_range;

    targeting.spatial_candidates.reserve(targeting.active_units.size());
    UnitTargetingResult result{};
    if (allow_type73_active_list_scan && unit.type_id == 0x73) {
        result = FindBestUnitTargetByActiveList(targeting);
    }
    else {
        // FUN_004c2e61 returns no target when the frame-start spatial query
        // has no head.  Only the original type-0x73 special case scans the
        // active list; falling back for every other type observes units that
        // were not present in the frame snapshot.
        if (!populate_default_spatial_target_candidates(
                context, unit, targeting)) {
            return nullptr;
        }
        result = FindBestUnitTargetUsingSpatialIndex(targeting);
    }
    return result.target != nullptr ? find_default_damage_record_unit(*result.target) :
        nullptr;
}

UnitMovementUnit* default_unit_command_find_target(UnitCommandContext& context,
    UnitMovementUnit& unit) {
    return default_unit_command_find_target_impl(context, unit, true);
}

void default_unit_command_dispatch_attack(UnitCommandContext& context,
    UnitMovementUnit& unit) {
    UnitActionContext& action_context = g_runtime.gameplay_unit_actions;
    configure_default_unit_action_context(action_context, context);
    const bool extended_runtime_table_unit = unit.type_id >= 0x60;
    const u32 command_state = unit.command_state & kUnitCommandStateMask;
    const auto pop_extended_runtime_action = [&]() {
        if (command_state == kUnitStateRuntimeAttackTarget) {
            unit.command_flags &= ~0x10u;
        }
        PopDeferredUnitCommandOrReturnIdle(context, unit);
    };
    const auto can_attack_replacement = [&](UnitMovementUnit& target) {
        return context.callbacks.can_attack_target != nullptr
            ? context.callbacks.can_attack_target(context, unit, target)
            : default_unit_command_can_attack(context, unit, target);
    };
    const auto target_in_command_action_range = [&](UnitMovementUnit& target) {
        return context.callbacks.target_in_action_range != nullptr
            ? context.callbacks.target_in_action_range(context, unit, target)
            : default_unit_command_target_in_action_range(context, unit, target);
    };
    const auto command_target_priority = [](const UnitMovementUnit& target) {
        return target.definition.target_selection_priority != 0xffffffffu
            ? target.definition.target_selection_priority
            : target.type_id;
    };
    const auto find_valid_replacement = [&]() -> UnitMovementUnit* {
        UnitMovementUnit* replacement = context.callbacks.find_target != nullptr
            ? context.callbacks.find_target(context, unit)
            : nullptr;
        return replacement != nullptr && can_attack_replacement(*replacement)
            ? replacement
            : nullptr;
    };
    const auto copy_attack_path_target = [&](UnitMovementUnit& target) {
        unit.path_target_x = target.x;
        unit.path_target_y = target.y;
    };
    const auto path_current_target_to_state =
        [&](UnitMovementUnit& target, u32 state, bool set_path_flag) {
            SetUnitCommandTarget(unit, &target);
            copy_attack_path_target(target);
            if (context.movement != nullptr) {
                ProcessUnitPathToDestination(*context.movement, unit);
            }
            unit.command_state = state;
            if (set_path_flag) {
                unit.command_flags |= 8u;
            }
        };
    const auto path_point_to_state = [&](i32 x, i32 y, u32 state, bool set_path_flag) {
        unit.target = nullptr;
        unit.command_value = 0;
        unit.path_target_x = x;
        unit.path_target_y = y;
        if (context.movement != nullptr) {
            ProcessUnitPathToDestination(*context.movement, unit);
        }
        unit.command_state = state;
        if (set_path_flag) {
            unit.command_flags |= 8u;
        }
    };
    const auto handle_lost_action_target = [&](UnitMovementUnit& target) {
        switch (command_state) {
        case kUnitStateGuardAnchorAction:
            // Original 0x004c9a66..0x004c9a89 replans while raw state is
            // still 0x1d, then writes 0x1e.  State 0x1e has metadata bit 2;
            // storing it before ProcessUnitPathToDestination suppresses the
            // original rand(80) movement-animation initialization and shifts
            // the shared gameplay RNG stream.
            SetUnitCommandTarget(unit, &target);
            copy_attack_path_target(target);
            if (context.movement != nullptr) {
                ProcessUnitPathToDestination(*context.movement, unit);
            }
            unit.command_state = kUnitStateGuardAnchorApproach;
            return true;
        case kUnitStateGuardCombatCycle:
            path_current_target_to_state(target, kUnitStateGuardPursueTarget, false);
            return true;
        case kUnitStatePatrolReturnCombat:
            path_current_target_to_state(target, kUnitStatePatrolReturnLeg, false);
            return true;
        case kUnitStatePatrolOutboundCombat:
            path_current_target_to_state(target, kUnitStatePatrolOutboundLeg, false);
            return true;
        default:
            return false;
        }
    };
    const auto handle_invalid_action_target = [&]() {
        switch (command_state) {
        case kUnitStateGuardAnchorAction:
            unit.anchor_x = unit.x;
            unit.anchor_y = unit.y;
            PopDeferredUnitCommandOrReturnIdle(context, unit);
            return true;
        case kUnitStateGuardCombatCycle:
            path_point_to_state(unit.saved_path_target_x, unit.saved_path_target_y,
                kUnitStateGuardReturnTravel, true);
            return true;
        case kUnitStatePatrolReturnCombat:
        case kUnitStatePatrolOutboundCombat:
            ResumeUnitPatrolRouteAfterCombatTargetLoss(
                context, unit, command_state);
            return true;
        default:
            return false;
        }
    };

    UnitMovementUnit* const saved_action_target = unit.target;
    const UnitActionTickResult result =
        ProcessUnitActionCycle(action_context, unit);

    if (HandleExtendedRuntimeTargetValidationActionResult(
            context, unit, result)) {
        return;
    }

    if (!extended_runtime_table_unit && command_state == kUnitStateAttackTarget) {
        // Original low-unit state 0x04 (0x004c93d1, table 0x0072d2a8)
        // distinguishes the action result and carry paths.  In particular,
        // recovery result 4 must revalidate the target because the action
        // helper deliberately skipped class/range validation while locked out.
        if (result.code == UnitActionTickCode::cycle_started ||
            result.code == UnitActionTickCode::cycle_in_progress) {
            return;
        }
        if (result.code == UnitActionTickCode::cycle_complete) {
            HandleUnitAttackCycleCompleteTargetSelection(context, unit);
            return;
        }
        if (result.carry) {
            // The action-helper carry path at 0x004c93e5 calls
            // FindBestUnitTargetUsingSpatialIndex and publishes its returned
            // candidate directly at 0x004c93f0.  It does not run the common
            // action gate a second time.  Automatic acquisition has already
            // applied the relation, class/profile and visibility filters;
            // revalidating the returned pointer here is an extra operation
            // absent from the original carry path.
            UnitMovementUnit* replacement =
                context.callbacks.find_target != nullptr
                    ? context.callbacks.find_target(context, unit)
                    : nullptr;
            if (replacement != nullptr) {
                SetUnitCommandTarget(unit, replacement);
                copy_attack_path_target(*replacement);
                return;
            }
            pop_extended_runtime_action();
            return;
        }

        // The remaining EAX=0 and EAX=4 entries both revalidate the current
        // target at 0x004c9444/0x004c9435.  EAX=0 is the no-carry transient-
        // replacement reach failure; EAX=4 is recovery/turning.
        UnitMovementUnit* current = result.target != nullptr
            ? result.target
            : unit.target;
        if (current == nullptr || !can_attack_replacement(*current)) {
            pop_extended_runtime_action();
            return;
        }
        if (target_in_command_action_range(*current)) {
            return;
        }
        if ((unit.runtime_flags & 0x8u) != 0) {
            pop_extended_runtime_action();
            return;
        }
        SetUnitCommandTarget(unit, current);
        copy_attack_path_target(*current);
        unit.command_state = kUnitStateAttackTravel;
        if (context.movement != nullptr) {
            ProcessUnitPathToDestination(*context.movement, unit);
        }
        return;
    }

    if (!extended_runtime_table_unit &&
        command_state == kUnitStateGuardCombatCycle) {
        // State 0x20 (0x004c9bdd) scans on carry/loss and results 0/1.  The
        // action-helper carry path uses the scanned replacement directly.
        // Result 0 applies the saved-target priority comparison; result 1
        // keeps the scanned target at equal priority as well.
        const bool lost_or_out_of_range =
            result.code == UnitActionTickCode::lost_target;
        const bool completed = result.code == UnitActionTickCode::cycle_complete;
        if (!lost_or_out_of_range && !completed) {
            return;
        }

        UnitMovementUnit* current = result.target != nullptr
            ? result.target
            : unit.target;
        UnitMovementUnit* replacement = find_valid_replacement();
        if (completed) {
            current = SelectGuardCombatCycleCompletedTarget(
                current, replacement);
        }
        else if (lost_or_out_of_range && !result.valid_target) {
            current = SelectGuardCombatCycleCarryTarget(
                saved_action_target, replacement);
            if (current == nullptr) {
                path_point_to_state(unit.saved_path_target_x,
                    unit.saved_path_target_y, kUnitStateGuardReturnTravel, true);
                return;
            }
        }
        else if (replacement != nullptr &&
            (current == nullptr ||
                command_target_priority(*replacement) <=
                    command_target_priority(*current))) {
            // In the exact original/rebuild five-worker attack trace, state
            // 0x20 result 0 at frame 1617 replaces worker slot 60 with the
            // equal-priority scanned slot 61.  Keeping slot 60 starts an
            // unnecessary pursue path, consumes three extra RNG calls, and
            // causes the P2P peer drop.  The live behavior is inclusive here,
            // matching the completed-cycle target selection above.
            current = replacement;
        }

        if (current == nullptr) {
            path_point_to_state(unit.saved_path_target_x,
                unit.saved_path_target_y, kUnitStateGuardReturnTravel, true);
            return;
        }
        SetUnitCommandTarget(unit, current);
        copy_attack_path_target(*current);
        if (!target_in_command_action_range(*current)) {
            path_current_target_to_state(
                *current, kUnitStateGuardPursueTarget, false);
        }
        return;
    }

    if (!extended_runtime_table_unit &&
        (command_state == kUnitStatePatrolReturnCombat ||
            command_state == kUnitStatePatrolOutboundCombat)) {
        // Patrol combat states 0x39/0x3a (0x004ca790/0x004ca818) scan only
        // for the action helper's carry/loss or result-0 paths.  Results 1..4
        // leave the current combat state untouched.
        if (result.code != UnitActionTickCode::lost_target) {
            return;
        }
        const u32 leg_state = command_state == kUnitStatePatrolReturnCombat
            ? kUnitStatePatrolReturnLeg
            : kUnitStatePatrolOutboundLeg;
        // FindBestUnitTargetUsingSpatialIndex returns the raw candidate before
        // FUN_004c1e85 applies its action/range result.  In particular,
        // distance_check_mode 1 must retain and approach that candidate.
        UnitMovementUnit* replacement = context.callbacks.find_target != nullptr
            ? context.callbacks.find_target(context, unit)
            : nullptr;
        if (replacement == nullptr) {
            ResumeUnitPatrolRouteAfterCombatTargetLoss(
                context, unit, command_state);
            return;
        }
        SetUnitCommandTarget(unit, replacement);
        copy_attack_path_target(*replacement);
        if (!target_in_command_action_range(*replacement)) {
            path_current_target_to_state(*replacement, leg_state, false);
        }
        return;
    }

    if (result.code != UnitActionTickCode::lost_target) {
        if (extended_runtime_table_unit && unit.type_id == 0x73 &&
            result.target != nullptr &&
            (result.code != UnitActionTickCode::cycle_started &&
                result.code != UnitActionTickCode::cycle_in_progress) &&
            (result.target->runtime_flags & 0x20000u) != 0) {
            pop_extended_runtime_action();
        }
        if (command_state == kUnitStateGuardCombatCycle &&
            result.code == UnitActionTickCode::cycle_complete) {
            UnitMovementUnit* current = unit.target;
            UnitMovementUnit* replacement = context.callbacks.find_target != nullptr
                ? context.callbacks.find_target(context, unit)
                : nullptr;
            if (replacement != nullptr && can_attack_replacement(*replacement) &&
                (current == nullptr ||
                    command_target_priority(*replacement) <
                        command_target_priority(*current))) {
                SetUnitCommandTarget(unit, replacement);
                copy_attack_path_target(*replacement);
                current = replacement;
            }
            if (current != nullptr && !target_in_command_action_range(*current)) {
                path_current_target_to_state(
                    *current, kUnitStateGuardPursueTarget, false);
            }
        }
        return;
    }

    if (result.valid_target && result.target != nullptr) {
        if (handle_lost_action_target(*result.target)) {
            return;
        }
        if (extended_runtime_table_unit || (unit.runtime_flags & 0x8u) != 0) {
            pop_extended_runtime_action();
            return;
        }
        SetUnitCommandTarget(unit, result.target);
        copy_attack_path_target(*result.target);
        unit.command_state = kUnitStateAttackTravel;
        unit.command_flags |= 8;
        if (context.movement != nullptr) {
            ProcessUnitPathToDestination(*context.movement, unit);
        }
        return;
    }

    if (handle_invalid_action_target()) {
        return;
    }
    PopDeferredUnitCommandOrReturnIdle(context, unit);
}

UnitMovementUnit* take_default_free_unit_head(UnitMovementContext& movement) {
    if (movement.free_units.empty()) {
        return nullptr;
    }
    UnitMovementUnit* unit = movement.free_units.front();
    movement.free_units.erase(movement.free_units.begin());
    if (unit != nullptr) {
        // InitializePlacedUnitFromMapSlot clears raw +0x08 for every new
        // fixed-pool generation. The UI vectors use the stable pool id, so
        // forget the previous occupant before a later render mirror can make
        // the newly produced unit inherit its selection/control group.
        ForgetUiOverlayUnitIdentityForNewGeneration(
            ui_overlay_state(), unit->id);
    }
    return unit;
}

void return_default_free_unit_head(UnitMovementContext& movement,
    UnitMovementUnit* unit) {
    if (unit == nullptr) {
        return;
    }
    auto remove_unit = [unit](std::vector<UnitMovementUnit*>& units) {
        units.erase(std::remove(units.begin(), units.end(), unit), units.end());
    };
    remove_unit(movement.active_units);
    remove_unit(movement.lifecycle_units);
    remove_unit(movement.free_units);
    unit->active = false;
    movement.free_units.insert(movement.free_units.begin(), unit);
}

UnitMovementUnit* default_unit_command_create_unit(UnitCommandContext&,
    UnitMovementUnit& source, u32 type_id, i32 x, i32 y) {
    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle == nullptr || lifecycle->movement == nullptr) {
        return nullptr;
    }

    UnitMovementContext& movement = *lifecycle->movement;
    UnitMovementUnit* unit = nullptr;
    std::unique_ptr<UnitMovementUnit> owned_unit;
    if (!movement.free_units.empty()) {
        unit = take_default_free_unit_head(movement);
    }
    else {
        owned_unit = std::make_unique<UnitMovementUnit>();
        unit = owned_unit.get();
    }
    if (unit == nullptr) {
        return nullptr;
    }

    const u32 unit_id = unit->id != 0 ? unit->id :
        g_runtime.gameplay_script_next_unit_id++;
    const u32 runtime_slot_index =
        unit->runtime_slot_index != kInvalidUnitRuntimeSlotIndex ?
            unit->runtime_slot_index : unit_id;
    const i32 residual_next_path_x = unit->next_path_x;
    const i32 residual_next_path_y = unit->next_path_y;

    // HandleFreeUnitActivation changes only the intrusive list links.  Seed
    // the typed initializer from the previous fixed-pool generation so every
    // raw field that 0x004cf229 does not write remains intact.
    UnitMovementUnit initialized = *unit;
    const u32 saved_terrain_class = lifecycle->placement_terrain_class_override;
    const bool saved_terrain_override =
        lifecycle->placement_terrain_class_override_enabled;
    // HandleUnitProductionSpawnCycle samples DAT_00e99e74 at the producer's
    // origin (0x004ce092..0x004ce0b4), then searches from the definition
    // +0x2410/+0x2414 exit point.  Sampling the exit point instead can switch
    // placement class when a producer borders water or another terrain band.
    if ((source.command_state & kUnitCommandStateMask) ==
            kUnitStateProductionSpawnCycle && source.x >= 0 && source.y >= 0) {
        lifecycle->placement_terrain_class_override = GetPlacementTerrainClass(
            *lifecycle, static_cast<u32>(source.x) >> 5,
            static_cast<u32>(source.y) >> 5);
        lifecycle->placement_terrain_class_override_enabled = true;
    }
    const bool placed = InitializePlacedUnitFromMapSlot(*lifecycle, initialized,
        type_id, source.owner_id, x, y);
    lifecycle->placement_terrain_class_override = saved_terrain_class;
    lifecycle->placement_terrain_class_override_enabled = saved_terrain_override;
    if (!placed) {
        if (owned_unit == nullptr) {
            return_default_free_unit_head(movement, unit);
        }
        return nullptr;
    }

    initialized.next_path_x = residual_next_path_x;
    initialized.next_path_y = residual_next_path_y;
    initialized.saved_path_target_x = residual_next_path_x;
    initialized.saved_path_target_y = residual_next_path_y;

    initialized.id = unit_id;
    initialized.runtime_slot_index = runtime_slot_index;
    *unit = initialized;
    unit->id = unit_id;
    unit->runtime_slot_index = runtime_slot_index;
    unit->active = true;
    unit->linked_unit = unit;
    refresh_default_unit_definition_runtime_fields(*unit);
    if (owned_unit != nullptr) {
        g_runtime.gameplay_script_spawned_units.push_back(std::move(owned_unit));
    }
    default_gameplay_startup_unit_placed(*unit);
    sync_default_owner_type_count_for_unit(*unit);
    return unit;
}

bool dispatch_default_unit_command_action_effect(UnitMovementUnit& source,
    UnitMovementUnit* target, u32 action_id, i32 world_x, i32 world_y,
    u32 effect_mode_override = std::numeric_limits<u32>::max(),
    UnitEffectRuntime** created_effect = nullptr) {
    if (created_effect != nullptr) {
        *created_effect = nullptr;
    }
    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle == nullptr || action_id >= 0x2e) {
        return false;
    }

    UnitEffectRuntimeState& effects = g_runtime.gameplay_unit_effect_runtime;
    configure_default_unit_effect_runtime_state(effects);
    sync_default_unit_effect_runtime_units(effects, *lifecycle);

    const UnitEffectDefinition* definition =
        find_default_unit_effect_definition(effects, 0x3du + action_id);
    if (definition == nullptr) {
        return false;
    }

    // FUN_004ef7b8 rejects these two commands before pool allocation or
    // resource debit.
    if (action_id == 5 && target != nullptr &&
        (target->runtime_flags & 0x84u) != 0) {
        return false;
    }
    if (action_id == 0x17) {
        world_x &= ~0x1f;
        world_y &= ~0x1f;
        constexpr u32 kHurdleUnitType = 0x7d;
        // FUN_004ef7b8 calls the UI footprint predicate
        // FUN_004dba30/FUN_004dbae2 here, not the authoritative lifecycle
        // placement helper.  The UI predicate reads five distinct map
        // layers: last-visible terrain (E59E74), authoritative terrain
        // (F19E74), terrain class (E99E74), remembered route state (798D40)
        // and current visibility (758D40).  Combining the lifecycle check
        // with only bit 0x10000000 accepted cells that the original rejects
        // when the last-visible terrain layer is blocked, so one P2P peer
        // created the hurdle and consumed two RNG calls while the other did
        // not.  Refresh and use the existing exact UI-layer mirror.
        GameplayProductionActionState& placement_gate =
            gameplay_production_action_state();
        sync_default_gameplay_production_action_units(
            placement_gate, ui_overlay_state());
        // A reconstructed local caster was pre-gated against every active
        // participant before its command was published, so repeat that exact
        // all-owner decision on its simulation path.  For a command received
        // from an original peer, project only the source owner's explored
        // layer: that reproduces the original caster's local decision while
        // avoiding the receiver's unrelated local fog state.
        const u32 authority_mask = ResolvePreviewPlacementAuthorityMask(
            placement_gate.local_player_index, source.owner_id,
            placement_gate.preview_placement_required_owner_mask);
        const bool hurdle_placement_allowed =
            CheckPreviewProductionPlacementFootprintGateCellsForOwnerMask(
                placement_gate, kHurdleUnitType, world_x, world_y, source.id,
                authority_mask);
        if (!hurdle_placement_allowed) {
            return false;
        }
    }

    const auto ordinary_cost_available = [&]() {
        return source.secondary_value >= definition->action_secondary_cost &&
            source.health > definition->action_source_health_cost;
    };
    const auto debit_ordinary_cost = [&]() {
        source.secondary_value -= definition->action_secondary_cost;
        source.health -= definition->action_source_health_cost;
    };
    const auto scaled_effect_amount = [&]() {
        const u32 bonus = CalculateUnitVariantScaledBonus61c(source);
        return definition->damage_amount + static_cast<u32>(
            (static_cast<u64>(definition->damage_amount) * bonus) / 100u);
    };

    // Shield refresh is a pre-allocation special case.  The original can
    // refresh an existing shield even when the effect pool has no free node.
    if (action_id == 2 && target != nullptr &&
        (target->runtime_flags & 0x100u) != 0) {
        if (UnitEffectRuntime* shield =
                default_unit_effect_from_original_slot_offset_allow_inactive(
                    effects, target->linked_effect_slot_offset)) {
            if (!ordinary_cost_available()) {
                return false;
            }
            debit_ordinary_cost();
            shield->amount = scaled_effect_amount();
            return true;
        }
    }

    // Meteo and Rise Death have allocation/RNG ordering that is observably
    // different from the ordinary one-effect path.  Keep the production
    // callback and the deterministic regression harness on the same helper.
    if (action_id == 9 || action_id == 0x0f) {
        return DispatchSelectedUnitScatterActionEffect(effects, action_id,
            source, world_x, world_y, default_selected_action_random_limit);
    }

    // FUN_004ef7b8/0x004ef7c8 first looks for an equipped one-shot whose
    // JW2_10 +0x260 attachment id equals this action.  Such an item replaces
    // the ordinary JW2_11 +0x1e0/+0x1e4 health/secondary costs and is consumed
    // before the initializer table runs.
    i32 consumed_item_slot = -1;
    if (effects.equipment_catalog != nullptr) {
        for (std::size_t slot = 0; slot < source.item_slots.size(); ++slot) {
            const u32 item_id = source.item_slots[slot];
            if (item_id == 0) {
                continue;
            }
            const UnitEquipmentEffectDefinition* item =
                FindUnitEquipmentEffect(*effects.equipment_catalog, item_id);
            if (item != nullptr && item->attachment_definition_id == action_id) {
                consumed_item_slot = static_cast<i32>(slot);
                break;
            }
        }
    }
    if (consumed_item_slot < 0 && !ordinary_cost_available()) {
        return false;
    }

    UnitEffectRuntime* effect = AllocateUnitEffectSlot(effects);
    if (effect == nullptr) {
        return false;
    }

    if (consumed_item_slot < 0) {
        debit_ordinary_cost();
    }
    else {
        const std::size_t slot = static_cast<std::size_t>(consumed_item_slot);
        source.item_slots[slot] = 0;
        if (slot < source.equipment_slots.size()) {
            source.equipment_slots[slot] = 0;
        }
    }

    if (!DispatchSelectedUnitActionEffect(effects, *effect, action_id, source,
            target, world_x, world_y)) {
        ReleaseUnitEffectSlot(effects, *effect);
        return false;
    }
    if (effect_mode_override != std::numeric_limits<u32>::max()) {
        effect->flags = effect_mode_override;
    }
    if (created_effect != nullptr) {
        *created_effect = effect;
    }
    return true;
}

