void default_unit_command_reserved_tile_impact_frame(UnitCommandContext&,
    UnitMovementUnit& unit) {
    constexpr u32 kReservedTileAttachmentActionId = 0x26;

    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    if (lifecycle == nullptr) {
        return;
    }

    UnitEffectRuntime* effect = nullptr;
    (void)start_default_unit_command_ability_attachment_effect(
        unit, nullptr, kReservedTileAttachmentActionId, &effect);
    if (effect != nullptr) {
        effect->closest_distance = 0;
    }

    effect = nullptr;
    (void)start_default_unit_command_ability_attachment_effect(
        unit, nullptr, kReservedTileAttachmentActionId, &effect);
    if (effect != nullptr) {
        effect->x = unit.destination_x;
        effect->y = unit.destination_y + 0x11;
        effect->closest_distance = 1;
    }

    // The executing action is independent of the two best-effort startup
    // attachments.  Its raw mode/flags field is forced to one on success.
    (void)dispatch_default_unit_command_action_effect(unit, nullptr, 0x2c,
        unit.destination_x, unit.destination_y, 1u);
}

bool default_unit_command_reserved_tile_work_complete(UnitCommandContext&,
    UnitMovementUnit& unit) {
    constexpr u32 kReservedTileCompletionActionId = 0x26;

    UnitLifecycleContext* lifecycle = g_runtime.gameplay_startup_state.lifecycle;
    UnitMovementUnit* target = unit.target;
    if (lifecycle == nullptr || target == nullptr) {
        unit.reserved_tile_effect = nullptr;
        unit.reserved_tile_effect_slot_offset = 0;
        return false;
    }

    // FUN_004cb255 reaches action 0x26 through FUN_004ef7b8.  Keep its
    // equipped one-shot/resource gate even though the stock action costs zero.
    UnitEffectRuntime* effect = nullptr;
    if (!dispatch_default_unit_command_action_effect(unit, target,
            kReservedTileCompletionActionId, unit.path_target_x,
            unit.path_target_y, std::numeric_limits<u32>::max(), &effect) ||
        effect == nullptr) {
        unit.reserved_tile_effect = nullptr;
        unit.reserved_tile_effect_slot_offset = 0;
        return false;
    }

    // FUN_004cb255 copies the harvested value from raw unit +0x4c before it
    // overwrites that union with the allocated effect-pool offset.
    effect->amount = unit.cargo_amount;
    unit.reserved_tile_effect = effect;
    unit.reserved_tile_effect_slot_offset =
        default_unit_effect_original_slot_offset(
            g_runtime.gameplay_unit_effect_runtime, effect);
    return true;
}

u32 default_unit_command_ability_secondary_cost(UnitCommandContext&,
    UnitMovementUnit&, UnitMovementUnit*, u32 ability_id) {
    if (jw211_runtime_catalog_state().records.empty()) {
        LoadJw211RuntimeCatalog();
    }
    const AuxiliaryRuntimeCatalogState& catalog = jw211_runtime_catalog_state();
    if (ability_id >= catalog.records.size()) {
        return 1;
    }

    const AuxiliaryRuntimeCatalogRecord& record = catalog.records[ability_id];
    return read_runtime_catalog_u32(record.definition_bytes,
        kJw211ActionSecondaryCostOffset, 1);
}

i32 default_unit_command_ability_target_health_delta(UnitCommandContext&,
    UnitMovementUnit&, UnitMovementUnit*, u32 ability_id) {
    if (jw211_runtime_catalog_state().records.empty()) {
        LoadJw211RuntimeCatalog();
    }
    const AuxiliaryRuntimeCatalogState& catalog = jw211_runtime_catalog_state();
    if (ability_id >= catalog.records.size()) {
        return 1;
    }

    const AuxiliaryRuntimeCatalogRecord& record = catalog.records[ability_id];
    return -read_runtime_catalog_i32(record.definition_bytes,
        kJw211ActionTargetHealthDeltaOffset, -1);
}

bool default_unit_command_ability_updates_direction(UnitCommandContext&,
    UnitMovementUnit&, UnitMovementUnit*, u32 ability_id) {
    if (jw211_runtime_catalog_state().records.empty()) {
        LoadJw211RuntimeCatalog();
    }
    const AuxiliaryRuntimeCatalogState& catalog = jw211_runtime_catalog_state();
    if (ability_id >= catalog.records.size()) {
        return true;
    }

    const AuxiliaryRuntimeCatalogRecord& record = catalog.records[ability_id];
    return read_runtime_catalog_u32(record.definition_bytes,
        kJw211ActionDirectionModeOffset, 1) != 0;
}

